    /// Group 17 (17a) — a smart consumer is a SUPERSET of a standard one: its
    /// user↔agent conversation still runs the standard personal-memory
    /// pipeline. The project (smart) wiki it authors via `wiki_admin_*` is
    /// never an ingest destination (the `!w.smart` routing filter), so a
    /// conversational capture lands in the user's standard personal wiki. No
    /// `consumer_class` gate exists on this path — `IngestRequest` carries no
    /// such field; the only thing that historically kept the conversation out
    /// of personal memory was the skill instruction (revised in
    /// `smart-consumer`). This proves the engine was already a superset.
    #[tokio::test]
    async fn smart_consumer_conversation_ingests_into_standard_not_smart_wiki() {
        let (dir, tree, pool) = setup_workdir().await;
        // alice also owns a smart project wiki (the kind a smart consumer
        // authors via wiki_admin_push), alongside her standard wiki-user wiki.
        let smart_meta = "---\nwiki_id: proj\nwiki_type: wiki-companion\nparent_wiki_id: null\n\
                          slug: proj\ntitle: Proj\nacl_default: 'user:alice'\nsmart: true\n---\n";
        let (cmeta, _) =
            WikiMeta::parse(Path::new("_meta.md"), smart_meta).expect("smart-wiki meta");
        crate::wiki::write_wiki_dir(&tree, &cmeta, false).expect("create proj");

        // A conversational, durable personal fact. `requested_container: true`
        // files it live into `fact_index`, so the destination wiki is easy to
        // assert.
        let json = "{\"intent\":\"capture\",\"extractions\":[{\
            \"target_wiki_id\":\"alice\",\"target_page\":\"preferenze.md\",\
            \"subject_id\":\"user:alice\",\"body\":\"alice prefers tabs over spaces\",\
            \"fact_type\":\"preference\",\"topics\":[\"style\"],\"requested_container\":true}],\
            \"suggested_seed\":\"Noted.\"}";
        let llm = FakeLlmBackend::new("fake", json);
        let policy = IngestPolicy::default();
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req("I prefer tabs over spaces", "alice"),
            &policy,
        )
        .await
        .expect("ingest");
        assert_eq!(resp.intent, IntentKind::Capture);
        let row = fact_index::find_by_id(&pool, &resp.capture_id.expect("capture_id"))
            .await
            .expect("find")
            .expect("inserted row");
        assert_eq!(
            row.wiki_id, "alice",
            "the conversation lands in the standard personal wiki, never the smart project wiki"
        );
        drop(dir);
    }

    /// Group 17 (17e) — length is NEVER the fact-extraction gate. A durable
    /// fact buried in a long body must still be captured, and the FULL message
    /// must reach the classifier (`build_prompt` appends `current_message`
    /// untruncated). Storing the verbatim long body is a separate decision
    /// (document-import on explicit request); the classifier still scans for
    /// facts. This guards against a future truncation regression on the
    /// classifier input.
    #[tokio::test]
    async fn ingest_long_message_still_scans_for_buried_fact() {
        let (dir, tree, pool) = setup_workdir().await;
        let buried = "Please remember: my dentist appointment is Thursday at 17:00.";
        let filler = "fix the build, rerun the tests, bump the lints, ".repeat(60);
        let long = format!("{filler}\n\n{buried}\n\n{filler}");
        let json = "{\"intent\":\"capture\",\"extractions\":[{\
            \"target_wiki_id\":\"alice\",\"target_page\":\"preferenze.md\",\
            \"subject_id\":\"user:alice\",\"body\":\"alice has a dentist appointment Thursday at 17:00\",\
            \"fact_type\":\"plan\",\"topics\":[\"appointments\"],\"requested_container\":true}],\
            \"suggested_seed\":\"Noted.\"}";
        let llm = FakeLlmBackend::new("fake", json);
        let policy = IngestPolicy::default();
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req(&long, "alice"),
            &policy,
        )
        .await
        .expect("ingest");
        assert_eq!(resp.intent, IntentKind::Capture);
        assert!(
            resp.capture_id.is_some(),
            "the buried fact must be captured"
        );
        let prompt = llm.last_prompt().expect("classifier prompt recorded");
        assert!(
            prompt.contains(buried),
            "the buried sentence must reach the classifier untruncated — length never gates extraction"
        );
        drop(dir);
    }

    /// Group 17 (17f) — a conversation-borne dated commitment becomes a fact
    /// with a validity window and surfaces in the due-soon recall slot. It is
    /// the same mechanism, reached from a conversational turn: the
    /// classifier resolves the date and emits `valid_to`, capture persists it
    /// (here on the live `requested_container` path), and `recall_due_soon`
    /// pulls it within the horizon.
    #[tokio::test]
    async fn ingest_dated_commitment_lands_in_due_soon_slot() {
        let (dir, tree, pool) = setup_workdir().await;
        let valid_to = "2026-06-12T17:00:00Z";
        let json = format!(
            "{{\"intent\":\"capture\",\"extractions\":[{{\
            \"target_wiki_id\":\"alice\",\"target_page\":\"preferenze.md\",\
            \"subject_id\":\"user:alice\",\"body\":\"alice has a dentist appointment Thursday at 17:00\",\
            \"fact_type\":\"plan\",\"topics\":[\"appointments\"],\"requested_container\":true,\
            \"valid_from\":\"2026-06-10T08:00:00Z\",\"valid_to\":\"{valid_to}\"}}],\
            \"suggested_seed\":\"Noted.\"}}"
        );
        let llm = FakeLlmBackend::new("fake", &json);
        let policy = IngestPolicy::default();
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req("giovedì alle 17 dal dentista", "alice"),
            &policy,
        )
        .await
        .expect("ingest");
        let row = fact_index::find_by_id(&pool, &resp.capture_id.expect("capture_id"))
            .await
            .expect("find")
            .expect("inserted row");
        assert_eq!(
            row.valid_to.as_deref(),
            Some(valid_to),
            "the conversation-borne dated commitment carries its validity window"
        );
        let now = chrono::DateTime::parse_from_rfc3339("2026-06-10T08:00:00Z")
            .unwrap()
            .with_timezone(&chrono::Utc);
        let hits = recall::recall_due_soon(
            &pool,
            &SenderContext::user("alice"),
            now,
            chrono::Duration::days(7),
            10,
        )
        .await
        .expect("due soon");
        assert!(
            hits.iter().any(|h| h.text.contains("dentist")),
            "the dated commitment surfaces in the due-soon slot"
        );
        drop(dir);
    }

    /// An extraction the classifier marks
    /// as an engine-rule (a standing governance directive) is appended to the
    /// sender's `@rules.md` as prose and is NEVER filed in `fact_index` or the
    /// capture buffer. `setup_workdir` does not seed a `@rules.md`, so this also
    /// exercises the missing-file path (the helper seeds from the default body).
    #[tokio::test]
    async fn ingest_engine_rule_appends_to_rules_md_not_fact_index() {
        let (dir, tree, pool) = setup_workdir().await;
        let json = "{\"intent\":\"capture\",\"extractions\":[{\
            \"engine_rule\":true,\"fact_type\":\"rule\",\
            \"body\":\"Health information is always private; never share it with any group.\"}],\
            \"suggested_seed\":\"Got it.\"}";
        let llm = FakeLlmBackend::new("fake", json);
        let policy = IngestPolicy::default();
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req(
                "la mia salute è sempre privata, non condividerla mai",
                "alice",
            ),
            &policy,
        )
        .await
        .expect("ingest");

        assert_eq!(resp.intent, IntentKind::Capture);
        // A rule is not a fact: nothing filed, nothing buffered, no anchor id.
        assert!(resp.capture_id.is_none(), "engine-rule files no fact");
        assert_eq!(
            fact_index::count_active_in_wiki(&pool, "alice")
                .await
                .unwrap(),
            0,
            "engine-rule must not write a fact_index row"
        );
        assert_eq!(
            capture_buffer::count_buffered(&pool).await.unwrap(),
            0,
            "engine-rule must not buffer a capture"
        );

        // It landed in alice's rules.md as prose, read straight back next turn.
        let rules = std::fs::read_to_string(
            tree.wikis_dir()
                .join("alice")
                .join(crate::wiki::RULES_FILENAME),
        )
        .expect("@rules.md written");
        assert!(
            rules
                .contains("- Health information is always private; never share it with any group."),
            "rule appended as a bullet; body was:\n{rules}"
        );
        drop(dir);
    }

    /// A behaviour-rule (how the agent should converse) is filed in the
    /// CALLING AGENT's own wiki, OWNED by the served user — never in the user's
    /// fact memory. The consumer id threads from the request through
    /// `consumers.system_user_id` to the target wiki, and the rule surfaces in
    /// the same turn's recall block returned to the consumer.
    #[tokio::test]
    async fn ingest_behaviour_rule_lands_in_agent_wiki_owned_by_the_user() {
        let (dir, tree, pool) = setup_agent_workdir().await;
        let json = "{\"intent\":\"capture\",\"extractions\":[{\
            \"behaviour_rule\":true,\"behaviour_scope\":\"per-user\",\
            \"body\":\"Rispondi sempre in modo conciso.\"}],\
            \"suggested_seed\":\"Ok.\"}";
        let llm = FakeLlmBackend::new("fake", json);
        let policy = IngestPolicy::default();
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req_consumer("rispondimi sempre conciso", "alice", "botdeploy"),
            &policy,
        )
        .await
        .expect("ingest");

        assert_eq!(resp.intent, IntentKind::Capture);
        // The user's own wiki stays clean — a behaviour rule is not a fact
        // about the user.
        assert_eq!(
            fact_index::count_active_in_wiki(&pool, "alice")
                .await
                .unwrap(),
            0,
            "behaviour rule must not land in the user's wiki"
        );
        // It lands in the agent's wiki, attributed to the user who dictated it.
        let rows = fact_index::find_by_filters(
            &pool,
            &fact_index::FactFilters {
                wiki_id: Some("samvisebot".to_owned()),
                ..Default::default()
            },
        )
        .await
        .unwrap();
        assert_eq!(
            rows.len(),
            1,
            "exactly one behaviour rule in the agent wiki"
        );
        assert_eq!(rows[0].text, "Rispondi sempre in modo conciso.");
        assert_eq!(
            rows[0].subject_id,
            Principal::User("alice".into()),
            "the rule is OWNED by the user who dictated it (subject-scoped dedup keeps users' rules distinct)"
        );
        assert_eq!(
            rows[0].sender_id,
            Some(Principal::User("alice".into())),
            "subject is the user, so there is no SEPARATE sender — sender is materialized to the subject, never the agent"
        );
        assert_eq!(
            resp.capture_id.as_ref(),
            Some(&rows[0].fact_id),
            "the filed behaviour rule is the turn's anchor id"
        );
        assert!(
            resp.rules
                .as_deref()
                .unwrap_or_default()
                .contains("Rispondi sempre in modo conciso."),
            "the behaviour rule surfaces in the dedicated `rules` field, \
             not in the recalled-memory snippet"
        );
        assert!(
            resp.context_snippet.is_none(),
            "a pure behaviour-rule turn surfaces no recalled memory in context_snippet"
        );
        // The rule lands on the agent wiki's `@rules.md` page.
        assert!(
            rows[0].source_path.ends_with("@rules.md")
                && !rows[0].source_path.ends_with("behaviour_rules.md"),
            "behaviour rule stored on rules.md, was: {}",
            rows[0].source_path
        );
        drop(dir);
    }

    /// «And I mean with every assistant, not just this one»: the rule already
    /// set on the agent reaches the person's OWN rules page, word for word.
    ///
    /// Promotion restates the directive on purpose — the words are the same
    /// and the scope is not — so the write-time dedup must compare it against
    /// the page it is headed for and no other
    /// ([`crate::capture::ChannelScope`]). Folded into the agent's copy, the
    /// person's own rules page stays empty while the turn reports a rule
    /// filed, and every other assistant serving them never hears the rule.
    ///
    /// The ADDITIVE half of the widening, which is the half that meets the
    /// dedup: [`widening_a_directive_to_every_assistant_files_it_in_the_senders_own_memory`]
    /// covers the road where the classifier names the rule it is replacing,
    /// and a supersede writes without asking the dedup anything. The
    /// classifier is only shown the rules in force on THIS consumer, so a
    /// promotion said to a second assistant has no id to name and arrives
    /// here.
    #[tokio::test]
    async fn a_rule_widened_to_every_assistant_reaches_the_users_own_rules_page() {
        const RULE: &str = "Answer concisely: the answer without the preamble.";
        let (dir, tree, pool) = setup_agent_workdir().await;
        let policy = IngestPolicy::default();
        let per_user = format!(
            "{{\"intent\":\"capture\",\"extractions\":[{{\
             \"behaviour_rule\":true,\"behaviour_scope\":\"per-user\",\
             \"body\":\"{RULE}\"}}],\"suggested_seed\":\"Ok.\"}}"
        );
        let narrow = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", &per_user),
            None,
            req_consumer("keep it short with me", "alice", "botdeploy"),
            &policy,
        )
        .await
        .expect("ingest")
        .capture_id
        .expect("the per-user rule is filed");

        let widened = per_user.replace("per-user", "user-global");
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", &widened),
            None,
            req_consumer("and I mean with every assistant", "alice", "botdeploy"),
            &policy,
        )
        .await
        .expect("ingest");

        let own = fact_index::find_by_filters(
            &pool,
            &fact_index::FactFilters {
                wiki_id: Some("alice".to_owned()),
                ..Default::default()
            },
        )
        .await
        .unwrap();
        assert_eq!(
            own.len(),
            1,
            "the widened rule must be written on the person's own rules page"
        );
        assert_eq!(own[0].text, RULE);
        assert!(own[0].source_path.ends_with("@rules.md"));
        assert_eq!(
            resp.capture_id.as_ref(),
            Some(&own[0].fact_id),
            "the turn's anchor id is the rule that was written"
        );
        // And the narrow copy is retired onto it: widening MOVES a rule. Left
        // alive it is served beside the wide one on the very assistant it was
        // set on, and «drop that rule» would close one of the two.
        let retired = fact_index::find_by_id(&pool, &narrow)
            .await
            .expect("find")
            .expect("the row stays: retiring a rule is never deleting it");
        assert_eq!(
            retired.superseded_by.as_ref(),
            Some(&own[0].fact_id),
            "the narrower copy is retired onto the widened rule"
        );
        assert!(
            retired.valid_to.is_some(),
            "so the rules channel stops serving it"
        );
        assert_eq!(
            fact_index::count_active_in_wiki(&pool, "samvisebot")
                .await
                .unwrap(),
            0,
            "nothing of the rule is left in force on the one assistant it was set on"
        );
        drop(dir);
    }

    /// Widening said to a SECOND assistant still retires the copy sitting on
    /// the first, which is the case the classifier cannot help with.
    ///
    /// It is only ever shown the rules in force on the consumer it is talking
    /// to, so a rule set on the kitchen assistant and widened on the phone one
    /// has no id it could name. That is the shape the demo replay produced,
    /// and it is why the engine looks for the narrower copies itself instead
    /// of waiting to be told about them.
    #[tokio::test]
    async fn widening_on_a_second_assistant_retires_the_copy_on_the_first() {
        const RULE: &str = "Answer concisely: the answer without the preamble.";
        let (dir, _first_tree, pool) = setup_agent_workdir().await;
        let policy = IngestPolicy::default();
        // A second assistant, with its own wiki and its own consumer binding.
        // The tree is reopened after it lands, so both agents are locatable.
        write_wiki(
            &dir.path().join("wikis"),
            "phonebot",
            "Phone Bot",
            "wiki-user",
            None,
        );
        let tree = WikiTree::open(dir.path()).expect("reopen with the second agent");
        sqlx::query("INSERT INTO enrollment_users (user_id, is_admin) VALUES ('phonebot', 0)")
            .execute(&pool)
            .await
            .unwrap();
        crate::consumers::register(
            &pool,
            &crate::consumers::RegisterRequest {
                consumer_id: "phonedeploy",
                display_name: None,
                callback_url: None,
                kinds_subscribed: None,
                metadata: None,
                system_user_id: Some("phonebot"),
            },
        )
        .await
        .expect("register the second consumer");

        let per_user = format!(
            "{{\"intent\":\"capture\",\"extractions\":[{{\
             \"behaviour_rule\":true,\"behaviour_scope\":\"per-user\",\
             \"body\":\"{RULE}\"}}],\"suggested_seed\":\"Ok.\"}}"
        );
        let narrow = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", &per_user),
            None,
            req_consumer("keep it short with me", "alice", "botdeploy"),
            &policy,
        )
        .await
        .expect("ingest")
        .capture_id
        .expect("the per-user rule is filed on the first assistant");

        // Said to the OTHER assistant, and carrying no supersede target —
        // there is none it could have been shown.
        let widened = per_user.replace("per-user", "user-global");
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", &widened),
            None,
            req_consumer(
                "and I mean with every assistant, not just this one",
                "alice",
                "phonedeploy",
            ),
            &policy,
        )
        .await
        .expect("ingest");

        let retired = fact_index::find_by_id(&pool, &narrow)
            .await
            .expect("find")
            .expect("the row stays");
        assert!(
            retired.valid_to.is_some() && retired.superseded_by.is_some(),
            "the copy on the first assistant is retired onto the widened rule"
        );
        assert_eq!(
            fact_index::count_active_in_wiki(&pool, "alice")
                .await
                .unwrap(),
            1,
            "and the widened rule is the one left standing, on the person's own page"
        );
        drop(dir);
    }

    /// The admin widening a rule from the dashboard's operator chat retires
    /// the narrow copy too.
    ///
    /// Widening is one act with one consequence, and it reaches the memory by
    /// two roads — somebody telling their assistant, and the admin naming
    /// `every-assistant` in the operator chat. The retirement lived on the
    /// first road only, so the second one left the narrow copy standing and
    /// the assistant reading the same directive twice. It lives in the shared
    /// chokepoint now ([`file_behaviour_rule`]), which is the call the
    /// operator chat makes.
    #[tokio::test]
    async fn widening_from_the_operator_chat_retires_the_narrow_copy() {
        const RULE: &str = "Answer concisely: the answer without the preamble.";
        let (dir, tree, pool) = setup_agent_workdir().await;
        let per_user = format!(
            "{{\"intent\":\"capture\",\"extractions\":[{{\
             \"behaviour_rule\":true,\"behaviour_scope\":\"per-user\",\
             \"body\":\"{RULE}\"}}],\"suggested_seed\":\"Ok.\"}}"
        );
        let narrow = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", &per_user),
            None,
            req_consumer("keep it short with me", "alice", "botdeploy"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest")
        .capture_id
        .expect("the per-user rule is filed on the assistant");

        // Exactly the call `dispatch_wiki_set_behaviour_rule` makes for
        // `scope: "every-assistant"`: the person's own wiki, the person as
        // subject, and nothing naming what it replaces — the admin is not a
        // consumer and has no rule in front of them to name.
        file_behaviour_rule(
            &tree,
            &pool,
            fake_embedder(),
            WikiId::parse("alice").unwrap(),
            Principal::User("alice".to_owned()),
            BehaviourScope::UserGlobal,
            RULE,
            None,
            chrono::Utc::now(),
        )
        .await
        .expect("the admin widens it");

        let retired = fact_index::find_by_id(&pool, &narrow)
            .await
            .expect("find")
            .expect("the row stays");
        assert!(
            retired.valid_to.is_some() && retired.superseded_by.is_some(),
            "the narrow copy is retired onto the widened rule, whoever widened it"
        );
        assert_eq!(
            fact_index::count_active_in_wiki(&pool, "samvisebot")
                .await
                .unwrap(),
            0,
            "and the assistant is left reading the directive once"
        );
        drop(dir);
    }

    /// Saying a standing rule twice at the SAME scope writes nothing, and the
    /// turn's anchor id is the rule that is actually on the page.
    ///
    /// A dedup skip mints a fresh id for the audit trail without writing a
    /// row, so reporting that id says a rule was filed and names a fact
    /// nobody can read back.
    #[tokio::test]
    async fn a_rule_repeated_at_its_own_scope_reports_the_rule_that_stands() {
        let (dir, tree, pool) = setup_agent_workdir().await;
        let policy = IngestPolicy::default();
        let json = "{\"intent\":\"capture\",\"extractions\":[{\
            \"behaviour_rule\":true,\"behaviour_scope\":\"per-user\",\
            \"body\":\"Answer concisely.\"}],\"suggested_seed\":\"Ok.\"}";
        let first = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", json),
            None,
            req_consumer("keep it short", "alice", "botdeploy"),
            &policy,
        )
        .await
        .expect("ingest");
        let again = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", json),
            None,
            req_consumer("keep it short", "alice", "botdeploy"),
            &policy,
        )
        .await
        .expect("ingest");

        assert_eq!(
            fact_index::count_active_in_wiki(&pool, "samvisebot")
                .await
                .unwrap(),
            1,
            "one rule, said twice"
        );
        assert_eq!(
            again.capture_id, first.capture_id,
            "the second turn points at the rule that stands, not at an id nothing wrote"
        );
        let anchor = again.capture_id.expect("an anchor id");
        assert!(
            fact_index::find_by_id(&pool, &anchor)
                .await
                .expect("find")
                .is_some(),
            "the anchor id must name a fact that exists"
        );
        drop(dir);
    }

    /// Behaviour-rule recall is scoped to the served user by per-fact `sender`
    /// attribution: two users' directives coexist in the one agent wiki without
    /// bleeding into each other, and a caller with no consumer id (a smart
    /// consumer) draws only the user-global source — nothing per-user leaks.
    #[tokio::test]
    async fn behaviour_rule_recall_is_scoped_to_the_sender() {
        let (dir, tree, pool) = setup_agent_workdir().await;
        let policy = IngestPolicy::default();
        let llm_a = FakeLlmBackend::new(
            "fake",
            "{\"intent\":\"capture\",\"extractions\":[{\"behaviour_rule\":true,\
             \"behaviour_scope\":\"per-user\",\
             \"body\":\"Rispondi sempre in modo conciso.\"}]}",
        );
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm_a,
            None,
            req_consumer("rispondimi conciso", "alice", "botdeploy"),
            &policy,
        )
        .await
        .expect("ingest alice");
        let llm_b = FakeLlmBackend::new(
            "fake",
            "{\"intent\":\"capture\",\"extractions\":[{\"behaviour_rule\":true,\
             \"behaviour_scope\":\"per-user\",\
             \"body\":\"Dai del lei all'utente.\"}]}",
        );
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm_b,
            None,
            req_consumer("dammi del lei", "bilbo", "botdeploy"),
            &policy,
        )
        .await
        .expect("ingest bilbo");

        let alice = recall_behaviour_rules(&pool, &req_consumer("?", "alice", "botdeploy")).await;
        assert_eq!(
            alice.iter().map(|(_, b, _)| b.as_str()).collect::<Vec<_>>(),
            vec!["Rispondi sempre in modo conciso."],
            "alice recalls only her own behaviour rule"
        );
        let bilbo = recall_behaviour_rules(&pool, &req_consumer("?", "bilbo", "botdeploy")).await;
        assert_eq!(
            bilbo.iter().map(|(_, b, _)| b.as_str()).collect::<Vec<_>>(),
            vec!["Dai del lei all'utente."],
            "bilbo recalls only his own behaviour rule"
        );
        // A caller with no consumer binding (a smart consumer) draws only the
        // user-global source — and alice has no everywhere-rules in her own
        // identity wiki, so the channel is empty (her per-user rule lives in
        // the AGENT's wiki and binds that agent only).
        assert!(
            recall_behaviour_rules(&pool, &req("?", "alice"))
                .await
                .is_empty(),
            "per-user rules never leak to a consumer without the agent wiki binding"
        );
        drop(dir);
    }

    /// A behaviour rule the user revises (the classifier supersedes the rule it
    /// was shown) replaces the old one in place — the recall channel then
    /// surfaces only the revision, not both.
    #[tokio::test]
    async fn behaviour_rule_supersede_revises_in_place() {
        let (dir, tree, pool) = setup_agent_workdir().await;
        let policy = IngestPolicy::default();
        let llm1 = FakeLlmBackend::new(
            "fake",
            "{\"intent\":\"capture\",\"extractions\":[{\"behaviour_rule\":true,\
             \"behaviour_scope\":\"per-user\",\
             \"body\":\"Rispondi sempre in modo conciso.\"}]}",
        );
        let r1 = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm1,
            None,
            req_consumer("rispondimi conciso", "alice", "botdeploy"),
            &policy,
        )
        .await
        .expect("ingest 1");
        let f1 = r1.capture_id.expect("first rule filed");

        // alice revises it; the model supersedes the rule it was shown.
        let json2 = format!(
            "{{\"intent\":\"capture\",\"extractions\":[{{\"behaviour_rule\":true,\
             \"behaviour_scope\":\"per-user\",\
             \"body\":\"Rispondi pure in modo prolisso.\",\"supersede_target\":\"{}\"}}]}}",
            f1.as_str()
        );
        let llm2 = FakeLlmBackend::new("fake", &json2);
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm2,
            None,
            req_consumer("anzi prolisso", "alice", "botdeploy"),
            &policy,
        )
        .await
        .expect("ingest 2");

        let rules = recall_behaviour_rules(&pool, &req_consumer("?", "alice", "botdeploy")).await;
        assert_eq!(
            rules.iter().map(|(_, b, _)| b.as_str()).collect::<Vec<_>>(),
            vec!["Rispondi pure in modo prolisso."],
            "supersede replaces the old directive in place"
        );
        drop(dir);
    }

    /// An AGENT-WIDE behaviour-rule (impersonal — applies to everyone) set by
    /// the ADMIN is filed owned by the AGENT (not the admin), so it is recalled
    /// for EVERY user, not just the one who set it.
    #[tokio::test]
    async fn agent_wide_behaviour_rule_from_admin_applies_to_everyone() {
        let (dir, tree, pool) = setup_agent_workdir().await;
        // alice is the operator/admin (samvisebot is is_admin=0, so the partial
        // unique index allows one more admin row).
        sqlx::query("INSERT INTO enrollment_users (user_id, is_admin) VALUES ('alice', 1)")
            .execute(&pool)
            .await
            .unwrap();
        let llm = FakeLlmBackend::new(
            "fake",
            "{\"intent\":\"capture\",\"extractions\":[{\"behaviour_rule\":true,\
             \"behaviour_scope\":\"agent-wide\",\
             \"body\":\"Per i task pesanti delega a Claude Code.\"}]}",
        );
        let policy = IngestPolicy::default();
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req_consumer("delega a claude", "alice", "botdeploy"),
            &policy,
        )
        .await
        .expect("ingest admin");

        let rows = fact_index::find_by_filters(
            &pool,
            &fact_index::FactFilters {
                wiki_id: Some("samvisebot".to_owned()),
                ..Default::default()
            },
        )
        .await
        .unwrap();
        assert_eq!(
            rows.len(),
            1,
            "exactly one agent-wide rule in the agent wiki"
        );
        assert_eq!(
            rows[0].subject_id,
            Principal::User("samvisebot".into()),
            "an agent-wide rule is OWNED by the AGENT, not by the admin who set it"
        );
        // Recalled for a DIFFERENT, non-admin user — proving agent-wide reach.
        let bilbo = recall_behaviour_rules(&pool, &req_consumer("?", "bilbo", "botdeploy")).await;
        assert_eq!(
            bilbo.iter().map(|(_, b, _)| b.as_str()).collect::<Vec<_>>(),
            vec!["Per i task pesanti delega a Claude Code."],
            "an agent-wide rule is recalled for EVERY user, not just the admin"
        );
        drop(dir);
    }

    /// An AGENT-WIDE behaviour-rule from a NON-admin is REFUSED: nothing is
    /// filed, and the dedicated `rules` field carries a one-shot notice steering
    /// the agent to decline. A per-user rule from the same user would still be
    /// accepted — only agent-wide changes are admin-gated.
    #[tokio::test]
    async fn agent_wide_behaviour_rule_from_non_admin_is_refused() {
        let (dir, tree, pool) = setup_agent_workdir().await;
        // alice has no is_admin=1 row → not the admin.
        let llm = FakeLlmBackend::new(
            "fake",
            "{\"intent\":\"capture\",\"extractions\":[{\"behaviour_rule\":true,\
             \"behaviour_scope\":\"agent-wide\",\
             \"body\":\"Per i task pesanti delega a Claude Code.\"}],\
             \"suggested_seed\":\"Ok.\"}",
        );
        let policy = IngestPolicy::default();
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req_consumer("delega tutto a claude", "alice", "botdeploy"),
            &policy,
        )
        .await
        .expect("ingest non-admin");

        let rows = fact_index::find_by_filters(
            &pool,
            &fact_index::FactFilters {
                wiki_id: Some("samvisebot".to_owned()),
                ..Default::default()
            },
        )
        .await
        .unwrap();
        assert!(
            rows.is_empty(),
            "a non-admin's agent-wide rule must not be filed anywhere"
        );
        assert!(resp.capture_id.is_none(), "nothing filed → no anchor id");
        assert!(
            resp.rules
                .as_deref()
                .unwrap_or_default()
                .contains("reserved to the admin"),
            "the `rules` field tells the agent to decline (an agent-wide change is admin-only)"
        );
        drop(dir);
    }

    /// A USER-GLOBAL behaviour-rule — here in its clearest shape, the speaker
    /// naming every assistant outright — is filed in the SENDER's identity
    /// wiki, owned by the sender, and the rules channel serves it to every
    /// consumer serving that user, the bindingless smart consumer included. No
    /// admin gate: it binds only the user's own conversations.
    #[tokio::test]
    async fn user_global_rule_lands_in_sender_wiki_and_reaches_every_consumer() {
        let (dir, tree, pool) = setup_agent_workdir().await;
        let llm = FakeLlmBackend::new(
            "fake",
            "{\"intent\":\"capture\",\"extractions\":[{\"behaviour_rule\":true,\
             \"behaviour_scope\":\"user-global\",\
             \"body\":\"Parlami in italiano.\"}]}",
        );
        let policy = IngestPolicy::default();
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req_consumer("ogni assistente mi parli in italiano", "alice", "botdeploy"),
            &policy,
        )
        .await
        .expect("ingest user-global");

        // Home: the sender's own identity wiki — the agent wiki stays clean.
        let in_agent = fact_index::find_by_filters(
            &pool,
            &fact_index::FactFilters {
                wiki_id: Some("samvisebot".to_owned()),
                ..Default::default()
            },
        )
        .await
        .unwrap();
        assert!(
            in_agent.is_empty(),
            "a user-global rule never lands in the calling agent's wiki"
        );
        let rows = fact_index::find_by_filters(
            &pool,
            &fact_index::FactFilters {
                wiki_id: Some("alice".to_owned()),
                ..Default::default()
            },
        )
        .await
        .unwrap();
        assert_eq!(rows.len(), 1, "exactly one rule in alice's identity wiki");
        assert_eq!(rows[0].subject_id, Principal::User("alice".into()));
        assert!(rows[0].source_path.ends_with("@rules.md"));

        // Served through the channel on a bound consumer…
        let via_agent =
            recall_behaviour_rules(&pool, &req_consumer("?", "alice", "botdeploy")).await;
        assert_eq!(
            via_agent
                .iter()
                .map(|(_, b, s)| (b.as_str(), *s))
                .collect::<Vec<_>>(),
            vec![("Parlami in italiano.", BehaviourScope::UserGlobal)],
            "the user's everywhere-rule reaches a bound consumer"
        );
        // …and on a bindingless (smart) consumer alike.
        let smart = recall_behaviour_rules(&pool, &req("?", "alice")).await;
        assert_eq!(
            smart.iter().map(|(_, b, _)| b.as_str()).collect::<Vec<_>>(),
            vec!["Parlami in italiano."],
            "the user's everywhere-rule reaches a consumer with no agent wiki binding"
        );
        // Never for another user — it is alice's own rule.
        let bilbo = recall_behaviour_rules(&pool, &req_consumer("?", "bilbo", "botdeploy")).await;
        assert!(
            bilbo.is_empty(),
            "another user's channel never carries alice's user-global rule"
        );
        drop(dir);
    }

    /// The two ways a naming rule can reach past the speaker are OPPOSITE, and
    /// the scope alone tells them apart. `agent-wide` names the AGENT for
    /// everyone it serves: the rule is the agent's, filed in the agent's wiki
    /// with `subject = the agent`, and NOTHING of it lands in the speaker's own
    /// wiki. `user-global` names the SPEAKER for every assistant they talk to:
    /// the rule is the user's, filed in their identity wiki with
    /// `subject = the user`, and nothing is added to the agent's.
    #[tokio::test]
    async fn naming_rule_scope_decides_the_home_wiki_and_the_subject() {
        let (dir, tree, pool) = setup_agent_workdir().await;
        // alice is the operator/admin, so her agent-wide rule is not refused.
        sqlx::query("INSERT INTO enrollment_users (user_id, is_admin) VALUES ('alice', 1)")
            .execute(&pool)
            .await
            .unwrap();
        let policy = IngestPolicy::default();

        // "you are called Gandalf for everyone" — the AGENT is named, for the
        // whole audience this agent serves.
        let llm = FakeLlmBackend::new(
            "fake",
            "{\"intent\":\"capture\",\"extractions\":[{\"behaviour_rule\":true,\
             \"behaviour_scope\":\"agent-wide\",\
             \"body\":\"Your name is Gandalf.\"}]}",
        );
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req_consumer("you are called Gandalf for everyone", "alice", "botdeploy"),
            &policy,
        )
        .await
        .expect("ingest agent-wide naming");

        let in_agent = facts_in_wiki(&pool, "samvisebot").await;
        assert_eq!(
            in_agent.len(),
            1,
            "the agent's own name is filed in the agent's wiki"
        );
        assert_eq!(in_agent[0].text, "Your name is Gandalf.");
        assert_eq!(
            in_agent[0].subject_id,
            Principal::User("samvisebot".into()),
            "naming the agent for everyone is OWNED by the agent, never by the admin who said it"
        );
        assert!(
            facts_in_wiki(&pool, "alice").await.is_empty(),
            "naming the AGENT writes nothing in the speaker's wiki — that would rename the speaker"
        );

        // "call me Gandalf with every assistant" — the SPEAKER is named, for
        // every assistant serving them.
        let llm = FakeLlmBackend::new(
            "fake",
            "{\"intent\":\"capture\",\"extractions\":[{\"behaviour_rule\":true,\
             \"behaviour_scope\":\"user-global\",\
             \"body\":\"Call the user Gandalf.\"}]}",
        );
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req_consumer("call me Gandalf with every assistant", "alice", "botdeploy"),
            &policy,
        )
        .await
        .expect("ingest user-global naming");

        let in_user = facts_in_wiki(&pool, "alice").await;
        assert_eq!(
            in_user.len(),
            1,
            "the user's own name is filed in the user's identity wiki"
        );
        assert_eq!(in_user[0].text, "Call the user Gandalf.");
        assert_eq!(
            in_user[0].subject_id,
            Principal::User("alice".into()),
            "naming the speaker everywhere is OWNED by the speaker"
        );
        assert_eq!(
            facts_in_wiki(&pool, "samvisebot").await.len(),
            1,
            "naming the SPEAKER adds nothing to the agent's wiki — the agent keeps its own name"
        );
        drop(dir);
    }

    /// The `YOUR RULES` order is pinned, most specific last: agent-wide (the
    /// floor) → user-global (the user's everywhere-set) → per-user (this
    /// agent, this user).
    #[tokio::test]
    async fn rules_channel_order_is_agent_wide_then_user_global_then_per_user() {
        let (dir, tree, pool) = setup_agent_workdir().await;
        // alice is the operator/admin, so her agent-wide rule files.
        sqlx::query("INSERT INTO enrollment_users (user_id, is_admin) VALUES ('alice', 1)")
            .execute(&pool)
            .await
            .unwrap();
        let policy = IngestPolicy::default();
        // Each rule is dictated in its own words: three turns of one message
        // would be the same turn three times, and the second and third would
        // be answered with the first one's reply instead of filing anything
        // ([`crate::ingest_replay`]).
        for (scope, body, said) in [
            ("per-user", "Rispondi conciso.", "rispondimi conciso"),
            (
                "user-global",
                "Parlami in italiano.",
                "parlami sempre in italiano",
            ),
            (
                "agent-wide",
                "Non dare consigli medici.",
                "non dare consigli medici a nessuno",
            ),
        ] {
            let llm = FakeLlmBackend::new(
                "fake",
                format!(
                    "{{\"intent\":\"capture\",\"extractions\":[{{\"behaviour_rule\":true,\
                     \"behaviour_scope\":\"{scope}\",\"body\":\"{body}\"}}]}}"
                ),
            );
            wiki_ingest_message(
                &pool,
                &tree,
                fake_embedder(),
                &llm,
                None,
                req_consumer(said, "alice", "botdeploy"),
                &policy,
            )
            .await
            .expect("ingest rule");
        }
        let rules = recall_behaviour_rules(&pool, &req_consumer("?", "alice", "botdeploy")).await;
        assert_eq!(
            rules
                .iter()
                .map(|(_, b, s)| (b.as_str(), *s))
                .collect::<Vec<_>>(),
            vec![
                ("Non dare consigli medici.", BehaviourScope::AgentWide),
                ("Parlami in italiano.", BehaviourScope::UserGlobal),
                ("Rispondi conciso.", BehaviourScope::PerUser),
            ],
            "order pinned: agent-wide → user-global → per-user (most specific last)"
        );
        drop(dir);
    }

    /// A NON-admin revising an AGENT-WIDE rule cannot retire the floor: the
    /// supersede is dropped and their directive files additively at its own
    /// (per-user) scope — the agent-wide rule stays in force for everyone.
    #[tokio::test]
    async fn non_admin_supersede_of_agent_wide_rule_stays_additive() {
        let (dir, tree, pool) = setup_agent_workdir().await;
        sqlx::query("INSERT INTO enrollment_users (user_id, is_admin) VALUES ('alice', 1)")
            .execute(&pool)
            .await
            .unwrap();
        let policy = IngestPolicy::default();
        let llm = FakeLlmBackend::new(
            "fake",
            "{\"intent\":\"capture\",\"extractions\":[{\"behaviour_rule\":true,\
             \"behaviour_scope\":\"agent-wide\",\
             \"body\":\"Non dare consigli medici.\"}]}",
        );
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req_consumer("niente consigli medici", "alice", "botdeploy"),
            &policy,
        )
        .await
        .expect("ingest admin floor");
        let floor = &fact_index::find_by_filters(
            &pool,
            &fact_index::FactFilters {
                wiki_id: Some("samvisebot".to_owned()),
                ..Default::default()
            },
        )
        .await
        .unwrap()[0];

        // bilbo (not admin) tries to REVISE the floor into his own preference.
        let llm = FakeLlmBackend::new(
            "fake",
            format!(
                "{{\"intent\":\"capture\",\"extractions\":[{{\"behaviour_rule\":true,\
                 \"behaviour_scope\":\"per-user\",\"body\":\"Dammi pure consigli medici.\",\
                 \"supersede_target\":\"{}\"}}]}}",
                floor.fact_id
            ),
        );
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req_consumer("a me i consigli medici servono", "bilbo", "botdeploy"),
            &policy,
        )
        .await
        .expect("ingest non-admin revision");

        // The floor still stands for everyone, bilbo's rule rides beside it.
        let rules = recall_behaviour_rules(&pool, &req_consumer("?", "bilbo", "botdeploy")).await;
        assert_eq!(
            rules
                .iter()
                .map(|(_, b, s)| (b.as_str(), *s))
                .collect::<Vec<_>>(),
            vec![
                ("Non dare consigli medici.", BehaviourScope::AgentWide),
                ("Dammi pure consigli medici.", BehaviourScope::PerUser),
            ],
            "the agent-wide floor survives a non-admin's supersede — additive, not replaced"
        );
        drop(dir);
    }

    /// The `0052` page-rename data migration re-homes legacy
    /// behaviour-rule facts off `behaviour_rules.md` onto `@rules.md`, preserving
    /// the workdir-relative path prefix. (On a live DB the migration runs at
    /// startup; here we exercise its exact statement on a planted legacy row.)
    #[tokio::test]
    async fn migration_0052_rehomes_behaviour_rules_page() {
        let (dir, tree, pool) = setup_agent_workdir().await;
        // Plant a behaviour-rule fact on the LEGACY page name.
        let cap_req = CaptureRequest {
            subject_external: None,
            slot: None,
            slot_value: None,
            authored_refs: Vec::new(),
            wiki_id: WikiId::parse("samvisebot").unwrap(),
            page: Some(PathBuf::from("behaviour_rules.md")),
            body: "Dai del tu all'utente.".into(),
            subject: Principal::User("samvisebot".into()),
            allow: Vec::new(),
            sender: None,
            fact_type: Some("rule".into()),
            topics: Vec::new(),
            dedup_threshold: None,
            valid_from: None,
            valid_to: None,
            style: None,
            page_description: None,
            salience: None,
        };
        let planted = capture::wiki_capture(&tree, &pool, fake_embedder(), cap_req)
            .await
            .expect("plant legacy behaviour rule");
        let before = fact_index::find_by_id(&pool, &planted.fact_id)
            .await
            .unwrap()
            .unwrap();
        assert!(
            before.source_path.ends_with("/behaviour_rules.md"),
            "planted on the legacy page, was: {}",
            before.source_path
        );

        // The migration's statement — mirrors
        // migrations/0052_behaviour_rules_page_rename.sql.
        sqlx::query(
            "UPDATE fact_index \
             SET source_path = replace(source_path, 'behaviour_rules.md', 'rules.md') \
             WHERE source_path LIKE '%behaviour_rules.md'",
        )
        .execute(&pool)
        .await
        .unwrap();

        let after = fact_index::find_by_id(&pool, &planted.fact_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            after.source_path,
            before.source_path.replace("behaviour_rules.md", "rules.md"),
            "0052 moved the basename to `rules.md` — the bare name, which is \
             what that migration wrote; the `@` marker arrived on 2026-08-18 \
             and a migration is never edited after the fact"
        );
        assert!(after.source_path.ends_with("/rules.md"));
        // And the re-homed fact is recalled through the behaviour channel.
        let rules =
            behaviour_rows_on_page(&pool, "samvisebot", &Principal::User("samvisebot".into()))
                .await;
        assert_eq!(
            rules.iter().map(|(_, b)| b.as_str()).collect::<Vec<_>>(),
            vec!["Dai del tu all'utente."],
            "the re-homed legacy rule recalls from rules.md"
        );
        drop(dir);
    }

    /// A behaviour-rule capture request in the agent's own wiki, on the page
    /// `page` — the shape `capture_behaviour_rule` produces, for planting
    /// channel fixtures directly.
    fn agent_fact_req(page: &str, body: &str, dedup_threshold: Option<f32>) -> CaptureRequest {
        CaptureRequest {
            subject_external: None,
            slot: None,
            slot_value: None,
            authored_refs: Vec::new(),
            wiki_id: WikiId::parse("samvisebot").unwrap(),
            page: Some(PathBuf::from(page)),
            body: body.to_owned(),
            subject: Principal::User("samvisebot".into()),
            allow: Vec::new(),
            sender: None,
            fact_type: Some("rule".into()),
            page_description: None,
            topics: Vec::new(),
            dedup_threshold,
            valid_from: None,
            valid_to: None,
            style: None,
            salience: None,
        }
    }

    /// Starvation regression (the cap-before-filter bug): the rules-page
    /// predicate applies IN the SQL before `BEHAVIOUR_RULES_RECALL_CAP`, so
    /// an old rule survives more than a cap's worth of NEWER same-subject
    /// facts on the agent wiki's content pages.
    #[tokio::test]
    async fn behaviour_rules_survive_a_crowded_agent_wiki() {
        let (dir, tree, pool) = setup_agent_workdir().await;
        // The standing rule — backdated so it is unambiguously the OLDEST row.
        let rule = capture::wiki_capture(
            &tree,
            &pool,
            fake_embedder(),
            agent_fact_req(crate::wiki::RULES_FILENAME, "Dai del tu all'utente.", None),
        )
        .await
        .expect("plant rule");
        sqlx::query("UPDATE fact_index SET created_at = '2020-01-01T00:00:00Z' WHERE fact_id = ?")
            .bind(rule.fact_id.as_str())
            .execute(&pool)
            .await
            .unwrap();
        // Crowd the wiki with MORE THAN the recall cap of newer same-subject
        // facts on a content page (the agent's self-facts).
        for i in 0..(BEHAVIOUR_RULES_RECALL_CAP + 5) {
            capture::wiki_capture(
                &tree,
                &pool,
                fake_embedder(),
                agent_fact_req(
                    "esperienze.md",
                    &format!("agent self note number {i}"),
                    Some(1.01), // crowding, not dedup, is under test
                ),
            )
            .await
            .expect("crowd");
        }

        let rules =
            behaviour_rows_on_page(&pool, "samvisebot", &Principal::User("samvisebot".into()))
                .await;
        assert_eq!(
            rules.iter().map(|(_, b)| b.as_str()).collect::<Vec<_>>(),
            vec!["Dai del tu all'utente."],
            "the old rule must outlive a cap's worth of newer non-rules facts"
        );
        drop(dir);
    }

    /// Retraction semantics: a rule whose validity window was closed (the
    /// conversational closure path) stops being served by the channel, while
    /// the fact itself stays — closing is never deleting.
    #[tokio::test]
    async fn retracted_behaviour_rule_stops_serving_but_the_fact_stays() {
        let (dir, tree, pool) = setup_agent_workdir().await;
        let kept = capture::wiki_capture(
            &tree,
            &pool,
            fake_embedder(),
            agent_fact_req(
                crate::wiki::RULES_FILENAME,
                "Rispondi in modo conciso.",
                None,
            ),
        )
        .await
        .expect("plant kept rule");
        let retracted = capture::wiki_capture(
            &tree,
            &pool,
            fake_embedder(),
            agent_fact_req(crate::wiki::RULES_FILENAME, "Dai del tu all'utente.", None),
        )
        .await
        .expect("plant retracted rule");

        // The closure verb retracts one (a validity statement, not a delete).
        let closed_at = (chrono::Utc::now() - chrono::Duration::minutes(5)).to_rfc3339();
        fact_index::close_validity(
            &pool,
            &retracted.fact_id,
            &closed_at,
            "retracted",
            None,
            chrono::Utc::now(),
        )
        .await
        .expect("close")
        .expect("row exists");

        let rules =
            behaviour_rows_on_page(&pool, "samvisebot", &Principal::User("samvisebot".into()))
                .await;
        assert_eq!(
            rules.iter().map(|(id, _)| id).collect::<Vec<_>>(),
            vec![&kept.fact_id],
            "a closed-window rule must stop steering the agent"
        );
        // Closing is never deleting: the row stays active in the index.
        let row = fact_index::find_by_id(&pool, &retracted.fact_id)
            .await
            .unwrap()
            .expect("row still present");
        assert!(row.deleted_at.is_none() && row.superseded_at.is_none());
        drop(dir);
    }

    /// The bundled ingest prompt keeps the boundary that decides what this
    /// slot may act on.
    ///
    /// `supersede_target` survives for ONE target — a behaviour rule — because
    /// `agent_behaviour_rules` is the complete set of the directives in force,
    /// so the model can see everything it would be replacing. `recalled_memory`
    /// is a similarity sample of a store that may hold thousands, and a
    /// judgement about a stored fact made from a sample fails by omission: the
    /// prompt must keep saying so, and must keep the repeat-vs-revise guard on
    /// the one supersede that remains.
    #[test]
    fn bundled_ingest_prompt_keeps_the_complete_set_boundary() {
        assert!(
            BUNDLED_INGEST_PROMPT_MD.contains("You may act against a set you are shown COMPLETE"),
            "the complete-set-vs-sample rule is gone from the bundled prompt"
        );
        assert!(
            BUNDLED_INGEST_PROMPT_MD.contains("REVISING vs REPEATING a standing directive"),
            "the behaviour-rule repeat guard is gone from the bundled prompt"
        );
        assert!(
            !BUNDLED_INGEST_PROMPT_MD.contains("\"closures\":"),
            "reconciliation against stored facts must not come back to this slot"
        );
    }

    /// The bundled ingest prompt refuses to turn a measurement into a date.
    ///
    /// An age, a duration and a bare day-and-month are the three shapes a
    /// classifier reads as an anchor and resolves against `current_time`,
    /// and resolving any of them mints a birth date nobody stated — which
    /// then lands on the subject's card beside the one somebody did state.
    /// The prompt has to keep both halves: the measurement is never a date,
    /// and the anchor rule that licenses "tomorrow" does not reach it.
    #[test]
    fn bundled_ingest_prompt_never_derives_a_birth_date_from_an_age() {
        assert!(
            BUNDLED_INGEST_PROMPT_MD.contains("is never a date of birth"),
            "the age-is-not-a-birth-date rule is gone from the bundled prompt"
        );
        assert!(
            BUNDLED_INGEST_PROMPT_MD.contains("never gains a year"),
            "the day-and-month-without-a-year rule is gone from the bundled prompt"
        );
        assert!(
            BUNDLED_INGEST_PROMPT_MD
                .contains("The anchor rule is about the turn's own clock, and nothing else"),
            "the anchor rule no longer excludes ages and durations, so it licenses them again"
        );
    }

    /// The bundled ingest prompt teaches that a list entry is not a sentence.
    ///
    /// The engine renders a `lista` body exactly as it arrives, so the shape
    /// of a list is decided in this prompt and nowhere else. Three things have
    /// to keep standing: the exception itself, stated where the third-person
    /// rule is stated; the ONE separator, so two spellings of a second value
    /// cannot both be right; and the worked example, which is where a model
    /// reads the shape rather than the rule. The old example is asserted gone
    /// — it taught the sentence the exception exists to stop.
    #[test]
    fn bundled_ingest_prompt_teaches_that_a_list_entry_is_not_a_sentence() {
        for needle in [
            "THE ONE EXCEPTION — A LIST ENTRY IS NOT A SENTENCE",
            "EVERY OTHER VALUE takes ` · `",
            "WHAT LOOKS LIKE AN ENTRY AND IS NOT ONE",
            "`body`: `\"detergent 2 bottles\"`",
            "`body`: `\"yoghurt · expires 20 September\"`",
        ] {
            assert!(
                BUNDLED_INGEST_PROMPT_MD.contains(needle),
                "the bundled prompt does not say: {needle}"
            );
        }
        assert!(
            !BUNDLED_INGEST_PROMPT_MD.contains("Detergent is needed."),
            "the worked list example still writes an entry as a sentence"
        );
    }

    /// The turns a public-demo corpus lost, and the one gate that lost them.
    ///
    /// A standing directive, a stated position, a withdrawal of one's own
    /// claim and a plain sentence about somebody outside the roster all
    /// reached the classifier and came back `skip` — the last one `recall`.
    /// None of them is a hard case. What they share is that Part 1 never named
    /// their shape, so each fell to whichever bullet claims what is left, and
    /// everything downstream is gated on the intent. The prompt has to keep
    /// naming all four, and it has to keep the fence that stops the same rules
    /// swallowing an ordinary ack or a one-shot command.
    #[test]
    fn bundled_ingest_prompt_routes_directives_positions_and_withdrawals_to_capture() {
        for needle in [
            // The mechanism: an intent is a routing decision, not a verdict on
            // whether this turn can do the work itself.
            "leaves the memory something to do",
            // A directive is not a fact and is still a capture.
            "a standing directive is a `capture` turn",
            // A statement is not made a lookup by a name inside it.
            "A DECLARATIVE SENTENCE IS NEVER `recall` BECAUSE OF A NAME INSIDE IT",
            // The two shapes `skip` was swallowing.
            "AN ACK THAT CARRIES A DECISION IS NOT AN ACK",
            "A DIRECTIVE THAT WOULD STILL BIND TOMORROW IS NOT CHIT-CHAT",
        ] {
            assert!(
                BUNDLED_INGEST_PROMPT_MD.contains(needle),
                "the bundled prompt does not say: {needle}"
            );
        }
        assert!(
            BUNDLED_INGEST_PROMPT_MD.contains("COUNTER-EXAMPLES"),
            "the fence that keeps the four new shapes from swallowing an ack, \
             a one-shot command and a question is gone"
        );
    }

    /// A rule about how to treat SOMEBODY ELSE is refused in conversation, and
    /// the admin is refused with everybody else.
    ///
    /// The road is closed, not gated: the engine files every behaviour rule
    /// under whoever dictated it, so "read aloud every reply you send to bob"
    /// from anyone but bob has nowhere to go — routed per-user it would bind
    /// the SPEAKER and fire when the speaker talks, never when bob does. Read
    /// as a rule for everyone it used to reach the admin gate instead, and an
    /// ordinary user was refused for a rule they had not asked to set. So the
    /// classifier names the case (`behaviour_about`) and the engine answers it,
    /// on the same one-shot channel the admin refusal uses. What must NOT
    /// change with it: the very same sentence from bob about HIMSELF is an
    /// ordinary directive and still files.
    #[tokio::test]
    async fn a_rule_about_another_person_is_refused_in_conversation_for_everyone() {
        const RULE: &str = "Leggi a voce alta tutte le risposte che invii a bob.";

        async fn attempt(sender: &str, about: Option<&str>, admin: bool) -> (String, usize) {
            let (dir, tree, pool) = setup_agent_workdir().await;
            if admin {
                sqlx::query("INSERT INTO enrollment_users (user_id, is_admin) VALUES (?, 1)")
                    .bind(sender)
                    .execute(&pool)
                    .await
                    .unwrap();
            }
            let about_field =
                about.map_or_else(String::new, |a| format!(r#""behaviour_about":"{a}","#));
            let plan = format!(
                r#"{{"intent":"capture","extractions":[{{"behaviour_rule":true,"behaviour_scope":"per-user",{about_field}"body":"{RULE}"}}]}}"#
            );
            let llm = FakeLlmBackend::new("fake", &plan);
            let resp = wiki_ingest_message(
                &pool,
                &tree,
                fake_embedder(),
                &llm,
                None,
                req_consumer(
                    "leggi a voce alta le risposte che mandi a bob",
                    sender,
                    "botdeploy",
                ),
                &IngestPolicy::default(),
            )
            .await
            .expect("ingest");
            let filed = fact_index::find_by_filters(&pool, &fact_index::FactFilters::default())
                .await
                .unwrap()
                .into_iter()
                .filter(|r| crate::wiki::is_rules_page(&r.source_path))
                .count();
            let rules = resp.rules.unwrap_or_default();
            drop(dir);
            (rules, filed)
        }

        // An ordinary user, naming somebody else: refused, nothing stored, and
        // told which refusal it was.
        let (rules, filed) = attempt("alice", Some("bob"), false).await;
        assert_eq!(filed, 0, "a rule about another person is stored nowhere");
        assert!(
            rules.contains("SOMEBODY ELSE") && rules.contains("operator chat"),
            "the person is told what was refused and where it CAN be set: {rules}"
        );
        assert!(
            !rules.contains("reserved to the admin"),
            "and not with the agent-wide refusal, which is about a rule they never asked for"
        );

        // The admin, in conversation: the same refusal. This road is closed,
        // not gated — the dashboard's operator chat is the one that is open.
        let (rules, filed) = attempt("alice", Some("bob"), true).await;
        assert_eq!(
            filed, 0,
            "the admin is refused too — in conversation nobody may"
        );
        assert!(
            rules.contains("SOMEBODY ELSE"),
            "and hears the same answer, not a different one: {rules}"
        );

        // The same sentence from the person it is about: an ordinary directive.
        let (rules, filed) = attempt("bob", None, false).await;
        assert_eq!(filed, 1, "bob setting it about himself still files");
        assert!(
            rules.contains(RULE),
            "and it comes back as a rule in force: {rules}"
        );

        // BOTH SPELLINGS OF THE SAME PERSON MEAN THE SAME PERSON. Every other
        // id in the classifier's JSON is written `user:<id>`, so this one
        // arrives that way too — and compared literally, `"user:bob"` from bob
        // was somebody else: the refusal fired and told bob he may not set
        // rules about other people while he was setting one about himself.
        let (rules, filed) = attempt("bob", Some("user:bob"), false).await;
        assert_eq!(filed, 1, "`user:bob` from bob is bob — the rule files");
        assert!(
            rules.contains(RULE) && !rules.contains("SOMEBODY ELSE"),
            "and he is not told he may not set rules about others: {rules}"
        );
        // …and the prefixed form of a DIFFERENT person still refuses, so the
        // normalisation did not open the door it exists to keep shut.
        let (rules, filed) = attempt("alice", Some("user:bob"), false).await;
        assert_eq!(filed, 0, "`user:bob` from alice is still somebody else");
        assert!(
            rules.contains("SOMEBODY ELSE"),
            "and is refused exactly as the bare spelling is: {rules}"
        );
    }

    /// The scope of a directive is read from WHO WAS ADDRESSED, and a taste
    /// about the assistant's own conduct is a directive.
    ///
    /// Production filed «the user prefers to receive a summary as an audio
    /// message» as a `preference` on the speaker's identity card: an
    /// instruction to the assistant, stored as knowledge about her, where the
    /// rules channel can never reach it. Two sentences of Part 7 let that
    /// through. The boundary test offered "telling the agent how to conduct
    /// itself" and "stating something true about the user" as an exclusive
    /// choice, and that sentence answers yes to BOTH — so the nearest
    /// `fact_type` bullet won it. And the scope rule asked the user to name
    /// every assistant EXPLICITLY before a directive could travel with them,
    /// which no ordinary sentence does. Both are replaced by one reading:
    /// addressed to the assistant in front of you ⇒ this assistant only;
    /// addressed to nobody ⇒ every assistant serving that person.
    ///
    /// Three rules narrow that second half, and each exists because a wider
    /// reading is silently wrong. An explicit limiter ("qui", "solo su questo
    /// assistente") names who it binds without saying "you". A consumer's
    /// third-person summary is the BRIDGE's grammar, not the speaker's — it is
    /// no evidence about the addressee, so it takes the narrowest scope rather
    /// than the widest, or any consumer that paraphrases would promote its
    /// user's every directive into a rule for all assistants. And a directive
    /// whose scope is a THIRD PERSON is refused in the open: nobody sets how
    /// the assistant treats another person by talking to it, the admin
    /// included — that is the operator chat's, and the refusal says so.
    #[test]
    fn bundled_ingest_prompt_reads_a_directive_and_its_scope_from_the_addressee() {
        for needle in [
            // The scope criterion, in both directions.
            "THE SCOPE IS READ IN TWO STEPS, AND THE SECOND ONE IS THE ADDRESSEE",
            "the second person or the imperative",
            "an impersonal or general sentence about how the answers are to be",
            // A consumer's own third-person summary is the BRIDGE's grammar:
            // it is no evidence about the addressee, and no evidence narrows
            // the scope rather than widening it.
            "A THIRD-PERSON REPORT IS NOT AN IMPERSONAL SENTENCE",
            "take the NARROWEST scope",
            // A sentence can name who it binds by drawing the line instead of
            // by saying "you".
            "AN EXPLICIT LIMITER IS AN ADDRESSEE",
            // The taste-that-is-a-directive, and the test that decides it.
            "is a `behaviour_rule`, and never a preference on their card",
            // ONE question with ONE answer. Two questions both answered yes on
            // "I prefer short answers", which is the shape they had to settle.
            "WHO HAS TO MOVE for this sentence to become true, and is it YOU?",
            "a wish is not promoted into one because you could grant it",
            // A rule whose scope is a third person is nobody's to set in
            // conversation, and the classifier refuses it in the open rather
            // than guessing a home for it.
            "A RULE ABOUT SOMEBODY ELSE IS NOT SET IN CONVERSATION",
            "the same sentence from Bob about HIMSELF is an ordinary directive",
            // The `fact_type` list is where the wrong answer actually gets
            // picked, so it carries the pointer back to Part 7.
            "A taste whose object is the ASSISTANT'S OWN CONDUCT is not one of these",
        ] {
            assert!(
                BUNDLED_INGEST_PROMPT_MD.contains(needle),
                "the bundled prompt does not say: {needle}"
            );
        }
        assert!(
            BUNDLED_INGEST_PROMPT_MD.contains("NAME THE MOVER, and these stay facts"),
            "the fence is gone — without it the question promotes every ordinary \
             preference into a standing directive"
        );
        assert!(
            BUNDLED_INGEST_PROMPT_MD.contains("(BOB moves"),
            "the counter-example whose mover is a THIRD PERSON is gone, and it is the \
             one a two-question test used to get wrong"
        );
        // The naming rule has to justify itself with the criterion in force:
        // "your name is Gandalf" is per-user because it says YOUR, not because
        // it names no audience — the old reason contradicts the two steps.
        assert!(
            !BUNDLED_INGEST_PROMPT_MD.contains("with no audience, or for the speaker alone"),
            "the naming rule still explains itself with the scope rule that was replaced"
        );
        // The rule it replaces has to be gone, not merely outvoted: while it
        // stands, an impersonal directive still needs the user to name every
        // assistant before it can leave the agent it was said to.
        assert!(
            !BUNDLED_INGEST_PROMPT_MD.contains("needs the user to name every assistant EXPLICITLY"),
            "the old scope rule is still in the prompt, contradicting the new one"
        );
    }

    /// Where a directive lands, in the three directions the addressee sends
    /// it — and what filing it as a taste costs.
    ///
    /// Said to the assistant in front of the speaker, it is that assistant's
    /// rule and lives in the AGENT's wiki. Said impersonally, it is the
    /// SPEAKER's rule and lives in their own wiki, where every assistant
    /// serving them picks it up (the full serving matrix — bound consumer,
    /// bindingless consumer, and never another user — is
    /// [`user_global_rule_lands_in_sender_wiki_and_reaches_every_consumer`];
    /// what this pins is the contrast between the two homes). Filed as an
    /// ordinary taste it is taken all the same, into the captures buffer as
    /// knowledge about the speaker, and the rules channel stays EMPTY —
    /// [`recall_behaviour_rules`] reads `@rules.md` pages and nothing else,
    /// so an instruction filed as knowledge is never applied as a standing
    /// directive, never revised by a supersede and never withdrawn by asking
    /// the agent to stop.
    ///
    /// Which of the three the model picks is Part 7's job, pinned on the
    /// prompt text by
    /// [`bundled_ingest_prompt_reads_a_directive_and_its_scope_from_the_addressee`];
    /// what this test pins is that picking differently lands differently.
    #[tokio::test]
    async fn a_directive_lands_where_the_addressee_sends_it_and_a_taste_lands_nowhere() {
        const RULE: &str = "Manda a questo utente i riassunti e i verdetti finali come \
                            messaggio audio.";

        async fn ingest_as(json: &str, turn: &str) -> (TempDir, SqlitePool) {
            let (dir, tree, pool) = setup_agent_workdir().await;
            let llm = FakeLlmBackend::new("fake", json);
            wiki_ingest_message(
                &pool,
                &tree,
                fake_embedder(),
                &llm,
                None,
                req_consumer(turn, "alice", "botdeploy"),
                &IngestPolicy::default(),
            )
            .await
            .expect("ingest");
            (dir, pool)
        }
        async fn rules_page_of(pool: &SqlitePool, wiki: &str) -> Vec<String> {
            fact_index::find_by_filters(
                pool,
                &fact_index::FactFilters {
                    wiki_id: Some(wiki.to_owned()),
                    ..Default::default()
                },
            )
            .await
            .unwrap()
            .into_iter()
            .filter(|r| crate::wiki::is_rules_page(&r.source_path))
            .map(|r| r.text)
            .collect()
        }

        // 1. «Mandami i verdetti in audio» — the speaker addresses the
        //    assistant in front of them, so the rule is that assistant's.
        let (dir, pool) = ingest_as(
            "{\"intent\":\"capture\",\"extractions\":[{\
              \"behaviour_rule\":true,\"behaviour_scope\":\"per-user\",\
              \"body\":\"Manda a questo utente i riassunti e i verdetti finali come \
              messaggio audio.\"}]}",
            "mandami tu i riassunti e i verdetti finali in audio",
        )
        .await;
        assert_eq!(
            rules_page_of(&pool, "samvisebot").await,
            vec![RULE.to_owned()],
            "a rule told to this assistant lives in this assistant's wiki"
        );
        assert!(
            rules_page_of(&pool, "alice").await.is_empty(),
            "and nothing of it is written into the speaker's own memory"
        );
        drop(dir);

        // 2. «Vorrei che i verdetti fossero in audio» — nobody is addressed,
        //    so the rule is the speaker's and travels with them.
        let (dir, pool) = ingest_as(
            "{\"intent\":\"capture\",\"extractions\":[{\
              \"behaviour_rule\":true,\"behaviour_scope\":\"user-global\",\
              \"body\":\"Manda a questo utente i riassunti e i verdetti finali come \
              messaggio audio.\"}]}",
            "vorrei che i riassunti e i verdetti finali fossero in formato audio",
        )
        .await;
        assert_eq!(
            rules_page_of(&pool, "alice").await,
            vec![RULE.to_owned()],
            "a rule addressed to nobody lives in the speaker's own wiki"
        );
        assert!(
            rules_page_of(&pool, "samvisebot").await.is_empty(),
            "and the assistant that happened to hear it keeps nothing"
        );
        assert_eq!(
            recall_behaviour_rules(&pool, &req_consumer("?", "alice", "botdeploy"))
                .await
                .iter()
                .map(|(_, b, s)| (b.as_str(), *s))
                .collect::<Vec<_>>(),
            vec![(RULE, BehaviourScope::UserGlobal)],
            "and it is served as the user's own everywhere-rule"
        );
        drop(dir);

        // 3. «Preferisco il caffè» — true with no assistant in the room, so
        //    it stays a taste and reaches no rules page at all.
        let (dir, pool) = ingest_as(
            "{\"intent\":\"capture\",\"extractions\":[{\
              \"fact_type\":\"preference\",\"salience\":\"normal\",\
              \"body\":\"Alice preferisce il caffè al tè.\"}]}",
            "preferisco il caffè al tè",
        )
        .await;
        let buffered = capture_buffer::find_all_buffered(&pool, 100).await.unwrap();
        assert_eq!(buffered.len(), 1, "the taste was captured all the same");
        assert_eq!(buffered[0].subject, Principal::User("alice".into()));
        assert!(
            rules_page_of(&pool, "samvisebot").await.is_empty()
                && rules_page_of(&pool, "alice").await.is_empty(),
            "a taste reaches no rules page — not the agent's, not the speaker's"
        );
        assert!(
            recall_behaviour_rules(&pool, &req_consumer("?", "alice", "botdeploy"))
                .await
                .is_empty(),
            "and the rules channel stays empty: knowledge is never served as a directive"
        );
        drop(dir);
    }

    /// A standing directive is filed because the turn is a `capture`, and is
    /// filed nowhere at all when it is not.
    ///
    /// `behaviour_rule` is read where extractions are read, and extractions
    /// are read on `capture` (and the structural hybrid) and nowhere else. So
    /// the flag is not what files a directive — the intent above it is, and a
    /// classifier answering `skip` has thrown the rule away before a single
    /// line of Part 7 applies. Filing per scope is covered by its own tests;
    /// what this one pins is the gate over them.
    #[tokio::test]
    async fn a_standing_directive_is_filed_only_because_the_turn_is_a_capture() {
        const TURN: &str = "One thing I keep forgetting to ask. Keep it short with me. \
                            Give me the answer, not the preamble.";
        const RULE: &str = "Answer concisely: give the answer without the preamble.";

        // Classified the way the prompt now asks: a capture carrying one
        // directive.
        let (dir, tree, pool) = setup_agent_workdir().await;
        let llm = FakeLlmBackend::new(
            "fake",
            "{\"intent\":\"capture\",\"extractions\":[{\
              \"behaviour_rule\":true,\"behaviour_scope\":\"per-user\",\
              \"body\":\"Answer concisely: give the answer without the preamble.\"}],\
              \"suggested_seed\":\"Ok.\"}",
        );
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req_consumer(TURN, "alice", "botdeploy"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");
        assert_eq!(resp.intent, IntentKind::Capture);
        let filed = fact_index::find_by_filters(
            &pool,
            &fact_index::FactFilters {
                wiki_id: Some("samvisebot".to_owned()),
                ..Default::default()
            },
        )
        .await
        .unwrap();
        assert_eq!(filed.len(), 1, "the directive reaches the agent's own wiki");
        assert_eq!(filed[0].text, RULE);
        drop(dir);

        // The same words, classified `skip`. Nothing about the extraction
        // changed — there simply is no extraction, because the intent decides
        // whether one is read.
        let (dir, tree, pool) = setup_agent_workdir().await;
        let llm = FakeLlmBackend::new(
            "fake",
            "{\"intent\":\"skip\",\"extractions\":[],\"suggested_seed\":\"Ok.\"}",
        );
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req_consumer(TURN, "alice", "botdeploy"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");
        assert_eq!(resp.intent, IntentKind::Skip);
        assert!(
            fact_index::find_by_filters(
                &pool,
                &fact_index::FactFilters {
                    wiki_id: Some("samvisebot".to_owned()),
                    ..Default::default()
                },
            )
            .await
            .unwrap()
            .is_empty(),
            "a directive classified `skip` is filed nowhere — the rule is lost with the turn"
        );
        assert_eq!(
            fact_index::count_active_in_wiki(&pool, "alice")
                .await
                .unwrap(),
            0,
            "and it does not fall back into the user's own memory either"
        );
        assert!(
            resp.rules.as_deref().unwrap_or_default().is_empty(),
            "nothing is served back as a standing rule"
        );
        drop(dir);
    }

    /// Two people take opposite positions on one open decision, and both
    /// stand.
    ///
    /// A stated position is durable knowledge, not chit-chat: it has to be
    /// stored at all, which is the half that was being lost. And the fact
    /// already on record is not overtaken by disagreeing with it — the second
    /// speaker is not correcting the first, they are contradicting them, and a
    /// memory that keeps only the later one has silently picked a winner.
    #[tokio::test]
    async fn two_positions_on_one_decision_are_both_stored_and_neither_overtakes_the_other() {
        const TURN: &str = "I'm not convinced. Range in winter is the problem, \
                            I'd take a hybrid.";
        let (dir, tree, pool) = setup_family().await;
        // Carol's position, already on record and readable by Bob — an
        // unreadable fact could not be contradicted, because he would never be
        // shown it.
        let planted = capture::wiki_capture(
            &tree,
            &pool,
            fake_embedder(),
            CaptureRequest {
                subject_external: None,
                slot: None,
                slot_value: None,
                authored_refs: Vec::new(),
                wiki_id: WikiId::parse("carol").unwrap(),
                page: Some(PathBuf::from("cucina.md")),
                body: "Carol wants an electric car: charging at home solves it.".into(),
                subject: Principal::User("carol".into()),
                allow: vec![Principal::User("bob".into())],
                sender: None,
                fact_type: Some("preference".into()),
                page_description: None,
                topics: vec!["car".into(), "electric".into()],
                dedup_threshold: Some(0.99),
                valid_from: None,
                valid_to: None,
                style: None,
                salience: None,
            },
        )
        .await
        .expect("plant");

        // The classifier states Bob's position and supersedes nothing; the
        // reconciliation stage, shown Carol's fact, retires nothing either.
        let classify = "{\"intent\":\"capture\",\"extractions\":[{\
            \"subject_id\":\"user:bob\",\"fact_type\":\"preference\",\"style\":\"prosa\",\
            \"salience\":\"normal\",\
            \"body\":\"Bob prefers a hybrid: winter range is the problem with an electric car.\",\
            \"topics\":[\"car\",\"hybrid\"],\"supersede_target\":null}],\
            \"suggested_seed\":\"Noted.\"}";
        let llm = ScriptedLlm::new(&[
            classify,
            "{\"closures\":[],\"validity_edits\":[],\"acl_changes\":[]}",
        ]);
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req(TURN, "bob"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");
        assert_eq!(
            resp.intent,
            IntentKind::Capture,
            "a stated position changes what the memory holds"
        );

        // An ordinary capture on a standard wiki waits in the buffer for the
        // light dream to place it; what matters here is that it was taken.
        let buffered = capture_buffer::find_all_buffered(&pool, 100).await.unwrap();
        assert_eq!(buffered.len(), 1, "Bob's position was taken");
        assert_eq!(buffered[0].subject, Principal::User("bob".into()));
        assert!(
            buffered[0].body.contains("hybrid"),
            "and it is his claim, not a rewrite of Carol's: {}",
            buffered[0].body
        );

        let carols = fact_index::find_by_id(&pool, &planted.fact_id)
            .await
            .expect("find")
            .expect("row");
        assert!(
            carols.superseded_at.is_none() && carols.deleted_at.is_none(),
            "disagreeing with a fact never retires it"
        );
        assert!(
            carols.decay_reason.is_none() && carols.valid_to.is_none(),
            "Carol's position still holds — the memory picked no winner"
        );
        drop(dir);
    }

    /// Withdrawing your own claim is a `capture`, and that is the only reason
    /// the stage that can close it ever runs.
    ///
    /// The turn asserts nothing new, so its `extractions` are empty and it
    /// looks from the outside exactly like an ack. What it carries is the
    /// retirement, and the retirement is decided after the reading, by the
    /// reconciliation stage — which runs on a `capture` turn and on no other.
    /// The second half proves the gate rather than describing it: the script
    /// holds ONE response, so a reconciliation call would exhaust it and
    /// panic.
    #[tokio::test]
    async fn withdrawing_your_own_claim_reaches_the_stage_that_can_close_it() {
        const TURN: &str = "Bob was right, it's the 15th. Close mine.";

        async fn plant(tree: &WikiTree, pool: &SqlitePool) -> FactId {
            capture::wiki_capture(
                tree,
                pool,
                fake_embedder(),
                CaptureRequest {
                    subject_external: None,
                    slot: None,
                    slot_value: None,
                    authored_refs: Vec::new(),
                    wiki_id: WikiId::parse("alice").unwrap(),
                    page: Some(PathBuf::from("cucina.md")),
                    body: "Nora's birthday is on the 14th.".into(),
                    subject: Principal::User("alice".into()),
                    allow: Vec::new(),
                    sender: None,
                    fact_type: Some("bio".into()),
                    page_description: None,
                    topics: vec!["family".into(), "birthday".into()],
                    dedup_threshold: Some(0.99),
                    valid_from: None,
                    valid_to: None,
                    style: None,
                    salience: None,
                },
            )
            .await
            .expect("plant")
            .fact_id
        }

        // Classified as the prompt now asks. The classifier names no target:
        // the retirement is the next stage's to decide.
        let (dir, tree, pool) = setup_workdir().await;
        let target = plant(&tree, &pool).await;
        let reconcile = format!(
            "{{\"closures\":[{{\"target\":\"{}\",\"reason\":\"retracted\",\"valid_to\":null}}],\
              \"validity_edits\":[],\"acl_changes\":[]}}",
            target.as_str()
        );
        let llm = ScriptedLlm::new(&[
            "{\"intent\":\"capture\",\"extractions\":[],\"suggested_seed\":\"Done.\"}",
            &reconcile,
        ]);
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req(TURN, "alice"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");
        assert_eq!(resp.intent, IntentKind::Capture);
        let row = fact_index::find_by_id(&pool, &target)
            .await
            .expect("find")
            .expect("row");
        assert_eq!(
            row.decay_reason.as_deref(),
            Some(fact_index::decay::RETRACTED),
            "the speaker's own claim was withdrawn"
        );
        assert!(
            row.valid_to.is_some(),
            "and stamped when it stopped holding"
        );
        drop(dir);

        // The same words read as an ack. ONE scripted response: reaching the
        // reconciliation stage would exhaust the script and panic, so the
        // assertion below is what a `skip` turn really leaves behind.
        let (dir, tree, pool) = setup_workdir().await;
        let target = plant(&tree, &pool).await;
        let llm = ScriptedLlm::new(&["{\"intent\":\"skip\",\"extractions\":[],\
                                      \"suggested_seed\":\"Ok.\"}"]);
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req(TURN, "alice"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");
        assert_eq!(resp.intent, IntentKind::Skip);
        let row = fact_index::find_by_id(&pool, &target)
            .await
            .expect("find")
            .expect("row");
        assert!(
            row.decay_reason.is_none() && row.valid_to.is_none(),
            "under `skip` nothing can close it: the withdrawn claim stays live for ever"
        );
        drop(dir);
    }

    /// A plain sentence about somebody outside the roster is filed, not looked
    /// up.
    ///
    /// The name is unresolvable, and that is exactly why the fact is worth
    /// having — it is the subject of what is being written
    /// (`subject_external`), not a reference to go and find. Read as a
    /// reference it costs the fact twice over: the turn writes nothing, and
    /// the name never enters the memory at all, so the next turn cannot
    /// resolve it either.
    #[tokio::test]
    async fn a_statement_about_somebody_outside_the_roster_is_filed_not_looked_up() {
        const TURN: &str = "Sam is taking over the deployment side.";
        const PLAN: &str = "{\"intent\":\"capture\",\"extractions\":[{\
            \"subject_id\":\"user:alice\",\"subject_external\":\"Sam\",\
            \"fact_type\":\"state\",\"style\":\"prosa\",\
            \"body\":\"Sam is taking over the deployment side.\",\
            \"topics\":[\"work\",\"deployment\"]}],\"suggested_seed\":\"Noted.\"}";

        let (dir, tree, pool) = setup_workdir().await;
        let llm = FakeLlmBackend::new("fake", PLAN);
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req(TURN, "alice"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");
        assert_eq!(resp.intent, IntentKind::Capture);
        let buffered = capture_buffer::find_all_buffered(&pool, 100).await.unwrap();
        assert_eq!(buffered.len(), 1, "the statement is taken");
        assert_eq!(
            buffered[0].subject_external.as_deref(),
            Some("Sam"),
            "and it is filed as being ABOUT the person it names"
        );
        drop(dir);

        // The same words read as a question about a name the memory might
        // hold. A recall writes nothing, so the fact is gone and so is Sam.
        let (dir, tree, pool) = setup_workdir().await;
        let llm = FakeLlmBackend::new(
            "fake",
            "{\"intent\":\"recall\",\"extractions\":[],\"suggested_seed\":\"\"}",
        );
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req(TURN, "alice"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");
        assert_eq!(resp.intent, IntentKind::Recall);
        assert!(
            capture_buffer::find_all_buffered(&pool, 100)
                .await
                .unwrap()
                .is_empty(),
            "a recall writes nothing: the name is never filed and cannot be resolved later"
        );
        drop(dir);
    }

    /// The subject fields are shown with VALUES in them, the field name is
    /// forbidden as one, and what the prompt says a field name COSTS is what
    /// the engine does with it.
    ///
    /// On two turns of a public-demo corpus the classifier wrote the literal
    /// string `subject_external` into `subject_id`. The section explained both
    /// fields well and never showed one worked pair with the values side by
    /// side, which is the only form that makes "a principal here, a name
    /// there" unmistakable.
    ///
    /// **The claim is checked against the code, not quoted.** Pinning the
    /// sentence froze it: the prompt went on saying a field name lands the
    /// fact under the sender for two commits after the engine had started
    /// reading it back off the audience, and the assertion held the false
    /// version in place. So the two landing places are asserted where they are
    /// decided.
    #[test]
    fn the_prompt_and_the_engine_agree_on_what_a_field_name_costs() {
        assert!(
            BUNDLED_INGEST_PROMPT_MD
                .contains("NEVER write the word `subject_external` — or any other field name"),
            "the fence against writing a field name as a value is gone"
        );
        for pair in ["\"Pepper\"", "\"Marco\""] {
            assert!(
                BUNDLED_INGEST_PROMPT_MD.contains(pair),
                "the worked subject pair carrying {pair} is gone from the prompt"
            );
        }
        assert!(
            names_a_field("subject_external"),
            "the prompt says a field name is read as an empty box"
        );
        let named_thing = |allow: &[&str]| {
            let allow: Vec<String> = allow.iter().map(|s| (*s).to_owned()).collect();
            let unit = CaptureUnit {
                subject_external: Some("Pepper"),
                allow_ids: &allow,
                body: Some("Pepper is asleep on the new kitchen floor."),
                ..bare_unit()
            };
            subject_from_the_audience(&unit)
        };
        assert_eq!(
            named_thing(&["group:famiglia"]),
            Some(Principal::Group("famiglia".to_owned())),
            "the prompt says one group in the audience answers for a named thing"
        );
        assert_eq!(
            named_thing(&[]),
            None,
            "and the prompt says it otherwise falls to the sender, which is what an \
             unanswered subject does downstream"
        );
    }

    /// A `CaptureUnit` with every field empty, for a test that cares about two
    /// of them.
    const fn bare_unit() -> CaptureUnit<'static> {
        CaptureUnit {
            target_wiki_id: None,
            target_page: None,
            subject_id: None,
            subject_external: None,
            allow_ids: &[],
            fact_type: None,
            valid_from: None,
            valid_to: None,
            style: None,
            page_description: None,
            salience: None,
            requested_container: false,
            engine_rule: false,
            behaviour_rule: false,
            behaviour_scope: None,
            behaviour_about: None,
            topics: &[],
            body: None,
            supersede_target: None,
            conflicts_with: None,
            slot: None,
            slot_value: None,
            attachments: &[],
        }
    }

    /// The identity core is complete among what the speaker may READ, and the
    /// prompt says so where the model is told it may rely on it.
    ///
    /// A card's slots are filtered by the speaker's own read access
    /// ([`IdentityCore::served`]), so a value with a narrower audience is not
    /// in the block at all. Told the block was simply complete, the model
    /// reads an absence as an empty slot and writes a second value beside a
    /// first it was never shown. The engine catches that pair itself
    /// ([`value_filling_the_same_slot`]) — but only when the claim
    /// names its slot, which the model does because the prompt asks, and it
    /// asks because it knows the absence proves nothing.
    #[test]
    fn bundled_ingest_prompt_does_not_promise_a_complete_identity_core() {
        assert!(
            BUNDLED_INGEST_PROMPT_MD
                .contains("complete **among the facts you are allowed to see**"),
            "the identity-core block is promised complete again"
        );
        assert!(
            BUNDLED_INGEST_PROMPT_MD.contains("never a slot you know to be empty"),
            "the model may read an absence in the block as an empty slot again"
        );
    }

    /// A repeated measurement is a history, and the reconciler is told so
    /// where it decides a supersede — not at the end of the paragraph that
    /// decides one.
    ///
    /// Two weighings of the same cat three days apart, «3.9 kilos» and «4.05,
    /// same scales as Wednesday», became one: the reconciler superseded the
    /// first, and the reading of 15 July is gone from the record along with
    /// the trend the speaker had just described. The rule against it was
    /// already in the prompt, word for word: what it lacked was a place to be
    /// read from. A closing clause of the paragraph that decides a supersede
    /// arrives after the case it contradicts, which is why the position is
    /// asserted and not just the words. It carries the cue the turn itself
    /// gives, too: a message that COMPARES the new value with the old one is
    /// asserting that both are true.
    #[test]
    fn bundled_reconcile_prompt_keeps_a_repeated_measurement_as_a_history() {
        assert!(
            BUNDLED_INGEST_RECONCILE_MD
                .contains("A MEASUREMENT TAKEN ON A DAY IS NEVER SUPERSEDED BY THE NEXT ONE."),
            "the measurement rule is gone, and a weight history collapses to its last reading"
        );
        assert!(
            BUNDLED_INGEST_RECONCILE_MD.contains("same scales as Wednesday"),
            "the comparison cue is gone — it is the evidence the turn itself carries"
        );
        // Its own paragraph is the point of the change: as a closing clause of
        // the paragraph that OPENS by calling a number-and-a-date pair a
        // supersede, it was read after the case it contradicts.
        assert!(
            BUNDLED_INGEST_RECONCILE_MD
                .lines()
                .any(|l| l.trim_start().starts_with("**A MEASUREMENT TAKEN ON A DAY")),
            "the measurement rule is a clause inside another paragraph again"
        );
        let (rule_at, verb_three_at) = (
            BUNDLED_INGEST_RECONCILE_MD
                .find("A MEASUREMENT TAKEN ON A DAY")
                .expect("the rule"),
            BUNDLED_INGEST_RECONCILE_MD
                .find("3. `validity_edits`")
                .expect("the next verb"),
        );
        assert!(
            rule_at < verb_three_at,
            "the measurement rule belongs to the supersede verb, not to a later one"
        );
    }

    /// A bare day of the month is an anchor only where there is one day to
    /// find, and a person named only by relationship is not resolved by
    /// reaching for the roster.
    ///
    /// Both sentences come from one scene of a public-demo replay. On 3 April
    /// «Nora's birthday is on the 14th» was stored as «14 May» — a month
    /// nothing in the turn pointed at — while a related turn two days later
    /// resolved the same bare ordinal to April: the prompt listed "the 5th"
    /// among the anchors that MUST be resolved and never said where the month
    /// comes from. It comes from the clock for a thing that happens once, and
    /// from nowhere at all for a date that comes round every year, where "the
    /// next 14th" is a fact about today rather than about the person. Then
    /// «Mum's birthday is the 15th, not the 14th», said by Bob, was stored as
    /// «Alice's birthday is on 15 April»: the roster holds one enrolled
    /// mother, so the model reached for her. The subject guard caught the
    /// filing and could not catch the sentence — the `subject_id` rule forbade
    /// that reach and said nothing about the prose.
    #[test]
    fn bundled_ingest_prompt_pins_a_bare_ordinal_and_an_unnamed_relative() {
        assert!(
            BUNDLED_INGEST_PROMPT_MD
                .contains("A COMMITMENT TAKES THE NEAREST ONE, AN ANNIVERSARY TAKES NONE"),
            "the bare day-of-month rule is gone: a month becomes a guess again"
        );
        assert!(
            BUNDLED_INGEST_PROMPT_MD
                .contains("«L'appuntamento è il 14», said on 3 April, is 14 April."),
            "the worked commitment example, the one case where a month may be found, is gone"
        );
        assert!(
            BUNDLED_INGEST_PROMPT_MD.contains("\"Nora's birthday is on the 14th\""),
            "an anniversary must keep the bare day the turn gave it"
        );
        assert!(
            BUNDLED_INGEST_PROMPT_MD.contains(
                "A PERSON THE TURN NAMES ONLY BY RELATIONSHIP IS UNRESOLVED IN THE `body` TOO"
            ),
            "the prose half of the no-look-alike rule is gone"
        );
    }

    /// The guard's own test, asked of the prose: does the sentence still name
    /// the person the fact was just taken off?
    ///
    /// The two cases are the reason the guard leaves the body alone in the
    /// first place. A name the roster does not hold reads correctly wherever
    /// the fact is filed; the name the subject was taken FROM does not, and
    /// telling them apart is what makes the warning worth reading.
    #[test]
    fn the_body_is_read_for_the_name_the_subject_was_taken_from() {
        let roster = vec![
            enrollment::EnrolledUserLite {
                user_id: "alice".to_owned(),
                aliases: Vec::new(),
                is_agent: false,
            },
            enrollment::EnrolledUserLite {
                user_id: "bob".to_owned(),
                aliases: vec!["Bobby".to_owned()],
                is_agent: false,
            },
        ];
        assert!(
            body_names_user(Some("Alice's birthday is on 15 April."), &roster, "alice"),
            "the sentence says the person the subject guard just refused"
        );
        assert!(
            !body_names_user(
                Some("Bob's mother's birthday is on the 15th."),
                &roster,
                "alice"
            ),
            "a relationship is not a name, so nothing here is about Alice"
        );
        assert!(
            !body_names_user(
                Some("Roberto Sackville is retiring in June."),
                &roster,
                "bob"
            ),
            "a name the roster does not hold reads correctly wherever it is filed"
        );
        assert!(
            body_names_user(Some("Bobby is retiring in June."), &roster, "bob"),
            "a declared alias names its person"
        );
    }

    /// The prompt says what widening is and who finishes it.
    ///
    /// It is neither of the two cases the paragraph above it covers: it
    /// repeats the words and changes the scope. Read as a repeat it is
    /// deduped away, read as a revision it asks the classifier for an id that
    /// is not in the block — the block holds only the rules in force on the
    /// consumer being spoken to, and a rule set on another assistant is not
    /// among them. The engine finds those, so the prompt says so rather than
    /// leaving the model to invent an answer.
    #[test]
    fn bundled_ingest_prompt_says_who_finishes_a_widening() {
        assert!(
            BUNDLED_INGEST_PROMPT_MD
                .contains("WIDENING IS NEITHER OF THOSE, AND IT IS THE ENGINE'S TO FINISH"),
            "widening reads as a repeat or a revision again"
        );
        assert!(
            BUNDLED_INGEST_PROMPT_MD
                .contains("Widening MOVES a rule; it never leaves the narrow copy standing"),
            "the prompt has stopped saying that the narrow copy goes with the widening"
        );
    }

    /// A conversational gag is a family of directive, not a scope, and a room
    /// in the sentence is not evidence that it is a rule of the world.
    ///
    /// The admin's «a rule for you, and it goes for whoever is in the room,
    /// not only for me. Never read an address or a phone number out loud in
    /// here» filed as an ordinary household `rule` fact owned by the parents'
    /// group, and the body it stored had turned "in here" into "in the house".
    /// Two sentences in the prompt sent it there: the NET ROUTING RULE gave
    /// the don't-say family a scope of its own (`per-user`), so a gag for
    /// everyone matched no row of it; and the addressee triage offered «no
    /// smoking in the house» as the shape of a world rule with nothing beside
    /// it to say that the mover, not the room, is the discriminator.
    #[test]
    fn bundled_ingest_prompt_reads_a_gag_for_everyone_as_the_agents_rule() {
        assert!(
            BUNDLED_INGEST_PROMPT_MD.contains("A PLACE IN THE SENTENCE DOES NOT MAKE IT A RULE"),
            "the fence between a house rule and a gag with a room in it is gone"
        );
        assert!(
            BUNDLED_INGEST_PROMPT_MD.contains("A gag is a family of directive, not a scope."),
            "the don't-say row has taken a scope of its own again"
        );

        let row = BUNDLED_INGEST_PROMPT_MD
            .lines()
            .find(|l| l.contains("don't **SAY**"))
            .expect("the net routing rule still has a don't-say row");
        assert!(
            !row.contains("`behaviour_scope: \"per-user\"` — it governs"),
            "the don't-say row pins one scope again: {row}"
        );
        assert!(
            BUNDLED_INGEST_PROMPT_MD.contains("whoever is in the room, not only for me"),
            "the worked agent-wide gag is gone from the examples"
        );
    }

    /// One extraction the engine cannot read is dropped alone; the rest of the
    /// turn files.
    ///
    /// Both turns that hit this stored nothing, which reads exactly like the
    /// bad extraction taking the turn down with it. It does not, and never
    /// did — those turns each carried ONE extraction, so there was nothing
    /// else to save. The belief was held long enough to be worth a test, and
    /// the warning now names the claim that went, because a turn that drops
    /// one of its facts still reports itself as a capture.
    #[tokio::test]
    async fn one_unreadable_subject_does_not_take_the_turn_s_other_captures_with_it() {
        let (dir, tree, pool) = setup_workdir().await;
        // The first extraction carries a bare NAME where a principal goes —
        // the shape that is still dropped, because reading it as the sender
        // would file somebody else's life under whoever spoke. The second is
        // sound.
        let plan = "{\"intent\":\"capture\",\"extractions\":[\
            {\"subject_id\":\"Pepper\",\"fact_type\":\"episode\",\"style\":\"prosa\",\
             \"body\":\"Pepper has been fed.\",\"topics\":[\"pets\",\"feeding\"]},\
            {\"subject_id\":\"user:alice\",\"subject_external\":\"Marco\",\
             \"fact_type\":\"plan\",\"style\":\"prosa-tecnica\",\
             \"body\":\"Marco is dropping the tile samples round on Saturday.\",\
             \"topics\":[\"renovation\",\"tiles\"]}],\"suggested_seed\":\"Noted.\"}";
        let llm = FakeLlmBackend::new("fake", plan);
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req("Pepper has been fed. I caught Marco on the phone.", "alice"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");
        assert_eq!(resp.intent, IntentKind::Capture);
        let buffered = capture_buffer::find_all_buffered(&pool, 100).await.unwrap();
        assert_eq!(
            buffered.len(),
            1,
            "the sound extraction files; only the unreadable one is dropped"
        );
        assert_eq!(
            buffered[0].subject_external.as_deref(),
            Some("Marco"),
            "and it is the one whose subject the engine could read"
        );
        drop(dir);
    }

    /// A closure that says `superseded` closes the fact instead of being
    /// thrown away.
    ///
    /// It is the shape that arrives when the stage really did see the fact
    /// overtaken and had no successor id to name — three of the four times it
    /// happened, the same answer carried a correct `supersedes` entry for a
    /// different pair. Refusing the word left the fact open for ever, which is
    /// the one outcome nobody wanted; `contradicted` is what the reason means,
    /// and it is what the supersede chokepoint stamps anyway.
    #[tokio::test]
    async fn a_closure_reason_of_superseded_is_read_as_contradicted() {
        let (dir, tree, pool) = setup_workdir().await;
        let planted = capture::wiki_capture(
            &tree,
            &pool,
            fake_embedder(),
            CaptureRequest {
                subject_external: None,
                slot: None,
                slot_value: None,
                authored_refs: Vec::new(),
                wiki_id: WikiId::parse("alice").unwrap(),
                page: Some(PathBuf::from("cucina.md")),
                body: "The boiler man is coming on Thursday the nineteenth.".into(),
                subject: Principal::User("alice".into()),
                allow: Vec::new(),
                sender: None,
                fact_type: Some("plan".into()),
                page_description: None,
                topics: vec!["house".into(), "boiler".into()],
                dedup_threshold: Some(0.99),
                valid_from: None,
                valid_to: None,
                style: None,
                salience: None,
            },
        )
        .await
        .expect("plant");

        let reconcile = format!(
            "{{\"closures\":[{{\"target\":\"{}\",\"reason\":\"superseded\",\"valid_to\":null}}],\
              \"validity_edits\":[],\"acl_changes\":[]}}",
            planted.fact_id.as_str()
        );
        let llm = ScriptedLlm::new(&[
            "{\"intent\":\"capture\",\"extractions\":[],\"suggested_seed\":\"Ok.\"}",
            &reconcile,
        ]);
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req("The boiler man's been and gone.", "alice"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        let row = fact_index::find_by_id(&pool, &planted.fact_id)
            .await
            .expect("find")
            .expect("row");
        assert_eq!(
            row.decay_reason.as_deref(),
            Some(fact_index::decay::CONTRADICTED),
            "an out-of-vocabulary reason that means `contradicted` is read as it"
        );
        assert!(row.valid_to.is_some(), "and the window is shut");
        drop(dir);
    }

    /// Both stages that may close a fact answer the case the refused word was
    /// reached for.
    ///
    /// Saying "there is no `superseded` closure" and stopping leaves the model
    /// with the question it asked: the fact IS overtaken and there is no
    /// successor to name. Unanswered, it wrote the word anyway, four times.
    #[test]
    fn the_closing_stages_say_what_to_write_when_there_is_no_successor_to_name() {
        assert!(
            BUNDLED_INGEST_RECONCILE_MD.contains("a closure, reason\n      **\"contradicted\"**"),
            "the reconciler no longer answers the no-successor case"
        );
        assert!(
            BUNDLED_INGEST_RECONCILE_MD.contains("There is no fourth case"),
            "the three-way rule that decides between the verbs and doing nothing is gone"
        );
        assert!(
            BUNDLED_INGEST_CLOSURES_MD.contains("there is no \"superseded\""),
            "the topic-closure pass no longer rules the word out"
        );
    }

    /// Both closing stages are taught the rule the engine enforces: a rule is
    /// not theirs to touch, and a withdrawal is named elsewhere.
    ///
    /// Asserting that a SENTENCE is present defends that sentence after it has
    /// become false — which is what happened here twice. So each assertion
    /// asks for the rule instead: that naming a rule is refused, and where a
    /// withdrawal is really named, which is what lets the stage leave the rule
    /// alone without leaving the person unanswered. A prompt rewritten in
    /// other words passes; one that stops teaching the rule does not.
    #[test]
    fn the_closing_stages_send_a_withdrawal_where_it_is_really_named() {
        for (name, prompt) in [
            ("reconciler", BUNDLED_INGEST_RECONCILE_MD),
            ("closure confirmer", BUNDLED_INGEST_CLOSURES_MD),
        ] {
            let lowered = prompt.to_ascii_lowercase();
            // The rule is taught where the directive is discussed, so the
            // words have to appear together in one passage rather than
            // anywhere in a hundred-thousand-character document.
            let passage = lowered
                .split("standing rule")
                .nth(1)
                .or_else(|| lowered.split("standing directive").nth(1))
                .unwrap_or_default()
                .chars()
                .take(1_800)
                .collect::<String>();
            assert!(
                passage.contains("withdraw_target"),
                "the {name} is no longer told where a withdrawal is really named, \
                 so it has no answer for a person asking to drop a rule"
            );
            assert!(
                passage.contains("refused"),
                "the {name} is no longer told that naming a rule here is refused"
            );
        }
    }

    /// The topic words are told which language they are written in.
    ///
    /// They are neither a machine key nor a sentence, so a language directive
    /// that names only the machinery and the reply leaves them in the gap —
    /// and every worked example of the field being in one language is the
    /// other half of it. An all-English memory came back tagged `acquisto`,
    /// `finanze`, `manutenzione`, and the compiled pages printed those among
    /// their keywords, where a reader sees them.
    #[test]
    fn bundled_ingest_prompt_writes_the_topic_words_in_the_memory_s_language() {
        assert!(
            BUNDLED_INGEST_PROMPT_MD
                .contains("**They are written in the SAME LANGUAGE as the body**"),
            "the topics section does not say which language its words take"
        );
        assert!(
            BUNDLED_INGEST_PROMPT_MD.contains("[\"car\", \"purchase\"]"),
            "the English worked pair is gone, leaving only Italian examples to copy"
        );
        assert!(
            BUNDLED_INGEST_PROMPT_MD.contains("[\"strumenti\", \"configurazione\"]"),
            "the Italian pair is gone, and an Italian memory has no worked example of its own"
        );
    }

    /// A fact with no page yet is not reported as a smart wiki.
    ///
    /// Both refusals are right and they are different events. Told apart, an
    /// operator reading the log either goes and looks at wiki-level governance
    /// or understands that the capture had simply not been placed yet; told as
    /// one, they get the first answer and an empty `wiki_id` to go with it.
    #[tokio::test]
    async fn an_edit_on_a_fact_with_no_page_yet_is_not_reported_as_a_smart_wiki() {
        let (dir, tree, _pool) = setup_workdir().await;
        assert!(
            EditRefusal::of(&tree, "alice").is_none(),
            "a standard wiki is no refusal at all"
        );
        let refusal = EditRefusal::of(&tree, "").expect("an unresolvable wiki still refuses");
        assert!(
            matches!(refusal, EditRefusal::NoWikiYet),
            "an absent wiki id is the buffered-capture case, not the smart one"
        );
        assert_ne!(
            EditRefusal::NoWikiYet.as_reason(),
            EditRefusal::SmartWiki.as_reason(),
            "the two refusals must not read as the same event"
        );
        drop(dir);
    }

    /// The standing directive Zoe laid down survives the sentence about
    /// dinner two days later.
    ///
    /// The structural passes leave the rules page alone — the compiler's
    /// gather, refile, the navigator's walk, and the cross-page half of dedup
    /// (rule pairs with rule there, never with an ordinary fact) — and the one
    /// stage that reached it is the only one that can take a fact away. So an ordinary
    /// remark arrived as a candidate beside «answer me concisely», the two
    /// shared a speaker and a wiki, and the remark was recorded as replacing
    /// the rule: the directive died, the page it lived on emptied overnight,
    /// and the turn that would have widened it three weeks later had nothing
    /// left to widen.
    #[tokio::test]
    async fn an_ordinary_remark_cannot_replace_a_standing_directive() {
        let (dir, tree, pool) = setup_agent_workdir().await;

        // Day one: the directive.
        let rule_llm = FakeLlmBackend::new(
            "fake",
            "{\"intent\":\"capture\",\"extractions\":[{\
              \"behaviour_rule\":true,\"behaviour_scope\":\"per-user\",\
              \"body\":\"Answer concisely: give the answer without the preamble.\"}],\
              \"suggested_seed\":\"Ok.\"}",
        );
        let rule_resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &rule_llm,
            None,
            req_consumer(
                "Keep it short with me. Give me the answer, not the preamble.",
                "alice",
                "botdeploy",
            ),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");
        let rule_id = rule_resp.capture_id.expect("the directive is filed");

        // Two days later: an ordinary remark, and a reconciliation stage that
        // reaches for the rule. Its verdict is scripted the way the failing
        // run answered — this test is about what the engine does with it.
        // The CLOSURE verb, deliberately: it names no successor, so nothing
        // but the rules-page guard can refuse it. A scripted `supersedes`
        // would be turned away by the older rule that a successor must be a
        // fact this turn filed, and the test would pass without proving
        // anything.
        let reconcile = format!(
            "{{\"closures\":[{{\"target\":\"{}\",\"reason\":\"contradicted\",\
              \"valid_to\":null}}],\"supersedes\":[],\
              \"validity_edits\":[],\"acl_changes\":[]}}",
            rule_id.as_str(),
        );
        let llm = ScriptedLlm::new(&[
            "{\"intent\":\"capture\",\"extractions\":[{\
              \"subject_id\":\"user:alice\",\"fact_type\":\"preference\",\"style\":\"prosa\",\
              \"body\":\"Zoe would rather not have rice again tomorrow.\",\
              \"topics\":[\"meals\",\"rice\"]}],\"suggested_seed\":\"Noted.\"}",
            &reconcile,
        ]);
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req_consumer("Can we not do rice again tomorrow.", "alice", "botdeploy"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        let rule = fact_index::find_by_id(&pool, &rule_id)
            .await
            .expect("find")
            .expect("the directive is still a row");
        assert!(
            rule.superseded_at.is_none() && rule.deleted_at.is_none(),
            "a remark about dinner does not replace a standing directive"
        );
        assert!(
            rule.valid_to.is_none() && rule.decay_reason.is_none(),
            "and it does not end one either: a closed window stops a rule steering the agent"
        );
        // The remark itself is kept, on its own account.
        let buffered = capture_buffer::find_all_buffered(&pool, 100).await.unwrap();
        assert_eq!(buffered.len(), 1, "the remark is a fact of its own");
        assert!(
            buffered[0].body.contains("rice"),
            "and it is the remark, not the rule: {}",
            buffered[0].body
        );
        drop(dir);
    }

    /// Withdrawing a rule out loud works, and the page says so afterwards.
    ///
    /// «Forget the one about short answers» asserts nothing new, so the turn
    /// files no extraction; what carries it is `withdrawal` plus the rule's
    /// own id in `withdraw_target`, resolved against the block of directives
    /// the classifier is shown. That block is the only place a rule is ever
    /// visible with its id — it never travels with the recalled facts — which
    /// is why this is the road and the closing stages are not.
    #[tokio::test]
    async fn a_rule_is_withdrawn_when_somebody_says_so_of_the_rule() {
        let (dir, tree, pool) = setup_agent_workdir().await;
        sqlx::query("INSERT INTO enrollment_users (user_id, is_admin) VALUES ('alice', 0)")
            .execute(&pool)
            .await
            .unwrap();
        let rule_id = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new(
                "fake",
                "{\"intent\":\"capture\",\"extractions\":[{\
                  \"behaviour_rule\":true,\"behaviour_scope\":\"per-user\",\
                  \"body\":\"Answer concisely: give the answer without the preamble.\"}],\
                  \"suggested_seed\":\"Ok.\"}",
            ),
            None,
            req_consumer(
                "Keep it short with me. Give me the answer, not the preamble.",
                "alice",
                "botdeploy",
            ),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest")
        .capture_id
        .expect("the directive is filed");

        let withdraw = format!(
            "{{\"intent\":\"capture\",\"withdrawal\":true,\"withdraw_target\":\"{}\",\
              \"extractions\":[],\"suggested_seed\":\"Ok.\"}}",
            rule_id.as_str()
        );
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", &withdraw),
            None,
            req_consumer(
                "Forget that rule about keeping it short.",
                "alice",
                "botdeploy",
            ),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        let row = fact_index::find_by_id(&pool, &rule_id)
            .await
            .expect("find")
            .expect("row");
        assert_eq!(
            row.decay_reason.as_deref(),
            Some(fact_index::decay::RETRACTED),
            "a rule its own subject withdraws is withdrawn"
        );
        assert!(row.valid_to.is_some(), "and stops steering the agent");
        assert!(
            row.deleted_at.is_none(),
            "closing is not deleting: the record stays"
        );

        // The channel stops serving it, which is what "withdrawn" means to
        // everyone downstream.
        let served = recall_behaviour_rules(&pool, &req_consumer("?", "alice", "botdeploy")).await;
        assert!(
            served.is_empty(),
            "a withdrawn rule must stop steering the agent: {served:?}"
        );

        // The words stay on the page — cutting a live row's region hands it to
        // the orphan sweep, which tombstones it — and the page says they no
        // longer bind, so it stays a truthful list of what does.
        let page = std::fs::read_to_string(
            tree.wikis_dir()
                .join("samvisebot")
                .join(crate::wiki::RULES_FILENAME),
        )
        .expect("the rules page is there");
        assert!(
            page.contains("without the preamble"),
            "the rule's own words are untouched: {page}"
        );
        assert!(
            page.contains(crate::wiki::WITHDRAWN_NOTE_PREFIX),
            "and the page says it was withdrawn: {page}"
        );
        // The marker survived, so nothing collected it as an orphan.
        assert!(
            row.region_start.is_some(),
            "the row keeps its region: nothing swept it"
        );
        drop(dir);
    }

    /// A rule is never a candidate of the reconciliation stage, on any turn.
    ///
    /// It cannot be: a behaviour rule travels on its own channel and never on
    /// recall, so the stage would be judging something it was never shown.
    /// Both roads a person has to a rule — revising it and withdrawing it —
    /// are resolved against the block the classifier IS shown, where a rule
    /// appears with its id, and neither passes through here.
    #[tokio::test]
    async fn a_standing_rule_is_never_a_reconciliation_candidate() {
        let rule = {
            let mut h = sample_recall_hit("0190f3c2-7a4e-7c31-9b02-2f6a1c8e5d21");
            h.source_path = format!("wikis/alice/{}", crate::wiki::RULES_FILENAME);
            h
        };
        let plain = sample_recall_hit("0190f3c2-7a4e-7c31-9b02-2f6a1c8e5d22");
        let flat = vec![rule.clone(), plain.clone()];
        let (dir, _tree, pool) = setup_workdir().await;

        let got = reconcile_candidates(
            &pool,
            &fake_embedder(),
            "forget that rule about keeping it short",
            &flat,
            &[],
            &SenderContext::user("alice"),
            0,
            &[],
        )
        .await;
        assert!(
            !got.iter().any(|h| h.fact_id == rule.fact_id),
            "a rule must never reach the stage that judges recalled facts"
        );
        assert!(
            got.iter().any(|h| h.fact_id == plain.fact_id),
            "an ordinary fact still is a candidate"
        );
        drop(dir);
    }

    /// A refused withdrawal is said out loud, not answered with "Ok."
    ///
    /// The person asked for something and the answer is no. The one-shot
    /// governance channel in the response's `rules` field is where the turn
    /// says which no it is — the same channel the agent-wide refusal uses.
    #[test]
    fn a_refused_withdrawal_tells_the_person_which_refusal_it_was() {
        let for_everyone = RuleRetractionRefused::NeedsTheAdmin.notice();
        let somebody_elses = RuleRetractionRefused::NotYours.notice();
        assert!(
            for_everyone.contains("administrator") && for_everyone.contains("still in force"),
            "the agent-wide refusal must name the admin and say the rule stands: {for_everyone}"
        );
        assert!(
            somebody_elses.contains("somebody else") && somebody_elses.contains("still in force"),
            "the not-yours refusal must say whose it is and that the rule stands: {somebody_elses}"
        );
        assert_ne!(
            for_everyone, somebody_elses,
            "two different refusals must not read the same"
        );
        // And it reaches the field the consumer actually receives.
        let rules = assemble_rules_block(Some(for_everyone.to_owned()), None)
            .expect("a notice alone still fills the rules field");
        assert!(rules.contains("administrator"));
    }

    /// File one rule and hand back its id — shared by the crossings below.
    async fn file_rule(
        pool: &SqlitePool,
        tree: &WikiTree,
        who: &str,
        scope: &str,
        body: &str,
    ) -> FactId {
        let plan = format!(
            "{{\"intent\":\"capture\",\"extractions\":[{{\
              \"behaviour_rule\":true,\"behaviour_scope\":\"{scope}\",\
              \"body\":\"{body}\"}}],\"suggested_seed\":\"Ok.\"}}"
        );
        wiki_ingest_message(
            pool,
            tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", &plan),
            None,
            req_consumer("a rule", who, "botdeploy"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest")
        .capture_id
        .expect("the rule is filed")
    }

    /// Ask for a withdrawal, the way the prompt asks the classifier to.
    async fn withdraw(
        pool: &SqlitePool,
        tree: &WikiTree,
        who: &str,
        target: &FactId,
    ) -> IngestResponse {
        let plan = format!(
            "{{\"intent\":\"capture\",\"withdrawal\":true,\
              \"withdraw_target\":\"{}\",\"extractions\":[],\
              \"suggested_seed\":\"Ok.\"}}",
            target.as_str()
        );
        wiki_ingest_message(
            pool,
            tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", &plan),
            None,
            req_consumer("forget that rule", who, "botdeploy"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest")
    }

    /// Has this rule's window been shut?
    async fn is_withdrawn(pool: &SqlitePool, id: &FactId) -> bool {
        fact_index::find_by_id(pool, id)
            .await
            .expect("find")
            .expect("row")
            .valid_to
            .is_some()
    }

    /// The four crossings of a withdrawal, each driven through a real turn.
    ///
    /// The previous version of this called the authority helper with
    /// candidates built by hand, which proved the door and not that anybody
    /// could reach it — and nobody could: a rule never enters the candidates
    /// the closing stages judge, so every withdrawal was refused as a
    /// hallucinated id and the person heard "Ok." Here the classifier answers
    /// with `withdrawal` and `withdraw_target`, exactly as the prompt now
    /// asks, and the turn goes through `wiki_ingest_message`.
    #[tokio::test]
    async fn the_four_crossings_of_a_withdrawal_through_a_real_turn() {
        // 1 — the author takes back their own rule.
        let (dir, tree, pool) = setup_agent_workdir().await;
        sqlx::query("INSERT INTO enrollment_users (user_id, is_admin) VALUES ('alice', 0)")
            .execute(&pool)
            .await
            .unwrap();
        let mine = file_rule(&pool, &tree, "alice", "per-user", "Answer concisely.").await;
        let resp = withdraw(&pool, &tree, "alice", &mine).await;
        assert!(
            is_withdrawn(&pool, &mine).await,
            "the person who set a rule may take it back"
        );
        assert!(
            !resp.rules.as_deref().unwrap_or_default().contains("NOTE —"),
            "and hears no refusal: {:?}",
            resp.rules
        );
        drop(dir);

        // 2 — a rule this speaker was never shown. Somebody else's per-user
        // rule is not in the block they are served, so its id is one they
        // cannot have been given: the withdrawal names nothing in force, the
        // rule is untouched, and they are told rather than answered "Ok."
        let (dir, tree, pool) = setup_agent_workdir().await;
        for (u, admin) in [("alice", 1), ("zoe", 0)] {
            sqlx::query("INSERT INTO enrollment_users (user_id, is_admin) VALUES (?, ?)")
                .bind(u)
                .bind(admin)
                .execute(&pool)
                .await
                .unwrap();
        }
        let zoes = file_rule(&pool, &tree, "zoe", "per-user", "Answer concisely.").await;
        let resp = withdraw(&pool, &tree, "alice", &zoes).await;
        assert!(
            !is_withdrawn(&pool, &zoes).await,
            "being the admin is not being the person who said it"
        );
        assert!(
            resp.rules
                .as_deref()
                .unwrap_or_default()
                .contains("none of the rules in force"),
            "and the refusal is told, not swallowed: {:?}",
            resp.rules
        );
        drop(dir);

        // 3 and 4 — a rule for everyone: the admin may, a normal user may not.
        for (who, expect_withdrawn) in [("zoe", false), ("alice", true)] {
            let (dir, tree, pool) = setup_agent_workdir().await;
            for (u, admin) in [("alice", 1), ("zoe", 0)] {
                sqlx::query("INSERT INTO enrollment_users (user_id, is_admin) VALUES (?, ?)")
                    .bind(u)
                    .bind(admin)
                    .execute(&pool)
                    .await
                    .unwrap();
            }
            sqlx::query("UPDATE enrollment_users SET is_agent = 1 WHERE user_id = 'samvisebot'")
                .execute(&pool)
                .await
                .unwrap();
            let everyones = file_rule(
                &pool,
                &tree,
                "alice",
                "agent-wide",
                "Never give medical advice.",
            )
            .await;
            let resp = withdraw(&pool, &tree, who, &everyones).await;
            assert_eq!(
                is_withdrawn(&pool, &everyones).await,
                expect_withdrawn,
                "a rule for everyone, asked by {who}"
            );
            if !expect_withdrawn {
                assert!(
                    resp.rules
                        .as_deref()
                        .unwrap_or_default()
                        .contains("administrator"),
                    "a normal user must be told an admin has to lift it: {:?}",
                    resp.rules
                );
            }
            drop(dir);
        }
    }

    /// `withdrawal` on a turn that also writes facts changes nothing about
    /// the facts, and a turn that writes facts without it withdraws nothing.
    ///
    /// The two are independent: the flag says the turn takes something back,
    /// the extractions say what it states. A turn can do both.
    #[tokio::test]
    async fn a_withdrawal_flag_does_not_disturb_the_facts_the_turn_states() {
        for declared in [false, true] {
            let (dir, tree, pool) = setup_workdir().await;
            let plan = format!(
                "{{\"intent\":\"capture\",\"withdrawal\":{declared},\"extractions\":[{{\
                  \"subject_id\":\"user:alice\",\"fact_type\":\"state\",\"style\":\"prosa\",\
                  \"body\":\"Alice lives in Bologna.\",\"topics\":[\"home\",\"city\"]}}],\
                  \"suggested_seed\":\"Noted.\"}}"
            );
            wiki_ingest_message(
                &pool,
                &tree,
                fake_embedder(),
                &FakeLlmBackend::new("fake", &plan),
                None,
                req("I live in Bologna", "alice"),
                &IngestPolicy::default(),
            )
            .await
            .expect("ingest");
            let buffered = capture_buffer::find_all_buffered(&pool, 100).await.unwrap();
            assert_eq!(
                buffered.len(),
                1,
                "withdrawal = {declared}: the stated fact is taken either way"
            );
            drop(dir);
        }
    }

    /// The four verbs, one test each: what each refuses on a rule, and what
    /// it still does on an ordinary fact so the refusal is not the whole
    /// function saying no.
    ///
    /// `validate_*` is where the line falls for all four, so the check is made
    /// there rather than through a whole turn: each door is one call, and a
    /// door deleted makes exactly one of these go red.
    #[test]
    fn each_verb_refuses_a_standing_directive_and_still_works_on_an_ordinary_fact() {
        // The same fact twice, differing only in the page it sits on — so the
        // refusal below can be nothing but the rules page.
        let mut rule = sample_recall_hit("0190f3c2-7a4e-7c31-9b02-2f6a1c8e5d11");
        rule.source_path = format!("wikis/alice/{}", crate::wiki::RULES_FILENAME);
        rule.text = "Answer concisely: give the answer without the preamble.".into();
        let plain = sample_recall_hit("0190f3c2-7a4e-7c31-9b02-2f6a1c8e5d12");
        let groups: Vec<String> = Vec::new();

        // The closure verb judges recalled facts, and a rule is never one:
        // withdrawing a rule is named to the classifier instead. Every reason
        // is refused here, the one that IS a withdrawal included — that road
        // does not run through this function.
        for reason in ["retracted", "completed", "contradicted"] {
            let closure = LlmClosure {
                target: Some(rule.fact_id.as_str().to_owned()),
                reason: Some(reason.to_owned()),
                valid_to: None,
            };
            let got = validate_closure(
                &closure,
                std::slice::from_ref(&rule),
                &[],
                "alice",
                &groups,
                &[],
            );
            assert!(
                matches!(got, Err(ClosurePlanError::TargetIsAStandingRule(_))),
                "a `{reason}` closure on a standing directive: {got:?}"
            );
        }
        // And the same three all pass on an ordinary fact, so the refusal is
        // about the target and not about the verb.
        for reason in ["retracted", "completed", "contradicted"] {
            let closure = LlmClosure {
                target: Some(plain.fact_id.as_str().to_owned()),
                reason: Some(reason.to_owned()),
                valid_to: None,
            };
            assert!(
                validate_closure(
                    &closure,
                    std::slice::from_ref(&plain),
                    &[],
                    "alice",
                    &groups,
                    &[]
                )
                .is_ok(),
                "`{reason}` is refused on an ordinary fact"
            );
        }

        // The validity-edit verb: refused on a rule, fine on an ordinary fact.
        let edit = |target: &RecallHit| LlmValidityEdit {
            target: Some(target.fact_id.as_str().to_owned()),
            valid_from: None,
            valid_to: Some("2026-06-30T00:00:00Z".to_owned()),
        };
        assert!(
            matches!(
                validate_validity_edit(&edit(&rule), std::slice::from_ref(&rule), "alice", &groups),
                Err(ValidityEditPlanError::TargetIsAStandingRule(_))
            ),
            "re-dating a rule ends it under another name"
        );
        assert!(
            validate_validity_edit(
                &edit(&plain),
                std::slice::from_ref(&plain),
                "alice",
                &groups
            )
            .is_ok(),
            "an ordinary fact is still re-datable"
        );

        // The audience verb: refused on a rule, fine on an ordinary fact.
        let acl = |target: &RecallHit| LlmAclChange {
            target: Some(target.fact_id.as_str().to_owned()),
            subject_id: None,
            allow_ids: vec!["group:famiglia".to_owned()],
        };
        assert!(
            matches!(
                validate_acl_change(&acl(&rule), std::slice::from_ref(&rule), "alice", &groups),
                Err(AclChangePlanError::TargetIsAStandingRule(_))
            ),
            "re-scoping a rule takes it off the channel while leaving it alive"
        );
        assert!(
            validate_acl_change(&acl(&plain), std::slice::from_ref(&plain), "alice", &groups)
                .is_ok(),
            "an ordinary fact's audience is still changeable"
        );
    }

    /// A rule reaching a stage says it is one, in the line the stage reads.
    ///
    /// The candidate line is all either stage gets. Unmarked, a directive
    /// reads as an ordinary claim about the speaker — which is how one came to
    /// be closed as contradicted by a remark about dinner.
    #[test]
    fn a_rule_among_the_candidates_is_marked_as_one() {
        let now = now_fixture();
        let mut rule = sample_recall_hit("0190f3c2-7a4e-7c31-9b02-2f6a1c8e5d11");
        rule.source_path = format!("wikis/alice/{}", crate::wiki::RULES_FILENAME);
        let plain = sample_recall_hit("0190f3c2-7a4e-7c31-9b02-2f6a1c8e5d12");
        // The closure confirmer draws from recall, which does not hold rules
        // back, so it can be shown one and must see what it is.
        assert!(
            closure_candidate_line(&rule, &now).contains("STANDING RULE"),
            "the closure confirmer is not told its candidate is a rule"
        );
        // The reconciler's line does NOT carry the mark, and must not: a rule
        // never reaches that stage, so a label there would announce a
        // permission the stage does not have.
        assert!(
            !reconcile_candidate_line(&rule, &now).contains("STANDING RULE"),
            "the reconciler is labelling a candidate it can never be shown"
        );
        assert!(
            !closure_candidate_line(&plain, &now).contains("STANDING RULE"),
            "and an ordinary fact is not dressed as one"
        );
    }

    /// The road that IS allowed to revise a directive stays open: another
    /// directive, naming the one it replaces.
    ///
    /// The guards above refuse a rule to the four reconciliation verbs, and
    /// that must not close the one door a rule is meant to go through. This is
    /// the door: a behaviour-rule extraction carrying `supersede_target`,
    /// resolved against the directives in force.
    #[tokio::test]
    async fn a_standing_directive_is_revised_by_another_standing_directive() {
        let (dir, tree, pool) = setup_agent_workdir().await;
        let first = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new(
                "fake",
                "{\"intent\":\"capture\",\"extractions\":[{\
                  \"behaviour_rule\":true,\"behaviour_scope\":\"per-user\",\
                  \"body\":\"Answer concisely: give the answer without the preamble.\"}],\
                  \"suggested_seed\":\"Ok.\"}",
            ),
            None,
            req_consumer(
                "Keep it short with me. Give me the answer, not the preamble.",
                "alice",
                "botdeploy",
            ),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest")
        .capture_id
        .expect("the first directive is filed");

        let revise = format!(
            "{{\"intent\":\"capture\",\"extractions\":[{{\
              \"behaviour_rule\":true,\"behaviour_scope\":\"per-user\",\
              \"supersede_target\":\"{}\",\
              \"body\":\"You can be chatty again.\"}}],\"suggested_seed\":\"Ok.\"}}",
            first.as_str()
        );
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", &revise),
            None,
            req_consumer("You can be chatty with me again.", "alice", "botdeploy"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        let rules = recall_behaviour_rules(&pool, &req_consumer("?", "alice", "botdeploy")).await;
        let bodies: Vec<&str> = rules.iter().map(|(_, body, _)| body.as_str()).collect();
        assert!(
            bodies.iter().any(|b| b.contains("chatty")),
            "the new directive is in force: {bodies:?}"
        );
        assert!(
            !bodies.iter().any(|b| b.contains("without the preamble")),
            "and the one it names stops steering the agent: {bodies:?}"
        );
        drop(dir);
    }

    /// Widening a directive to every assistant reaches the sender's own
    /// memory, and takes nothing away on the way.
    ///
    /// The scope is read from the addressee, so «and I mean with every
    /// assistant» is the same directive at a wider reach — filed in the
    /// SENDER's identity wiki, where every consumer serving them reads it.
    /// What this pins is that the widening road is not the reconciliation
    /// road: nothing is retired by an ordinary verb on the way through.
    #[tokio::test]
    async fn widening_a_directive_to_every_assistant_files_it_in_the_senders_own_memory() {
        let (dir, tree, pool) = setup_agent_workdir().await;
        // `alice` is the speaker here, and a user-global rule lands in her own
        // identity wiki rather than the agent's.
        sqlx::query("INSERT INTO enrollment_users (user_id, is_admin) VALUES ('alice', 0)")
            .execute(&pool)
            .await
            .unwrap();
        // The per-user rule the widening replaces, filed first.
        let per_user = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new(
                "fake",
                "{\"intent\":\"capture\",\"extractions\":[{\
                  \"behaviour_rule\":true,\"behaviour_scope\":\"per-user\",\
                  \"body\":\"Answer concisely: give the answer without the preamble.\"}],\
                  \"suggested_seed\":\"Ok.\"}",
            ),
            None,
            req_consumer(
                "Keep it short with me. Give me the answer, not the preamble.",
                "alice",
                "botdeploy",
            ),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest")
        .capture_id
        .expect("the per-user rule is filed");

        // The widening NAMES it, which is the only road that replaces a rule.
        let widened = format!(
            "{{\"intent\":\"capture\",\"extractions\":[{{\
              \"behaviour_rule\":true,\"behaviour_scope\":\"user-global\",\
              \"supersede_target\":\"{}\",\
              \"body\":\"Answer concisely: give the answer without the preamble.\"}}],\
              \"suggested_seed\":\"Ok.\"}}",
            per_user.as_str()
        );
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", &widened),
            None,
            req_consumer(
                "And I mean with every assistant, not just this one. The short answers, all of them.",
                "alice",
                "botdeploy",
            ),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        let in_her_own = fact_index::find_by_filters(
            &pool,
            &fact_index::FactFilters {
                wiki_id: Some("alice".to_owned()),
                ..Default::default()
            },
        )
        .await
        .unwrap();
        assert_eq!(
            in_her_own.len(),
            1,
            "a directive addressed to every assistant lives with the person, not the agent"
        );
        assert!(
            crate::wiki::is_rules_page(&in_her_own[0].source_path),
            "on her rules page: {}",
            in_her_own[0].source_path
        );
        assert!(
            in_her_own[0].valid_to.is_none() && in_her_own[0].decay_reason.is_none(),
            "and it arrives in force, not already closed"
        );
        drop(dir);
    }

    /// Neither stage that judges a stored fact is told that duplicates get
    /// merged downstream.
    ///
    /// Nothing merges them: the promotion dedup only looks at claims from the
    /// same sender inside its similarity threshold, and the identity core is
    /// held out of every automatic pass by design. A stage told the memory
    /// tidies up after it has a reason to leave a second live value where it
    /// found it, which is exactly the state the card was found in.
    #[test]
    fn the_stages_that_judge_stored_facts_promise_no_downstream_merge() {
        for (name, prompt) in [
            ("reconciler", BUNDLED_INGEST_RECONCILE_MD),
            ("closure confirmer", BUNDLED_INGEST_CLOSURES_MD),
        ] {
            assert!(
                !prompt.contains("merges duplicates by itself"),
                "the {name} is still told something merges duplicates for it"
            );
        }
        assert!(
            BUNDLED_INGEST_RECONCILE_MD
                .contains("nothing downstream folds two live values into one later"),
            "the reconciler no longer knows a second live value stays where it lands"
        );
    }

    /// The bundled ingest prompt carries the explicit-relationship gate: a
    /// person the message leaves unnamed is never identified with a
    /// `known_users` entry, and relationship facts require the sender to
    /// state the tie explicitly.
    #[test]
    fn bundled_ingest_prompt_carries_the_explicit_relationship_gate() {
        assert!(
            BUNDLED_INGEST_PROMPT_MD.contains("Explicitly stated ONLY — never inferred"),
            "the explicit-relationship gate is gone from the bundled prompt"
        );
        assert!(
            BUNDLED_INGEST_PROMPT_MD.contains("it never runs in reverse"),
            "the no-reverse-alias-resolution guard is gone from the bundled prompt"
        );
    }

    /// A single turn can carry BOTH an engine-rule and an ordinary fact. The
    /// rule is appended to `@rules.md`; the fact still routes normally (buffered
    /// for the standard `alice` wiki) and surfaces as the turn's `capture_id`.
    #[tokio::test]
    async fn ingest_mixed_turn_files_fact_and_appends_rule() {
        let (dir, tree, pool) = setup_workdir().await;
        let json = "{\"intent\":\"capture\",\"extractions\":[\
            {\"engine_rule\":true,\"fact_type\":\"rule\",\
             \"body\":\"Never store my exact home address.\"},\
            {\"target_wiki_id\":\"alice\",\"target_page\":\"preferenze.md\",\"subject_id\":\"user:alice\",\
             \"body\":\"Alice lives in Bologna.\",\"fact_type\":\"bio\",\"topics\":[\"bio\"]}],\
            \"suggested_seed\":\"Noted.\"}";
        let llm = FakeLlmBackend::new("fake", json);
        let policy = IngestPolicy::default();
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req("non salvare il mio indirizzo. vivo a Bologna.", "alice"),
            &policy,
        )
        .await
        .expect("ingest");

        assert_eq!(resp.intent, IntentKind::Capture);
        // The ordinary fact buffers (standard wiki) and anchors the turn.
        let cid = resp
            .capture_id
            .expect("the ordinary fact surfaces a capture_id");
        let buffered = capture_buffer::find_all_buffered(&pool, 100).await.unwrap();
        assert_eq!(buffered.len(), 1, "exactly the one ordinary fact buffers");
        assert_eq!(buffered[0].capture_id, cid);
        assert_eq!(buffered[0].body, "Alice lives in Bologna.");
        // The rule went to rules.md, not the buffer.
        let rules = std::fs::read_to_string(
            tree.wikis_dir()
                .join("alice")
                .join(crate::wiki::RULES_FILENAME),
        )
        .expect("@rules.md written");
        assert!(rules.contains("- Never store my exact home address."));
        drop(dir);
    }

    // ---------- a filled identity slot is a question, not a second value ----------

    /// The two candidate ids are a wire contract: the consumer sends one back
    /// verbatim, and the engine has to read the same answer out of it.
    ///
    /// A choice belonging to some OTHER disambiguation must not parse as one
    /// of these — it would settle a slot question nobody was asked — so the
    /// prefix and a well-formed fact id are both required.
    #[test]
    fn a_slot_answer_round_trips_and_ignores_anybody_elses_choice() {
        let id = FactId::parse(CARD_FACT_ID).unwrap();
        for answer in [SlotAnswer::Keep(id.clone()), SlotAnswer::Replace(id)] {
            let on_the_wire = answer.candidate_id();
            assert_eq!(SlotAnswer::parse(&on_the_wire), Some(answer));
        }
        for foreign in [
            "a",
            "the-dentist",
            "keep:0190f3c2-7a4e-7c31-9b02-2f6a1c8e5da1",
            "slot-keep:not-a-fact-id",
            "slot-keep:",
            "",
        ] {
            assert_eq!(
                SlotAnswer::parse(foreign),
                None,
                "{foreign:?} is not an answer to a slot question"
            );
        }
    }

    /// The turn that opened this, with the family renamed to the repo's
    /// fixtures. It states an AGE, in a month, about a child whose card
    /// already carries a birth date.
    const AGE_TURN: &str = "bob ha circa 300-350 \u{20ac} di risparmi da parte.\n\
                            carol ha gi\u{e0} un conto corrente presso le Poste Italiane.\n\
                            bob ha circa 14 anni a luglio 2026.\n\
                            carol sta valutando diverse opzioni per i risparmi di bob: \
                            l'apertura di un libretto postale, un fondo pensione o un piano \
                            di accumulo (PAC).";
    /// The birth date already on bob's card.
    const CARD_BIRTHDATE: &str = "bob \u{e8} nato il 12 marzo 2014 alle 06:45";
    /// The birth date a classifier derives from the age above.
    const DERIVED_BIRTHDATE: &str = "bob \u{e8} nato l'8 luglio 2012";
    const CARD_FACT_ID: &str = "0190f3c2-7a4e-7c31-9b02-2f6a1c8e5da1";

    /// Two enrolled people, each with their own wiki: carol speaks, bob is the
    /// child she speaks about.
    async fn setup_family() -> (TempDir, WikiTree, SqlitePool) {
        let dir = tempfile::tempdir().unwrap();
        let pool = db::open_or_init(dir.path()).await.expect("db open");
        let wikis = dir.path().join("wikis");
        std::fs::create_dir_all(&wikis).unwrap();
        write_wiki(&wikis, "carol", "Carol", "wiki-user", None);
        write_wiki(&wikis, "bob", "Bob", "wiki-user", None);
        let tree = WikiTree::open(dir.path()).expect("open tree");
        for user in ["carol", "bob"] {
            sqlx::query(
                "INSERT INTO enrollment_users (user_id, aliases, is_admin) VALUES (?,'[]',0)",
            )
            .bind(user)
            .execute(&pool)
            .await
            .unwrap();
        }
        (dir, tree, pool)
    }

    /// Plant the birth date already on bob's identity card: his own claim,
    /// shared with carol so she may read it (an unreadable fact cannot be
    /// quoted back to her, and so cannot be asked about).
    async fn plant_the_card_birthdate(pool: &SqlitePool) -> FactId {
        let fact_id = FactId::parse(CARD_FACT_ID).unwrap();
        fact_index::insert(
            pool,
            &fact_index::NewFact {
                subject_external: None,
                slot: None,
                slot_value: None,
                authored_refs: Vec::new(),
                fact_id: fact_id.clone(),
                wiki_id: "bob".to_owned(),
                source_path: "wikis/bob/@profile.md".to_owned(),
                region_start: Some(0),
                region_end: Some(40),
                text: CARD_BIRTHDATE.to_owned(),
                embedding: vec![0.1, 0.2, 0.3, 0.4],
                subject_id: Principal::User("bob".to_owned()),
                allow_ids: vec![Principal::User("carol".to_owned())],
                sender_id: Some(Principal::User("bob".to_owned())),
                fact_type: Some("bio".to_owned()),
                topics: Vec::new(),
                valid_from: Some("2026-07-02T00:00:00Z".to_owned()),
                valid_to: None,
                target_page: None,
                style: None,
                salience: Some("high".to_owned()),
                source_ref: None,
            },
        )
        .await
        .expect("plant the card's birth date");
        fact_id
    }

    /// A classifier that derives a birth date from the age in the turn and
    /// declares the conflict the `identity_core` block let it see.
    fn derived_birthdate_plan() -> String {
        format!(
            "{{\"intent\":\"capture\",\"suggested_seed\":\"Noted.\",\"extractions\":[\
             {{\"target_wiki_id\":\"bob\",\"subject_id\":\"user:bob\",\
             \"body\":\"{DERIVED_BIRTHDATE}\",\"fact_type\":\"bio\",\"salience\":\"high\",\
             \"conflicts_with\":\"{CARD_FACT_ID}\",\"slot\":\"date_of_birth\"}}]}}"
        )
    }

    fn the_age_turn(sender: &str, choice: Option<&str>) -> IngestRequest {
        IngestRequest {
            disambig_choice: choice.map(str::to_owned),
            metadata: IngestMetadata {
                occurred_at: Some(
                    chrono::DateTime::parse_from_rfc3339("2026-07-08T08:54:40Z")
                        .unwrap()
                        .to_utc(),
                ),
                ..IngestMetadata::default()
            },
            ..req(AGE_TURN, sender)
        }
    }

    /// The real turn, on the real card: a second birth date is NOT written,
    /// and the turn asks instead.
    ///
    /// This is the case that opened 85 — an age in a month, replayed against a
    /// card that already carried a birth date, and both values ended up live
    /// on the same card. The classifier here still derives the date (85a asks
    /// it not to; a prompt is not a guarantee), so what this pins is the
    /// engine's half: nothing is queued, nothing reaches the page, and the
    /// turn comes back with the two candidates for a person to choose
    /// between.
    #[tokio::test]
    async fn a_second_birth_date_is_asked_about_and_never_written() {
        let (dir, tree, pool) = setup_family().await;
        let card = plant_the_card_birthdate(&pool).await;
        let llm = FakeLlmBackend::new("fake", derived_birthdate_plan());
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            the_age_turn("carol", None),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        assert!(resp.needs_disambig, "the turn asks");
        let ids: Vec<&str> = resp
            .disambig_candidates
            .iter()
            .map(|c| c.candidate_id.as_str())
            .collect();
        assert_eq!(
            ids,
            vec![
                format!("slot-keep:{CARD_FACT_ID}").as_str(),
                format!("slot-replace:{CARD_FACT_ID}").as_str(),
            ],
            "keep what is there, or replace it — and both name the fact"
        );
        assert!(
            resp.disambig_candidates[0]
                .description
                .contains(CARD_BIRTHDATE)
                && resp.disambig_candidates[0].description.contains("bob")
                && resp.disambig_candidates[0]
                    .description
                    .contains("2026-07-02"),
            "the kept candidate quotes the value, who said it and when: {:?}",
            resp.disambig_candidates[0].description
        );
        assert!(
            resp.disambig_candidates[1]
                .description
                .contains(DERIVED_BIRTHDATE),
            "the replacing candidate quotes the new value"
        );

        assert!(resp.capture_id.is_none(), "nothing was filed");
        assert!(
            capture_buffer::find_all_buffered(&pool, 100)
                .await
                .unwrap()
                .is_empty(),
            "and nothing is waiting in the buffer to be filed for it either"
        );
        let card_row = fact_index::find_by_id(&pool, &card)
            .await
            .unwrap()
            .expect("the card's own fact");
        assert!(
            card_row.valid_to.is_none() && card_row.superseded_at.is_none(),
            "the value already on the card is untouched"
        );
        assert_ne!(
            resp.suggested_seed.as_deref(),
            Some("Noted."),
            "a turn that wrote nothing must not tell the person it noted something"
        );
        drop(dir);
    }

    /// The person keeps what the card says: nothing is written, and the turn
    /// stops asking.
    #[tokio::test]
    async fn keeping_the_card_value_writes_nothing() {
        let (dir, tree, pool) = setup_family().await;
        let card = plant_the_card_birthdate(&pool).await;
        let llm = FakeLlmBackend::new("fake", derived_birthdate_plan());
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            the_age_turn("carol", Some(&format!("slot-keep:{CARD_FACT_ID}"))),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        assert!(!resp.needs_disambig, "the question is settled");
        assert!(
            capture_buffer::find_all_buffered(&pool, 100)
                .await
                .unwrap()
                .is_empty(),
            "keeping means keeping: the rejected value is not filed either"
        );
        let card_row = fact_index::find_by_id(&pool, &card).await.unwrap().unwrap();
        assert!(card_row.valid_to.is_none(), "and the card still holds");
        drop(dir);
    }

    /// The subject himself replaces it: the new value is filed and the old one
    /// is retired, pointing at it.
    ///
    /// The weld happens in the turn, not in the reconciliation stage that runs
    /// after it. That stage judges whether a message replaced something; here
    /// a person was asked and answered, and putting a model's opinion after
    /// their answer could only overrule it.
    #[tokio::test]
    async fn the_subject_replacing_his_own_birth_date_retires_the_old_one() {
        let (dir, tree, pool) = setup_family().await;
        let card = plant_the_card_birthdate(&pool).await;
        let llm = FakeLlmBackend::new("fake", derived_birthdate_plan());
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            the_age_turn("bob", Some(&format!("slot-replace:{CARD_FACT_ID}"))),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        let filed = resp.capture_id.expect("the new value is filed");
        let card_row = fact_index::find_by_id(&pool, &card).await.unwrap().unwrap();
        assert_eq!(
            card_row.superseded_by.as_ref().map(FactId::as_str),
            Some(filed.as_str()),
            "the old birth date is retired and points at the one that replaced it"
        );
        let pending: i64 =
            sqlx::query_scalar("SELECT count(*) FROM structure_proposals WHERE kind = ?")
                .bind(proposals::kind::SLOT_CONFLICT)
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(pending, 0, "nobody needs asking: he is the subject");
        drop(dir);
    }

    /// «Replace» welds the old value onto the row that EXISTS, which is not
    /// the id the capture minted when it wrote nothing.
    ///
    /// Write-time dedup resolves a restated body onto a fact already in the
    /// memory and still hands back a fresh id for the audit trail. Welding to
    /// that id retires the value the person rejected and points
    /// `superseded_by` at nothing — a reader of the old value is sent to a
    /// fact that does not exist.
    #[tokio::test]
    async fn replacing_with_words_already_stored_welds_onto_the_stored_fact() {
        let (dir, tree, pool) = setup_family().await;
        let card = plant_the_card_birthdate(&pool).await;
        let twin = plant_bobs_twin(&pool, DERIVED_BIRTHDATE, TWIN_ID).await;

        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", replace_into_a_page(DERIVED_BIRTHDATE)),
            None,
            the_age_turn("bob", Some(&format!("slot-replace:{CARD_FACT_ID}"))),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");
        assert!(
            resp.capture_id.is_some(),
            "the turn reports what it resolved"
        );

        let row = fact_index::find_by_id(&pool, &card)
            .await
            .unwrap()
            .expect("the card fact stays");
        assert_eq!(
            row.superseded_by.as_ref(),
            Some(&twin),
            "the value bob rejected points at the fact that now holds the answer"
        );
        drop(dir);
    }

    /// And when the words are the words already on the fact being replaced,
    /// nothing happens.
    ///
    /// Dedup resolves the new body onto the very target. Retiring it and
    /// pointing it at itself closes a window and writes no successor link to
    /// explain it, leaving a fact nothing contradicted marked `contradicted`.
    #[tokio::test]
    async fn replacing_a_value_with_its_own_words_retires_nothing() {
        let (dir, tree, pool) = setup_family().await;
        let card = plant_the_card_birthdate(&pool).await;
        // The box says one date, the claim says another — so there is a
        // disagreement to answer — while the WORDS are the card's own, and
        // its audience is the one a turn of bob's produces, so write-time
        // dedup resolves the new body onto the card itself.
        sqlx::query(
            "UPDATE fact_index SET slot = 'date_of_birth', slot_value = '2014-03-12', \
             allow_ids = '[]' WHERE fact_id = ?",
        )
        .bind(card.as_str())
        .execute(&pool)
        .await
        .unwrap();

        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", replace_into_a_page(CARD_BIRTHDATE)),
            None,
            the_age_turn("bob", Some(&format!("slot-replace:{CARD_FACT_ID}"))),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        let row = fact_index::find_by_id(&pool, &card)
            .await
            .unwrap()
            .expect("the card fact stays");
        assert!(
            row.valid_to.is_none() && row.superseded_at.is_none(),
            "a fact is not retired in favour of itself"
        );
        drop(dir);
    }

    const TWIN_ID: &str = "0190f3c2-7a4e-7c31-9b02-2f6a1c8e5dc1";

    /// A fact already in bob's memory, on the page this turn writes to and
    /// with the audience a turn of his own produces, so write-time dedup
    /// resolves onto it.
    async fn plant_bobs_twin(pool: &SqlitePool, text: &str, fact_id: &str) -> FactId {
        let fact_id = FactId::parse(fact_id).unwrap();
        fact_index::insert(
            pool,
            &fact_index::NewFact {
                subject_external: None,
                slot: None,
                slot_value: None,
                authored_refs: Vec::new(),
                fact_id: fact_id.clone(),
                wiki_id: "bob".to_owned(),
                source_path: "wikis/bob/nascita.md".to_owned(),
                region_start: Some(0),
                region_end: Some(40),
                text: text.to_owned(),
                embedding: vec![0.1, 0.2, 0.3, 0.4],
                subject_id: Principal::User("bob".to_owned()),
                allow_ids: Vec::new(),
                sender_id: Some(Principal::User("bob".to_owned())),
                fact_type: Some("bio".to_owned()),
                topics: Vec::new(),
                valid_from: Some("2026-07-02T00:00:00Z".to_owned()),
                valid_to: None,
                target_page: None,
                style: None,
                salience: Some("high".to_owned()),
                source_ref: None,
            },
        )
        .await
        .expect("plant the twin");
        fact_id
    }

    /// A card claim that names its own page, so it takes the LIVE write path
    /// where dedup runs inside the turn rather than in the dream.
    fn replace_into_a_page(body: &str) -> String {
        format!(
            "{{\"intent\":\"capture\",\"suggested_seed\":\"Noted.\",\"extractions\":[\
             {{\"target_wiki_id\":\"bob\",\"subject_id\":\"user:bob\",\
             \"target_page\":\"nascita.md\",\"requested_container\":true,\
             \"page_description\":\"when bob was born\",\
             \"body\":\"{body}\",\"fact_type\":\"bio\",\"salience\":\"high\",\
             \"conflicts_with\":\"{CARD_FACT_ID}\",\"slot\":\"date_of_birth\",\
             \"slot_value\":\"2012-07-08\"}}]}}"
        )
    }

    /// Somebody else replaces it: the new value does NOT go on the page, and
    /// the person whose card it is gets the question.
    ///
    /// Carol may not rewrite what bob said about bob. Filing her value anyway
    /// and leaving the disagreement to a dashboard nobody reads is what the
    /// old `continue` did.
    #[tokio::test]
    async fn a_third_party_replacing_it_writes_nothing_and_asks_the_owner() {
        let (dir, tree, pool) = setup_family().await;
        let card = plant_the_card_birthdate(&pool).await;
        let llm = FakeLlmBackend::new("fake", derived_birthdate_plan());
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            the_age_turn("carol", Some(&format!("slot-replace:{CARD_FACT_ID}"))),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        assert!(resp.capture_id.is_none(), "her value is not filed");
        assert!(
            capture_buffer::find_all_buffered(&pool, 100)
                .await
                .unwrap()
                .is_empty(),
            "not on the page and not in the buffer on its way there"
        );
        let card_row = fact_index::find_by_id(&pool, &card).await.unwrap().unwrap();
        assert!(
            card_row.valid_to.is_none() && card_row.superseded_at.is_none(),
            "and bob's own claim stands until bob says otherwise"
        );
        let (recipient, context): (Option<String>, String) = sqlx::query_as(
            "SELECT recipient_id, context FROM structure_proposals WHERE kind = ? AND status = 'pending'",
        )
        .bind(proposals::kind::SLOT_CONFLICT)
        .fetch_one(&pool)
        .await
        .expect("the question was opened");
        assert_eq!(recipient.as_deref(), Some("user:bob"));
        assert!(
            context.contains(DERIVED_BIRTHDATE) && context.contains(CARD_FACT_ID),
            "the proposal carries both values: {context}"
        );
        drop(dir);
    }

    /// The number nobody else may read: a second value for that slot is not
    /// written, its owner is asked, and the speaker is told only that it was
    /// passed on.
    ///
    /// Zoe gives her mobile number and it stays hers to read. A fortnight later
    /// Alice states a different one. Alice is shown nothing of that slot — the
    /// question a declared conflict raises would quote Zoe's number back to her
    /// — so no `conflicts_with` can be set and, until the engine compared the
    /// slots itself, both numbers landed on Zoe's card with neither of them
    /// told. The comparison is the code's, the values reach only the one reader
    /// entitled to both, and what goes back to Alice names nothing.
    #[tokio::test]
    async fn a_value_the_speaker_may_not_read_is_settled_by_the_card_s_owner() {
        const HERS: &str = "Zoe's mobile number is 07700 900314.";
        const ALICE_SAYS: &str = "Zoe's mobile number is 07700 900275.";
        let (dir, tree, pool) = setup_slot_family().await;
        let hers = plant_private_number(&pool, HERS, "07700 900314").await;

        let plan = format!(
            "{{\"intent\":\"capture\",\"extractions\":[\
             {{\"target_wiki_id\":\"zoe\",\"subject_id\":\"user:zoe\",\
             \"body\":\"{ALICE_SAYS}\",\"fact_type\":\"bio\",\"salience\":\"high\",\
             \"slot\":\"mobile_number\",\"slot_value\":\"07700 900275\",\
             \"topics\":[\"contact\"]}}]}}"
        );
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", &plan),
            None,
            req(
                "Zoe's number is 07700 900275, that's the one I've got",
                "alice",
            ),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        assert!(resp.capture_id.is_none(), "Alice's value is not filed");
        assert!(
            capture_buffer::find_all_buffered(&pool, 100)
                .await
                .unwrap()
                .is_empty(),
            "and it is not waiting on its way to the card either"
        );
        let card = fact_index::find_active_by_source_path(&pool, "wikis/zoe/@profile.md")
            .await
            .unwrap();
        assert_eq!(card.len(), 1, "one number on the card, not two");
        assert_eq!(card[0].fact_id, hers);

        let (recipient, context): (Option<String>, String) = sqlx::query_as(
            "SELECT recipient_id, context FROM structure_proposals WHERE kind = ? AND status = 'pending'",
        )
        .bind(proposals::kind::SLOT_CONFLICT)
        .fetch_one(&pool)
        .await
        .expect("the question was opened");
        assert_eq!(
            recipient.as_deref(),
            Some("user:zoe"),
            "the card's owner is the one reader entitled to both values"
        );
        assert!(
            context.contains("07700 900314") && context.contains("07700 900275"),
            "and she is shown both: {context}"
        );

        let notice = resp.rules.unwrap_or_default();
        assert!(
            notice.contains("NOT saved") && notice.contains("been asked"),
            "Alice is told it was passed on: {notice}"
        );
        for secret in ["07700 900314", "mobile_number"] {
            assert!(
                !notice.contains(secret),
                "and told nothing else — `{secret}` leaked into the notice: {notice}"
            );
        }
        drop(dir);
    }

    /// The same number in other words is the same number: nothing is written
    /// and nobody is asked.
    ///
    /// **Said DIFFERENTLY on purpose.** The card holds «Zoe's mobile number is
    /// 07700 900314.» and the turn writes «Zoe can be reached on 07700
    /// 900314» — one number, two sentences. Comparing the two bodies word for
    /// word calls that a disagreement and puts a question to Zoe quoting a
    /// value she is being asked to choose against itself. The comparison runs
    /// on the bare values instead, and there is nothing between them.
    #[tokio::test]
    async fn the_same_value_in_other_words_asks_nobody() {
        const HERS: &str = "Zoe's mobile number is 07700 900314.";
        const SAME_NUMBER_OTHER_WORDS: &str = "Zoe can be reached on 07700 900314";
        let (dir, tree, pool) = setup_slot_family().await;
        plant_private_number(&pool, HERS, "07700 900314").await;

        let plan = format!(
            "{{\"intent\":\"capture\",\"extractions\":[\
             {{\"target_wiki_id\":\"zoe\",\"subject_id\":\"user:zoe\",\
             \"body\":\"{SAME_NUMBER_OTHER_WORDS}\",\"fact_type\":\"bio\",\
             \"salience\":\"high\",\"slot\":\"mobile_number\",\
             \"slot_value\":\"07700 900314\",\"topics\":[\"contact\"]}}]}}"
        );
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", &plan),
            None,
            req("Zoe's number is 07700 900314", "alice"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        let opened: i64 =
            sqlx::query_scalar("SELECT COUNT(*) FROM structure_proposals WHERE kind = ?")
                .bind(proposals::kind::SLOT_CONFLICT)
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(opened, 0, "nothing to settle, so nobody is asked");
        drop(dir);
    }

    /// Two people, and one number that is Zoe's alone to read.
    async fn setup_slot_family() -> (TempDir, WikiTree, SqlitePool) {
        let dir = tempfile::tempdir().unwrap();
        let pool = db::open_or_init(dir.path()).await.expect("db open");
        let wikis = dir.path().join("wikis");
        std::fs::create_dir_all(&wikis).unwrap();
        write_wiki(&wikis, "alice", "Alice", "wiki-user", None);
        write_wiki(&wikis, "zoe", "Zoe", "wiki-user", None);
        write_wiki(&wikis, "bob", "Bob", "wiki-user", None);
        let tree = WikiTree::open(dir.path()).expect("open tree");
        for user in ["alice", "zoe", "bob"] {
            sqlx::query(
                "INSERT INTO enrollment_users (user_id, aliases, is_admin) VALUES (?,'[]',0)",
            )
            .bind(user)
            .execute(&pool)
            .await
            .unwrap();
        }
        (dir, tree, pool)
    }

    /// Zoe's own number on her own card, readable by nobody else — the shape
    /// `allow_ids: []` gives every fact somebody states about themselves and
    /// does not share.
    async fn plant_private_number(pool: &SqlitePool, text: &str, number: &str) -> FactId {
        plant_private_number_for(pool, "zoe", text, number).await
    }

    /// The same, on any enrolled person's card. Their id seeds the fact id, so
    /// one turn can plant two people's private numbers.
    async fn plant_private_number_for(
        pool: &SqlitePool,
        who: &str,
        text: &str,
        number: &str,
    ) -> FactId {
        let tail = format!("{:02x}", u32::from(who.as_bytes()[0]));
        let fact_id = FactId::parse(&format!("0190f3c2-7a4e-7c31-9b02-2f6a1c8e5d{tail}")).unwrap();
        fact_index::insert(
            pool,
            &fact_index::NewFact {
                subject_external: None,
                slot: Some("mobile_number".to_owned()),
                slot_value: Some(number.to_owned()),
                authored_refs: Vec::new(),
                fact_id: fact_id.clone(),
                wiki_id: who.to_owned(),
                source_path: format!("wikis/{who}/@profile.md"),
                region_start: Some(0),
                region_end: Some(40),
                text: text.to_owned(),
                embedding: vec![0.1, 0.2, 0.3, 0.4],
                subject_id: Principal::User(who.to_owned()),
                allow_ids: Vec::new(),
                sender_id: Some(Principal::User(who.to_owned())),
                fact_type: Some("bio".to_owned()),
                topics: Vec::new(),
                valid_from: Some("2026-06-24T00:00:00Z".to_owned()),
                valid_to: None,
                target_page: None,
                style: None,
                salience: Some("high".to_owned()),
                source_ref: None,
            },
        )
        .await
        .expect("plant a private number");
        fact_id
    }

    /// The question about a card goes to WHOSE CARD IT IS, whoever happened to
    /// say the value on it.
    ///
    /// Zoe's number was given by Bob, on Zoe's card, readable by neither of the
    /// other two. Alice states a different one. Addressing the question to the
    /// author sends Bob a decision about Zoe's own record — and the notice
    /// Alice gets, the guide and the changelog all say the person it is about
    /// was asked.
    #[tokio::test]
    async fn a_card_question_goes_to_whose_card_it_is() {
        const HERS: &str = "Zoe's mobile number is 07700 900314.";
        let (dir, tree, pool) = setup_slot_family().await;
        let planted = plant_private_number(&pool, HERS, "07700 900314").await;
        sqlx::query("UPDATE fact_index SET sender_id = 'user:bob' WHERE fact_id = ?")
            .bind(planted.as_str())
            .execute(&pool)
            .await
            .unwrap();

        let plan = "{\"intent\":\"capture\",\"extractions\":[\
             {\"target_wiki_id\":\"zoe\",\"subject_id\":\"user:zoe\",\
             \"body\":\"Zoe's mobile number is 07700 900275.\",\"fact_type\":\"bio\",\
             \"salience\":\"high\",\"slot\":\"mobile_number\",\
             \"slot_value\":\"07700 900275\",\"topics\":[\"contact\"]}]}";
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", plan),
            None,
            req("Zoe's number is 07700 900275", "alice"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        let recipient: Option<String> = sqlx::query_scalar(
            "SELECT recipient_id FROM structure_proposals WHERE kind = ? AND status = 'pending'",
        )
        .bind(proposals::kind::SLOT_CONFLICT)
        .fetch_one(&pool)
        .await
        .expect("the question was opened");
        assert_eq!(
            recipient.as_deref(),
            Some("user:zoe"),
            "the card belongs to Zoe; Bob only spoke"
        );
        drop(dir);
    }

    /// Three turns saying the same thing are one disagreement, and the card's
    /// owner is asked once.
    ///
    /// Every repetition put the value Alice may not read in front of Zoe
    /// again. What Alice hears does not change — she is told it was passed on
    /// every time, because from where she stands nothing is different.
    #[tokio::test]
    async fn one_slot_is_one_question_however_often_it_is_restated() {
        const HERS: &str = "Zoe's mobile number is 07700 900314.";
        let (dir, tree, pool) = setup_slot_family().await;
        plant_private_number(&pool, HERS, "07700 900314").await;
        let plan = "{\"intent\":\"capture\",\"extractions\":[\
             {\"target_wiki_id\":\"zoe\",\"subject_id\":\"user:zoe\",\
             \"body\":\"Zoe's mobile number is 07700 900275.\",\"fact_type\":\"bio\",\
             \"salience\":\"high\",\"slot\":\"mobile_number\",\
             \"slot_value\":\"07700 900275\",\"topics\":[\"contact\"]}]}";

        for turn in 0..3 {
            let resp = wiki_ingest_message(
                &pool,
                &tree,
                fake_embedder(),
                &FakeLlmBackend::new("fake", plan),
                None,
                req("Zoe's number is 07700 900275", "alice"),
                &IngestPolicy::default(),
            )
            .await
            .expect("ingest");
            assert!(
                resp.rules.unwrap_or_default().contains("NOT saved"),
                "turn {turn}: Alice is told the same thing every time"
            );
        }

        let opened: i64 = sqlx::query_scalar(
            "SELECT count(*) FROM structure_proposals WHERE kind = ? AND status = 'pending'",
        )
        .bind(proposals::kind::SLOT_CONFLICT)
        .fetch_one(&pool)
        .await
        .unwrap();
        assert_eq!(opened, 1, "one box, one question");
        let parked: i64 =
            sqlx::query_scalar("SELECT count(*) FROM capture_buffer WHERE status = 'held'")
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(parked, 1, "and one claim parked behind it, not three");
        drop(dir);
    }

    /// A classifier that reads the card and forgets to declare the conflict
    /// still costs nobody a second birth date: the engine compares the boxes
    /// itself and asks the same question.
    ///
    /// The plan here is the real one with `conflicts_with` taken out — the
    /// value on the card is one carol MAY read, so before this the extraction
    /// simply filed beside it.
    ///
    /// Both sides carry the bare value, and the box holds one value, and the
    /// dates are written the one way the prompt asks for — which is the whole
    /// of what this side of the comparison needs before the engine will act
    /// without a model.
    #[tokio::test]
    async fn a_conflict_the_classifier_forgot_to_declare_is_still_asked() {
        let (dir, tree, pool) = setup_family().await;
        let card = plant_the_card_birthdate(&pool).await;
        sqlx::query(
            "UPDATE fact_index SET slot = 'date_of_birth', slot_value = '2014-03-12' \
             WHERE fact_id = ?",
        )
        .bind(card.as_str())
        .execute(&pool)
        .await
        .unwrap();
        let undeclared = format!(
            "{{\"intent\":\"capture\",\"suggested_seed\":\"Noted.\",\"extractions\":[\
             {{\"target_wiki_id\":\"bob\",\"subject_id\":\"user:bob\",\
             \"body\":\"{DERIVED_BIRTHDATE}\",\"fact_type\":\"bio\",\"salience\":\"high\",\
             \"slot\":\"date_of_birth\",\"slot_value\":\"2012-07-08\"}}]}}"
        );
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", &undeclared),
            None,
            the_age_turn("carol", None),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        assert!(
            resp.needs_disambig,
            "the engine found the pair the classifier did not name"
        );
        assert!(resp.capture_id.is_none(), "and wrote nothing meanwhile");
        assert!(
            capture_buffer::find_all_buffered(&pool, 100)
                .await
                .unwrap()
                .is_empty(),
            "not queued on its way to the card either"
        );
        drop(dir);
    }

    /// A claim held back is PARKED, and the owner answering «the other one is
    /// right» releases it onto their card.
    ///
    /// Retiring the stored value and writing nothing left the box empty and the
    /// right value alive only inside the question. The words wait in the
    /// buffer, out of every queue, until the one person entitled to settle it
    /// says which is which.
    #[tokio::test]
    async fn the_owner_calling_the_other_value_right_gets_it_written() {
        let (dir, tree, pool) = setup_family().await;
        let card = plant_the_card_birthdate(&pool).await;
        let (proposal, parked) = ask_bob_about_his_birth_date(&pool, &tree).await;
        assert!(
            fact_index::find_by_id(&pool, &parked)
                .await
                .unwrap()
                .is_none(),
            "a parked claim is not a fact"
        );

        proposals::apply_proposal(
            &pool,
            &tree,
            &proposal,
            &serde_json::json!({ "verdict": "retire" }),
            Some("bob"),
            false,
        )
        .await
        .expect("bob answers");

        let card_row = fact_index::find_by_id(&pool, &card).await.unwrap().unwrap();
        assert!(
            card_row.valid_to.is_some(),
            "the value he called wrong stops being asserted"
        );
        promote_buffer(&pool, &tree).await;
        let written = fact_index::find_by_id(&pool, &parked)
            .await
            .unwrap()
            .expect("the released claim reached the card");
        assert_eq!(written.text.trim(), DERIVED_BIRTHDATE);
        assert_eq!(
            written.subject_id,
            Principal::User("bob".to_owned()),
            "about the person whose card it is"
        );
        assert_eq!(
            written.sender_id,
            Some(Principal::User("carol".to_owned())),
            "and authored by whoever said it"
        );
        drop(dir);
    }

    /// The owner keeps their own value, and the claim that argued with it is
    /// dropped: it was never memory and it does not become memory later.
    #[tokio::test]
    async fn the_owner_keeping_their_value_drops_the_parked_claim() {
        let (dir, tree, pool) = setup_family().await;
        let card = plant_the_card_birthdate(&pool).await;
        let (proposal, parked) = ask_bob_about_his_birth_date(&pool, &tree).await;

        proposals::apply_proposal(
            &pool,
            &tree,
            &proposal,
            &serde_json::json!({ "verdict": "keep" }),
            Some("bob"),
            false,
        )
        .await
        .expect("bob answers");

        assert!(
            fact_index::find_by_id(&pool, &card)
                .await
                .unwrap()
                .unwrap()
                .valid_to
                .is_none(),
            "his own value stands"
        );
        assert_eq!(
            rows_of_the_parked_claim(&pool, &parked).await,
            0,
            "and what argued with it is gone, not left waiting for a later pass"
        );
        promote_buffer(&pool, &tree).await;
        assert!(
            fact_index::find_by_id(&pool, &parked)
                .await
                .unwrap()
                .is_none(),
            "so it never reaches the card"
        );
        drop(dir);
    }

    /// Nobody answers, so the timeout sweep applies the recommended answer:
    /// the card stands and the parked claim goes with the question.
    #[tokio::test]
    async fn an_unanswered_card_question_drops_the_parked_claim() {
        let (dir, tree, pool) = setup_family().await;
        plant_the_card_birthdate(&pool).await;
        let (proposal, parked) = ask_bob_about_his_birth_date(&pool, &tree).await;

        proposals::auto_apply_proposal(
            &pool,
            &tree,
            &proposal,
            &serde_json::json!({ "verdict": "keep" }),
        )
        .await
        .expect("the sweep");

        assert_eq!(
            rows_of_the_parked_claim(&pool, &parked).await,
            0,
            "silence keeps the card as it was, and keeps nothing else"
        );
        promote_buffer(&pool, &tree).await;
        assert!(
            fact_index::find_by_id(&pool, &parked)
                .await
                .unwrap()
                .is_none(),
            "so it never reaches the card"
        );
        drop(dir);
    }

    /// How many rows the buffer still holds for the claim parked behind a
    /// question — in any state, since a row left parked is a claim the answer
    /// did not settle.
    async fn rows_of_the_parked_claim(pool: &SqlitePool, parked: &FactId) -> i64 {
        sqlx::query_scalar("SELECT count(*) FROM capture_buffer WHERE capture_id = ?")
            .bind(parked.as_str())
            .fetch_one(pool)
            .await
            .unwrap()
    }

    /// Carol answers «replace» on bob's birth date, which is not hers to
    /// replace: the question goes to bob and her words are parked behind it.
    /// Returns the proposal and the parked claim's id.
    async fn ask_bob_about_his_birth_date(pool: &SqlitePool, tree: &WikiTree) -> (String, FactId) {
        let llm = FakeLlmBackend::new("fake", derived_birthdate_plan());
        wiki_ingest_message(
            pool,
            tree,
            fake_embedder(),
            &llm,
            None,
            the_age_turn("carol", Some(&format!("slot-replace:{CARD_FACT_ID}"))),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");
        let (proposal, context): (String, String) = sqlx::query_as(
            "SELECT proposal_id, context FROM structure_proposals WHERE kind = ? AND status = 'pending'",
        )
        .bind(proposals::kind::SLOT_CONFLICT)
        .fetch_one(pool)
        .await
        .expect("bob was asked");
        let parked = serde_json::from_str::<serde_json::Value>(&context)
            .unwrap()
            .get("parked_capture_id")
            .and_then(serde_json::Value::as_str)
            .map(|id| FactId::parse(id).unwrap())
            .expect("her words are parked, not lost");
        // The two answers are offered to bob in the words of what they do, and
        // what they do now includes the other value.
        let questions: String =
            sqlx::query_scalar("SELECT questions FROM structure_proposals WHERE proposal_id = ?")
                .bind(&proposal)
                .fetch_one(pool)
                .await
                .unwrap();
        assert!(
            questions.contains("record what was said instead")
                && questions.contains("drop what was said instead"),
            "each answer says what becomes of the other value: {questions}"
        );
        (proposal, parked)
    }

    /// One turn, three things it could not do, and the user hears about all
    /// three.
    ///
    /// Two people's cards are asked about and a list item is refused. The
    /// notice named one owner and dropped the other, and the list refusal never
    /// reached the user at all — the chain of `or_else` returned the first
    /// notice and stopped, so the item they believed was on their list was
    /// simply gone.
    #[tokio::test]
    async fn every_notice_the_turn_owes_reaches_the_user() {
        const ZOE_HAS: &str = "Zoe's mobile number is 07700 900314.";
        const ALICE_HAS: &str = "Alice's mobile number is 07700 900500.";
        let (dir, tree, pool) = setup_slot_family().await;
        plant_private_number(&pool, ZOE_HAS, "07700 900314").await;
        plant_private_number_for(&pool, "bob", ALICE_HAS, "07700 900500").await;

        let plan = "{\"intent\":\"capture\",\"extractions\":[\
             {\"target_wiki_id\":\"zoe\",\"subject_id\":\"user:zoe\",\
              \"body\":\"Zoe's mobile number is 07700 900275.\",\"fact_type\":\"bio\",\
              \"salience\":\"high\",\"slot\":\"mobile_number\",\
              \"slot_value\":\"07700 900275\",\"topics\":[\"contact\"]},\
             {\"target_wiki_id\":\"bob\",\"subject_id\":\"user:bob\",\
              \"body\":\"Bob's mobile number is 07700 900601.\",\"fact_type\":\"bio\",\
              \"salience\":\"high\",\"slot\":\"mobile_number\",\
              \"slot_value\":\"07700 900601\",\"topics\":[\"contact\"]},\
             {\"target_wiki_id\":\"alice\",\"subject_id\":\"user:alice\",\
              \"body\":\"Milk is on the shopping list.\",\"fact_type\":\"other\",\
              \"style\":\"lista\",\"topics\":[\"shopping\"]}]}";
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", plan),
            None,
            req(
                "Zoe is on 07700 900275, Bob on 07700 900601, and add milk to the list",
                "alice",
            ),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        let notice = resp.rules.unwrap_or_default();
        for owner in ["zoe", "bob"] {
            assert!(
                notice.contains(owner),
                "every owner the turn asked is named — `{owner}` is missing from: {notice}"
            );
        }
        assert!(
            notice.contains("put something on a list and it was NOT saved"),
            "and the refused list item is still said: {notice}"
        );
        // One box name, two cards: each question has to go to the card it is
        // about. Matching on the box name alone put Bob's number in front of
        // Zoe, in a question about her own record.
        let mut asked: Vec<String> = sqlx::query_scalar(
            "SELECT recipient_id FROM structure_proposals WHERE kind = ? ORDER BY recipient_id",
        )
        .bind(proposals::kind::SLOT_CONFLICT)
        .fetch_all(&pool)
        .await
        .unwrap();
        asked.sort();
        assert_eq!(
            asked,
            vec!["user:bob".to_owned(), "user:zoe".to_owned()],
            "one question each, to the person whose card it is"
        );
        drop(dir);
    }

    /// `user:Zoe` is `user:zoe`, and a capital does not put her number on the
    /// speaker's own card.
    ///
    /// Ids are lowercase by construction, so the enrolment guard is a string
    /// lookup: `user:Zoe` matched nobody, the subject was cleared as a coined
    /// principal, and the claim was re-read as the SPEAKER's — Zoe's mobile
    /// number filed on Alice's identity card, box name and all, with no
    /// question asked. From there the box defended the wrong value: Alice
    /// stating her own number was stopped and asked to choose against Zoe's.
    #[tokio::test]
    async fn a_capital_in_a_principal_is_the_same_principal() {
        const HERS: &str = "Zoe's mobile number is 07700 900314.";
        let (dir, tree, pool) = setup_slot_family().await;
        plant_private_number(&pool, HERS, "07700900314").await;
        let plan = "{\"intent\":\"capture\",\"extractions\":[\
             {\"target_wiki_id\":\"zoe\",\"subject_id\":\"user:Zoe\",\
             \"body\":\"Zoe's mobile number is 07700 900275.\",\"fact_type\":\"bio\",\
             \"salience\":\"high\",\"slot\":\"mobile_number\",\
             \"slot_value\":\"07700900275\",\"topics\":[\"contact\"]}]}";
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", plan),
            None,
            req("Zoe's number is 07700 900275", "alice"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        assert_eq!(
            fact_index::find_active_by_source_path(&pool, "wikis/alice/@profile.md")
                .await
                .unwrap()
                .len(),
            0,
            "Zoe's number does not land on Alice's card"
        );
        assert!(
            capture_buffer::find_all_buffered(&pool, 100)
                .await
                .unwrap()
                .is_empty(),
            "and it is not queued on its way there"
        );
        let recipient: Option<String> = sqlx::query_scalar(
            "SELECT recipient_id FROM structure_proposals WHERE kind = ? AND status = 'pending'",
        )
        .bind(proposals::kind::SLOT_CONFLICT)
        .fetch_one(&pool)
        .await
        .expect("Zoe was asked, exactly as a lowercase id would have asked her");
        assert_eq!(recipient.as_deref(), Some("user:zoe"));
        drop(dir);
    }

    /// A second person with a DIFFERENT value is a second disagreement, not a
    /// repetition of the first.
    ///
    /// Keyed on the box alone, Bob's value found Alice's question already open
    /// and was swallowed: not parked, not in the question, and Zoe was shown a
    /// choice between two values one of which nobody had said.
    #[tokio::test]
    async fn a_different_value_opens_its_own_question() {
        const HERS: &str = "Zoe's mobile number is 07700 900314.";
        let (dir, tree, pool) = setup_slot_family().await;
        plant_private_number(&pool, HERS, "07700900314").await;
        let claim = |number: &str| {
            format!(
                "{{\"intent\":\"capture\",\"extractions\":[\
                 {{\"target_wiki_id\":\"zoe\",\"subject_id\":\"user:zoe\",\
                 \"body\":\"Zoe's mobile number is {number}.\",\"fact_type\":\"bio\",\
                 \"salience\":\"high\",\"slot\":\"mobile_number\",\
                 \"slot_value\":\"{number}\",\"topics\":[\"contact\"]}}]}}"
            )
        };
        for (who, number) in [("alice", "07700900275"), ("bob", "07700900601")] {
            wiki_ingest_message(
                &pool,
                &tree,
                fake_embedder(),
                &FakeLlmBackend::new("fake", claim(number)),
                None,
                req("Zoe's number is that one", who),
                &IngestPolicy::default(),
            )
            .await
            .expect("ingest");
        }

        let contexts: Vec<(String,)> = sqlx::query_as(
            "SELECT context FROM structure_proposals WHERE kind = ? AND status = 'pending'",
        )
        .bind(proposals::kind::SLOT_CONFLICT)
        .fetch_all(&pool)
        .await
        .unwrap();
        assert_eq!(contexts.len(), 2, "two people, two disagreements");
        for number in ["07700900275", "07700900601"] {
            assert!(
                contexts.iter().any(|(c,)| c.contains(number)),
                "the value {number} is in a question of its own: {contexts:?}"
            );
        }
        let parked: i64 =
            sqlx::query_scalar("SELECT count(*) FROM capture_buffer WHERE status = 'held'")
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(parked, 2, "and each has its own claim waiting behind it");
        drop(dir);
    }

    /// A box a card may carry two of is not a disagreement the engine settles
    /// on its own, and its owner is offered *both stand*.
    ///
    /// A work email beside a personal one, a mobile beside a landline: the
    /// engine treats a second value in one of those as a second value. Where
    /// the speaker may READ the one on record it says nothing at all and the
    /// model judges; where they may not, it asks the owner — with three
    /// answers, because *keep* and *replace* are both wrong for a card that
    /// can carry the two.
    #[tokio::test]
    async fn a_box_that_holds_several_values_is_asked_with_three_answers() {
        const HERS: &str = "Zoe's mobile number is 07700 900314.";
        let (dir, tree, pool) = setup_slot_family().await;
        let hers = plant_private_number(&pool, HERS, "07700900314").await;
        let plan = "{\"intent\":\"capture\",\"extractions\":[\
             {\"target_wiki_id\":\"zoe\",\"subject_id\":\"user:zoe\",\
             \"body\":\"Zoe also has a work mobile, 07700 900601.\",\"fact_type\":\"bio\",\
             \"salience\":\"high\",\"slot\":\"mobile_number\",\
             \"slot_value\":\"07700900601\",\"topics\":[\"contact\"]}]}";
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", plan),
            None,
            req("Zoe's work mobile is 07700 900601", "alice"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        let (proposal, questions): (String, String) = sqlx::query_as(
            "SELECT proposal_id, questions FROM structure_proposals \
             WHERE kind = ? AND status = 'pending'",
        )
        .bind(proposals::kind::SLOT_CONFLICT)
        .fetch_one(&pool)
        .await
        .expect("Zoe was asked");
        assert!(
            questions.contains("\"both\""),
            "a card that may carry two numbers is offered both: {questions}"
        );
        assert!(
            questions.contains("may carry more than one of"),
            "and the question says so rather than asking which is right: {questions}"
        );

        proposals::apply_proposal(
            &pool,
            &tree,
            &proposal,
            &serde_json::json!({ "verdict": "both" }),
            Some("zoe"),
            false,
        )
        .await
        .expect("Zoe answers");
        assert!(
            fact_index::find_by_id(&pool, &hers)
                .await
                .unwrap()
                .unwrap()
                .valid_to
                .is_none(),
            "her first number still stands"
        );
        promote_buffer(&pool, &tree).await;
        let card = fact_index::find_active_by_source_path(&pool, "wikis/zoe/@profile.md")
            .await
            .unwrap();
        assert_eq!(card.len(), 2, "and the second one is on the card beside it");
        drop(dir);
    }

    /// On the values the speaker may READ, the engine keeps out of what it
    /// cannot be sure of: a box that holds several values, a value nobody
    /// wrote out, a date in some other notation.
    #[test]
    fn the_served_side_acts_only_where_there_is_nothing_left_to_judge() {
        let stored = |slot: &str, value: Option<&str>| StoredValue {
            fact_id: FactId::parse(CARD_FACT_ID).unwrap(),
            subject: Principal::User("bob".to_owned()),
            text: "bob was born on 12 March 2014".to_owned(),
            sender: None,
            said_on: None,
            slot: Some(slot.to_owned()),
            slot_value: value.map(str::to_owned),
            allow: Vec::new(),
        };
        let claim =
            |slot: &'static str, value: Option<&'static str>, body: &'static str| CaptureUnit {
                fact_type: Some("bio"),
                body: Some(body),
                slot: Some(slot),
                slot_value: value,
                ..bare_unit()
            };
        let raises = |side: SlotSide, s: &StoredValue, u: &CaptureUnit<'_>| {
            value_filling_the_same_slot(
                u,
                &Principal::User("bob".to_owned()),
                side,
                std::slice::from_ref(s),
            )
            .is_some()
        };

        let one_value = stored("date_of_birth", Some("2014-03-12"));
        let plain = claim("date_of_birth", Some("2012-07-08"), "bob was born in 2012");
        assert!(
            raises(SlotSide::Served, &one_value, &plain),
            "one value each, one box, dates written the one way: nothing left to judge"
        );
        assert!(
            !raises(
                SlotSide::Served,
                &one_value,
                &claim("date_of_birth", Some("8 July 2012"), "bob was born in 2012")
            ),
            "a date in another notation is not two values, it is two notations"
        );
        assert!(
            !raises(
                SlotSide::Served,
                &one_value,
                &claim("date_of_birth", None, "bob was born in 2012")
            ),
            "with no value written out there is only prose, and the model reads prose"
        );
        assert!(
            !raises(
                SlotSide::Served,
                &stored("mobile_number", Some("07700900314")),
                &claim("mobile_number", Some("07700900601"), "a second number")
            ),
            "two numbers in a box that holds numbers is not a disagreement"
        );
        assert!(
            raises(
                SlotSide::Hidden,
                &stored("mobile_number", Some("07700900314")),
                &claim("mobile_number", Some("07700900601"), "a second number")
            ),
            "the half nobody else can judge asks anyway — its owner reads both"
        );
        assert!(
            raises(
                SlotSide::Hidden,
                &stored("mobile_number", None),
                &claim("mobile_number", None, "a second number")
            ),
            "and asks on the sentences alone when neither side wrote the value out"
        );
    }

    /// A turn the classifier is already asking about keeps its question, and
    /// the slot the engine found goes to the card's owner instead.
    ///
    /// A synthesised slot question can only reach the person by REPLACING the
    /// one the model raised — two unrelated questions in one list is a choice
    /// nobody can make — so it took the model's question away and answered a
    /// different one. Now the model's question stands and nothing is lost.
    #[tokio::test]
    async fn a_turn_that_already_asks_keeps_its_own_question() {
        let (dir, tree, pool) = setup_family().await;
        let card = plant_the_card_birthdate(&pool).await;
        sqlx::query(
            "UPDATE fact_index SET slot = 'date_of_birth', slot_value = '2014-03-12' \
             WHERE fact_id = ?",
        )
        .bind(card.as_str())
        .execute(&pool)
        .await
        .unwrap();
        let asking = format!(
            "{{\"intent\":\"capture\",\"suggested_seed\":\"Which one?\",\
             \"needs_disambig\":true,\"disambig_candidates\":[\
             {{\"candidate_id\":\"the-dentist\",\"description\":\"the dentist\"}},\
             {{\"candidate_id\":\"the-doctor\",\"description\":\"the doctor\"}}],\
             \"extractions\":[\
             {{\"target_wiki_id\":\"bob\",\"subject_id\":\"user:bob\",\
             \"body\":\"{DERIVED_BIRTHDATE}\",\"fact_type\":\"bio\",\"salience\":\"high\",\
             \"slot\":\"date_of_birth\",\"slot_value\":\"2012-07-08\"}}]}}"
        );
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", &asking),
            None,
            the_age_turn("carol", None),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        let ids: Vec<&str> = resp
            .disambig_candidates
            .iter()
            .map(|c| c.candidate_id.as_str())
            .collect();
        assert_eq!(
            ids,
            vec!["the-dentist", "the-doctor"],
            "the model's own question is what the person is asked"
        );
        let recipient: Option<String> = sqlx::query_scalar(
            "SELECT recipient_id FROM structure_proposals WHERE kind = ? AND status = 'pending'",
        )
        .bind(proposals::kind::SLOT_CONFLICT)
        .fetch_one(&pool)
        .await
        .expect("and the slot went to the card's owner instead of being dropped");
        assert_eq!(recipient.as_deref(), Some("user:bob"));
        assert!(
            resp.rules.unwrap_or_default().contains("NOT saved"),
            "carol is told her value was not saved"
        );
        drop(dir);
    }

    /// A shared record has no one person to write to, so the notice says where
    /// it really went.
    #[test]
    fn a_shared_record_is_passed_to_the_administrator() {
        let alice = Principal::User("alice".to_owned());
        let mine = slot_notice(&[Principal::User("zoe".to_owned())], &alice).unwrap_or_default();
        assert!(
            mine.contains("They have been asked"),
            "a person's own card is put to them: {mine}"
        );
        let shared =
            slot_notice(&[Principal::Group("famiglia".to_owned())], &alice).unwrap_or_default();
        assert!(
            shared.contains("administrator"),
            "a group's record has no inbox, and the notice says so: {shared}"
        );
        assert!(
            !shared.contains("They have been asked"),
            "and does not name a person who was never asked: {shared}"
        );
    }

    /// The slot list the prompt publishes and the one the engine enforces are
    /// the same list, family by family.
    ///
    /// They are two copies by necessity — one is read by a model, the other by
    /// the code — and nothing but this ties them together. A name in the
    /// prompt and not in the engine is refused on arrival; a name in the
    /// engine and not in the prompt is one the model never writes; and a box
    /// filed under the wrong family is the difference between a question and a
    /// second value filed quietly.
    #[test]
    fn the_prompt_publishes_exactly_the_slots_the_engine_knows() {
        let after = |marker: &str| -> Vec<String> {
            let at = BUNDLED_INGEST_PROMPT_MD
                .find(marker)
                .unwrap_or_else(|| panic!("the prompt does not mark `{marker}`"));
            let line = BUNDLED_INGEST_PROMPT_MD[at..]
                .lines()
                .nth(1)
                .expect("a list on the line after the marker");
            line.split('`')
                .skip(1)
                .step_by(2)
                .map(str::to_owned)
                .collect()
        };
        assert_eq!(
            after("**ONE VALUE —"),
            ONE_VALUE_SLOTS
                .iter()
                .map(|s| (*s).to_owned())
                .collect::<Vec<_>>(),
            "the boxes the prompt calls single-valued are the ones the engine acts on alone"
        );
        assert_eq!(
            after("**MORE THAN ONE —"),
            MANY_VALUE_SLOTS
                .iter()
                .map(|s| (*s).to_owned())
                .collect::<Vec<_>>(),
            "and the ones it calls many-valued are the ones it leaves to the model"
        );
    }

    /// Two phrasings of one number with no bare value written out are ONE
    /// question, not two.
    ///
    /// The key that tells two disagreements apart is the claimed VALUE, and a
    /// claim that never wrote its value out has none: folding the sentence
    /// instead makes «Zoe's mobile is …» and «Zoe can be reached on …» two
    /// keys, so the owner is asked twice about one number and two claims are
    /// parked behind the two questions. Every fact written before the value
    /// column existed is on this side of it.
    #[tokio::test]
    async fn two_phrasings_with_no_bare_value_are_one_question() {
        const HERS: &str = "Zoe's mobile number is 07700 900314.";
        let (dir, tree, pool) = setup_slot_family().await;
        plant_private_number(&pool, HERS, "07700900314").await;
        let claim = |body: &str| {
            format!(
                "{{\"intent\":\"capture\",\"extractions\":[\
                 {{\"target_wiki_id\":\"zoe\",\"subject_id\":\"user:zoe\",\
                 \"body\":\"{body}\",\"fact_type\":\"bio\",\"salience\":\"high\",\
                 \"slot\":\"mobile_number\",\"topics\":[\"contact\"]}}]}}"
            )
        };
        for body in [
            "Zoe's mobile number is 07700 900275.",
            "Zoe can be reached on 07700 900275",
        ] {
            wiki_ingest_message(
                &pool,
                &tree,
                fake_embedder(),
                &FakeLlmBackend::new("fake", claim(body)),
                None,
                req("Zoe's number is 07700 900275", "alice"),
                &IngestPolicy::default(),
            )
            .await
            .expect("ingest");
        }

        let opened: i64 = sqlx::query_scalar(
            "SELECT count(*) FROM structure_proposals WHERE kind = ? AND status = 'pending'",
        )
        .bind(proposals::kind::SLOT_CONFLICT)
        .fetch_one(&pool)
        .await
        .unwrap();
        assert_eq!(opened, 1, "one number, one question");
        let parked: i64 =
            sqlx::query_scalar("SELECT count(*) FROM capture_buffer WHERE status = 'held'")
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(parked, 1, "and one claim behind it");
        drop(dir);
    }

    /// When the card is the SPEAKER's own, the notice speaks to them and says
    /// why — and the reason on the question is the true one.
    ///
    /// The turn was already asking them something else, which is the only
    /// reason the box did not reach them in the conversation. Telling them
    /// «they have been asked» about their own record names somebody who is not
    /// there, and «they are not the person this record belongs to» is simply
    /// false.
    #[tokio::test]
    async fn a_box_of_your_own_card_is_put_to_you_in_the_second_person() {
        let (dir, tree, pool) = setup_family().await;
        let card = plant_the_card_birthdate(&pool).await;
        sqlx::query(
            "UPDATE fact_index SET slot = 'date_of_birth', slot_value = '2014-03-12' \
             WHERE fact_id = ?",
        )
        .bind(card.as_str())
        .execute(&pool)
        .await
        .unwrap();
        let asking = format!(
            "{{\"intent\":\"capture\",\"suggested_seed\":\"Which one?\",\
             \"needs_disambig\":true,\"disambig_candidates\":[\
             {{\"candidate_id\":\"the-dentist\",\"description\":\"the dentist\"}},\
             {{\"candidate_id\":\"the-doctor\",\"description\":\"the doctor\"}}],\
             \"extractions\":[\
             {{\"target_wiki_id\":\"bob\",\"subject_id\":\"user:bob\",\
             \"body\":\"{DERIVED_BIRTHDATE}\",\"fact_type\":\"bio\",\"salience\":\"high\",\
             \"slot\":\"date_of_birth\",\"slot_value\":\"2012-07-08\"}}]}}"
        );
        // bob speaks about bob's own card.
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", &asking),
            None,
            the_age_turn("bob", None),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        let notice = resp.rules.unwrap_or_default();
        assert!(
            notice.contains("THEMSELVES") && notice.contains("second person"),
            "the agent is told to speak to him about his own record: {notice}"
        );
        assert!(
            notice.contains("Proposals"),
            "and to say where the question is waiting: {notice}"
        );
        assert!(
            !notice.contains("They have been asked"),
            "and not to speak of him in the third person: {notice}"
        );
        let context: String = sqlx::query_scalar(
            "SELECT context FROM structure_proposals WHERE kind = ? AND status = 'pending'",
        )
        .bind(proposals::kind::SLOT_CONFLICT)
        .fetch_one(&pool)
        .await
        .expect("the question is his");
        assert!(
            context.contains("the turn was already asking them something else"),
            "the reason on the question is the true one: {context}"
        );
        assert!(
            !context.contains("not the person this record belongs to"),
            "and not the one about standing, which is false here: {context}"
        );
        drop(dir);
    }

    /// A box a card may carry two of keeps BOTH when nobody answers.
    ///
    /// Silence applies the recommended answer. On a detail there can only be
    /// one of, that is *keep*: what is on record was stated by somebody
    /// entitled to state it. On a detail a card may carry several of, dropping
    /// the claim to be safe throws away something true and leaves the person
    /// to say it again, so the recommended answer is *both*.
    #[tokio::test]
    async fn silence_keeps_both_values_where_a_card_may_carry_two() {
        const HERS: &str = "Zoe's mobile number is 07700 900314.";
        let (dir, tree, pool) = setup_slot_family().await;
        let hers = plant_private_number(&pool, HERS, "07700900314").await;
        let plan = "{\"intent\":\"capture\",\"extractions\":[\
             {\"target_wiki_id\":\"zoe\",\"subject_id\":\"user:zoe\",\
             \"body\":\"Zoe also has a work mobile, 07700 900601.\",\"fact_type\":\"bio\",\
             \"salience\":\"high\",\"slot\":\"mobile_number\",\
             \"slot_value\":\"07700900601\",\"topics\":[\"contact\"]}]}";
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", plan),
            None,
            req("Zoe's work mobile is 07700 900601", "alice"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        // The deadline passes with no answer: the sweep applies whatever the
        // question marked as recommended.
        let overdue: String = sqlx::query_scalar(
            "SELECT proposal_id FROM structure_proposals WHERE kind = ? AND status = 'pending'",
        )
        .bind(proposals::kind::SLOT_CONFLICT)
        .fetch_one(&pool)
        .await
        .unwrap();
        sqlx::query("UPDATE structure_proposals SET timeout_at = ? WHERE proposal_id = ?")
            .bind("2000-01-01T00:00:00Z")
            .bind(&overdue)
            .execute(&pool)
            .await
            .unwrap();
        proposals::auto_apply_overdue_proposals(&pool, &tree, chrono::Utc::now())
            .await
            .expect("the sweep");

        assert!(
            fact_index::find_by_id(&pool, &hers)
                .await
                .unwrap()
                .unwrap()
                .valid_to
                .is_none(),
            "the number on record stands"
        );
        promote_buffer(&pool, &tree).await;
        let card = fact_index::find_active_by_source_path(&pool, "wikis/zoe/@profile.md")
            .await
            .unwrap();
        assert_eq!(
            card.len(),
            2,
            "and the second one is kept too: losing a true value costs more than holding one \
             too many"
        );
        drop(dir);
    }

    /// A uuid the model copied back in capitals names the fact it names.
    ///
    /// Every reader of these fields compares the string against an id the
    /// engine wrote in lowercase, so `0190F3C2-…` matched nothing: the
    /// declared conflict was dropped as a hallucinated id and the second birth
    /// date filed beside the first.
    #[tokio::test]
    async fn a_fact_id_in_capitals_names_the_same_fact() {
        let (dir, tree, pool) = setup_family().await;
        let card = plant_the_card_birthdate(&pool).await;
        let shouted = CARD_FACT_ID.to_uppercase();
        let plan = format!(
            "{{\"intent\":\"capture\",\"suggested_seed\":\"Noted.\",\"extractions\":[\
             {{\"target_wiki_id\":\"bob\",\"subject_id\":\"user:bob\",\
             \"body\":\"{DERIVED_BIRTHDATE}\",\"fact_type\":\"bio\",\"salience\":\"high\",\
             \"conflicts_with\":\"{shouted}\",\"slot\":\"date_of_birth\",\
             \"slot_value\":\"2012-07-08\"}}]}}"
        );
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", &plan),
            None,
            the_age_turn("carol", None),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        assert!(
            resp.needs_disambig,
            "the conflict it declared is the one it meant"
        );
        let ids: Vec<&str> = resp
            .disambig_candidates
            .iter()
            .map(|c| c.candidate_id.as_str())
            .collect();
        assert!(
            ids.iter().all(|id| id.ends_with(CARD_FACT_ID)),
            "and the candidates name the stored fact in the spelling the memory uses: {ids:?}"
        );
        assert!(
            fact_index::find_by_id(&pool, &card)
                .await
                .unwrap()
                .unwrap()
                .valid_to
                .is_none(),
            "nothing is written until the answer"
        );
        drop(dir);
    }

    /// A slot name outside the list is refused; a listed one comes back in its
    /// one spelling.
    #[test]
    fn only_a_name_from_the_card_s_own_list_is_a_slot() {
        for (written, canonical) in [
            ("date_of_birth", "date_of_birth"),
            ("Date of birth", "date_of_birth"),
            ("  MOBILE-NUMBER ", "mobile_number"),
        ] {
            assert_eq!(
                card_slot(written),
                Some(canonical),
                "{written:?} is how a model writes {canonical}"
            );
        }
        for outside in [
            "birthday",
            "birth_date",
            "data_di_nascita",
            "the date of birth",
            "shoe_size",
            "",
        ] {
            assert_eq!(
                card_slot(outside),
                None,
                "{outside:?} is not one of the card's boxes, and admitting it would make a \
                 second name for a box that already has one"
            );
        }
        assert!(slot_holds_one_value("date_of_birth"));
        assert!(!slot_holds_one_value("mobile_number"));
    }

    /// The date shape the prompt asks for, and what falls outside it.
    #[test]
    fn a_canonical_date_is_the_one_notation_the_engine_compares() {
        for good in ["1983-05-09", "1983-05", "--05-09"] {
            assert!(is_canonical_date(good), "{good} is the form asked for");
        }
        for other in ["9 May 1983", "09/05/1983", "1983", "83-05-09", "", "Marco"] {
            assert!(
                !is_canonical_date(other),
                "{other:?} is a value the engine will not read as a day"
            );
        }
    }

    /// A slot the card has no name for costs the fact nothing except the
    /// comparison: it files exactly as every fact filed before boxes existed.
    #[tokio::test]
    async fn a_slot_outside_the_list_is_not_recorded_and_the_fact_still_files() {
        let (dir, tree, pool) = setup_workdir().await;
        let json = "{\"intent\":\"capture\",\"extractions\":[{\"subject_id\":\"user:alice\",\
                    \"body\":\"Alice takes a size 39 shoe.\",\"fact_type\":\"bio\",\
                    \"salience\":\"high\",\"slot\":\"shoe_size\",\"slot_value\":\"39\",\
                    \"topics\":[\"clothing\"]}]}";
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &FakeLlmBackend::new("fake", json),
            None,
            req("I take a 39", "alice"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");
        assert!(resp.capture_id.is_some(), "the fact is not lost");
        let waiting = capture_buffer::find_all_buffered(&pool, 10).await.unwrap();
        assert_eq!(
            waiting.first().and_then(|c| c.slot.as_deref()),
            None,
            "and it carries no box, so it takes part in no comparison"
        );
        assert_eq!(waiting.first().and_then(|c| c.slot_value.as_deref()), None);
        drop(dir);
    }

    /// Restating the SAME value is not a conflict: it files as the duplicate
    /// it is, and nobody is asked to choose between a sentence and itself.
    #[tokio::test]
    async fn restating_the_same_value_asks_nobody() {
        let (dir, tree, pool) = setup_family().await;
        plant_the_card_birthdate(&pool).await;
        let plan = format!(
            "{{\"intent\":\"capture\",\"extractions\":[\
             {{\"target_wiki_id\":\"bob\",\"subject_id\":\"user:bob\",\
             \"body\":\"{CARD_BIRTHDATE}\",\"fact_type\":\"bio\",\"salience\":\"high\",\
             \"conflicts_with\":\"{CARD_FACT_ID}\",\"slot\":\"date_of_birth\"}}]}}"
        );
        let llm = FakeLlmBackend::new("fake", &plan);
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            the_age_turn("carol", None),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");
        assert!(
            !resp.needs_disambig,
            "the same value is a duplicate, not a disagreement"
        );
        assert!(
            resp.capture_id.is_some(),
            "and it files like any restatement"
        );
        drop(dir);
    }

    /// `needs_disambig` on its own holds nothing back — only a declared slot
    /// conflict does.
    ///
    /// The two questions are not the same question. The classifier raises
    /// `needs_disambig` when it cannot tell WHICH stored fact a turn refers to
    /// ("the dentist", with three on file); that is a reading problem, and the
    /// facts the same turn states have nothing to do with it. Holding those
    /// back would lose them outright for a consumer that never sends the
    /// choice, against the rule that a capture is never traded away. A slot
    /// conflict is the opposite shape: the write ITSELF is what nobody may
    /// decide, so that one extraction — and only it — waits.
    #[tokio::test]
    async fn needs_disambig_alone_does_not_hold_a_capture_back() {
        let (dir, tree, pool) = setup_workdir().await;
        let json = "{\"intent\":\"capture\",\"needs_disambig\":true,\
                    \"disambig_candidates\":[{\"candidate_id\":\"a\",\"description\":\"which dentist\"}],\
                    \"extractions\":[{\"target_wiki_id\":\"alice\",\"subject_id\":\"user:alice\",\
                    \"body\":\"Alice moved her appointment to the 20th.\",\"fact_type\":\"plan\"}]}";
        let llm = FakeLlmBackend::new("fake", json);
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req("ho spostato l'appuntamento al 20", "alice"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        assert!(
            resp.needs_disambig,
            "the reading question still reaches the consumer"
        );
        assert!(
            resp.capture_id.is_some(),
            "and the fact the turn stated is filed all the same"
        );
        assert_eq!(
            capture_buffer::find_all_buffered(&pool, 100)
                .await
                .unwrap()
                .len(),
            1,
            "queued, not held"
        );
        drop(dir);
    }

    /// End-to-end of the supersede wiring: with a fact already in
    /// `fact_index` and the LLM emitting `supersede_target` pointing at
    /// its `fact_id`, the orchestrator must (a) write a new row, (b)
    /// stamp `superseded_at`/`superseded_by` on the old row, and (c)
    /// surface the new row's `fact_id` as `capture_id`. This is the
    /// behaviour that was missing before the wiring landed — the prompt
    /// emitted `supersede_target` but the orchestrator ignored it
    /// and just inserted a duplicate new row.
    #[tokio::test]
    async fn ingest_supersede_target_routes_to_wiki_supersede() {
        let (dir, tree, pool) = setup_workdir().await;
        // Plant the row that we want the next turn to supersede.
        let cap_req = CaptureRequest {
            subject_external: None,
            slot: None,
            slot_value: None,
            authored_refs: Vec::new(),
            wiki_id: WikiId::parse("alice").unwrap(),
            page: Some(PathBuf::from("cucina.md")),
            body: "alice prefers coffee black".into(),
            subject: Principal::User("alice".into()),
            allow: Vec::new(),
            sender: None,
            fact_type: Some("preference".into()),
            topics: vec!["coffee".into()],
            dedup_threshold: Some(0.99),
            valid_from: None,
            valid_to: None,
            style: None,
            page_description: None,
            salience: None,
        };
        let planted = capture::wiki_capture(&tree, &pool, fake_embedder(), cap_req)
            .await
            .expect("plant");

        // LLM returns capture intent with supersede_target pointing at
        // the planted row. The new body contradicts the recalled fact.
        // `requested_container: true` keeps the live direct-write path so
        // the supersede routes to `wiki_supersede` (a plain
        // capture into the standard `alice` wiki would buffer instead).
        let llm_resp = format!(
            "{{\"intent\":\"capture\",\"target_wiki_id\":\"alice\",\
             \"target_page\":\"preferenze.md\",\"subject_id\":\"user:alice\",\
             \"body\":\"alice now prefers tea\",\
             \"fact_type\":\"preference\",\"topics\":[\"tea\"],\
             \"requested_container\":true,\
             \"supersede_target\":\"{}\",\
             \"suggested_seed\":\"Aggiornato.\"}}",
            planted.fact_id.as_str()
        );
        let llm = FakeLlmBackend::new("fake", &llm_resp);
        let policy = IngestPolicy::default();

        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req("ora preferisco il tè", "alice"),
            &policy,
        )
        .await
        .expect("ingest");

        assert_eq!(resp.intent, IntentKind::Capture);
        let new_fact_id = resp.capture_id.expect("must surface the new fact_id");
        assert_ne!(
            new_fact_id, planted.fact_id,
            "supersede must mint a fresh fact_id, not reuse the old one"
        );

        // The new row is active and carries the new body.
        let new_row = fact_index::find_by_id(&pool, &new_fact_id)
            .await
            .expect("find new")
            .expect("new row exists");
        assert_eq!(new_row.text, "alice now prefers tea");
        assert!(
            new_row.superseded_at.is_none(),
            "the freshly captured row must remain active"
        );

        // The old row is now tombstoned with superseded_by pointing at the new one.
        let old_row = fact_index::find_by_id(&pool, &planted.fact_id)
            .await
            .expect("find old")
            .expect("old row exists");
        assert!(
            old_row.superseded_at.is_some(),
            "the recalled row must have superseded_at stamped"
        );
        assert_eq!(
            old_row.superseded_by.as_ref(),
            Some(&new_fact_id),
            "old row must point at the new fact_id"
        );

        drop(dir);
    }

    /// Supersede is a CONTENT update, not a sharing change: the new fact
    /// INHERITS the superseded fact's `allow`, even when the classifier's
    /// supersede extraction carries none. Without this a re-statement
    /// silently re-privatizes a shared fact.
    #[tokio::test]
    async fn ingest_supersede_inherits_the_superseded_facts_allow() {
        let (dir, tree, pool) = setup_workdir().await;
        // Plant a fact SHARED with group:famiglia.
        let cap_req = CaptureRequest {
            subject_external: None,
            slot: None,
            slot_value: None,
            authored_refs: Vec::new(),
            wiki_id: WikiId::parse("alice").unwrap(),
            page: Some(PathBuf::from("cucina.md")),
            body: "alice is 72 kg".into(),
            subject: Principal::User("alice".into()),
            allow: vec![Principal::Group("famiglia".into())],
            sender: None,
            fact_type: Some("state".into()),
            page_description: None,
            topics: vec!["weight".into()],
            dedup_threshold: Some(0.99),
            valid_from: None,
            valid_to: None,
            style: None,
            salience: None,
        };
        let planted = capture::wiki_capture(&tree, &pool, fake_embedder(), cap_req)
            .await
            .expect("plant");

        // The supersede extraction carries NO allow_ids — the classifier
        // restated only the content.
        let llm_resp = format!(
            "{{\"intent\":\"capture\",\"target_wiki_id\":\"alice\",\
             \"target_page\":\"preferenze.md\",\"subject_id\":\"user:alice\",\
             \"body\":\"alice is 73 kg\",\
             \"fact_type\":\"state\",\"topics\":[\"weight\"],\
             \"requested_container\":true,\
             \"supersede_target\":\"{}\",\
             \"suggested_seed\":\"Aggiornato.\"}}",
            planted.fact_id.as_str()
        );
        let llm = FakeLlmBackend::new("fake", &llm_resp);
        let policy = IngestPolicy::default();

        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req("ora peso 73 kg", "alice"),
            &policy,
        )
        .await
        .expect("ingest");

        let new_fact_id = resp.capture_id.expect("must surface the new fact_id");
        let new_row = fact_index::find_by_id(&pool, &new_fact_id)
            .await
            .expect("find new")
            .expect("new row exists");
        assert_eq!(
            new_row.allow_ids,
            vec![Principal::Group("famiglia".into())],
            "supersede must INHERIT the superseded fact's allow, not reset it to empty"
        );

        drop(dir);
    }

    // ---------- the closure verb (completion / forget gesture) ----------

    /// A pure closure turn (intent capture, empty extractions, one closure
    /// against a recalled fact) must close the target's validity, emit the
    /// born-applied `validity_close` receipt + the `structure_applied`
    /// notice, and must NOT demote to the skip fallback.
    #[tokio::test]
    async fn ingest_closure_completes_a_recalled_open_fact() {
        let (dir, tree, pool) = setup_workdir().await;
        // Plant the open watchlist item the next turn completes.
        let cap_req = CaptureRequest {
            subject_external: None,
            slot: None,
            slot_value: None,
            authored_refs: Vec::new(),
            wiki_id: WikiId::parse("alice").unwrap(),
            page: Some(PathBuf::from("cucina.md")),
            body: "alice wants to watch Jumanji".into(),
            subject: Principal::User("alice".into()),
            allow: Vec::new(),
            sender: None,
            fact_type: Some("plan".into()),
            page_description: None,
            topics: vec!["film".into()],
            dedup_threshold: Some(0.99),
            valid_from: None,
            valid_to: None,
            style: None,
            salience: None,
        };
        let planted = capture::wiki_capture(&tree, &pool, fake_embedder(), cap_req)
            .await
            .expect("plant");

        let llm_resp = format!(
            "{{\"intent\":\"capture\",\"extractions\":[],\
             \"closures\":[{{\"target\":\"{}\",\"reason\":\"completed\",\
             \"valid_to\":\"2026-06-10T22:00:00Z\"}}],\
             \"suggested_seed\":\"Segnato come visto.\"}}",
            planted.fact_id.as_str()
        );
        // Scripted rather than a fake that repeats itself: the reconciliation
        // stage runs after the reading and would otherwise be handed the
        // classifier's own JSON back and apply the same closure twice. This
        // test is about the operator-override route into `apply_plan_closures`,
        // so the stage is scripted to change nothing.
        let llm = ScriptedLlm::new(&[
            &llm_resp,
            "{\"closures\":[],\"validity_edits\":[],\"acl_changes\":[]}",
        ]);
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req("ieri sera abbiamo visto Jumanji", "alice"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        // The turn is real activity — never the skip fallback.
        assert_eq!(resp.intent, IntentKind::Capture);
        assert_eq!(resp.suggested_seed.as_deref(), Some("Segnato come visto."));

        // The target's window closed with the completion stamp.
        let row = fact_index::find_by_id(&pool, &planted.fact_id)
            .await
            .expect("find")
            .expect("row");
        assert_eq!(row.valid_to.as_deref(), Some("2026-06-10T22:00:00Z"));
        assert_eq!(
            row.decay_reason.as_deref(),
            Some(fact_index::decay::COMPLETED)
        );
        assert!(row.deleted_at.is_none(), "closure is never a tombstone");

        // One born-applied receipt with the validity_close spec.
        let (status, spec): (String, String) = sqlx::query_as(
            "SELECT status, spec FROM structure_proposals WHERE kind = 'wiki_promote'",
        )
        .fetch_one(&pool)
        .await
        .expect("receipt row");
        assert_eq!(status, "applied");
        let spec: serde_json::Value = serde_json::from_str(&spec).unwrap();
        assert_eq!(spec["variant"], "validity_close");
        assert_eq!(spec["closures"][0]["fact_id"], planted.fact_id.as_str());
        assert!(
            spec["closures"][0]["prev_valid_to"].is_null(),
            "the receipt records that the window was open before"
        );

        // The dashboard notice.
        let n: i64 =
            sqlx::query_scalar("SELECT count(*) FROM wiki_events WHERE kind = 'structure_applied'")
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(n, 1);
        drop(dir);
    }

    /// One turn, two facts, two people: two receipts, and neither carries
    /// the other's words.
    ///
    /// Somebody a fact was shared with may close it, so a single turn can
    /// close facts belonging to several people. The receipt stores 120
    /// characters of each fact it records and nothing re-projects that per
    /// reader, so one receipt for the batch would have handed whoever the
    /// first fact named a preview of everybody else's.
    ///
    /// The gesture is asserted absent from both: the sentence was said by
    /// a third person, and neither addressee gets to read what was being
    /// talked about in somebody else's conversation.
    #[tokio::test]
    async fn a_turn_closing_two_peoples_facts_writes_one_receipt_each() {
        let (dir, _tree, pool) = setup_workdir().await;
        // A second household member, so the turn below closes one fact of
        // each — which is the whole premise. The tree is reopened with him
        // in it, so the fixture's first handle is never the one used.
        let wikis = dir.path().join("wikis");
        write_wiki(&wikis, "bob", "Bob", "wiki-user", None);
        let tree = WikiTree::open(dir.path()).expect("reopen with bob");
        sqlx::query(
            "INSERT INTO enrollment_users (user_id, aliases, is_admin) VALUES ('bob','[]',0)",
        )
        .execute(&pool)
        .await
        .unwrap();
        let alices = plant_fact_carol_can_close(&tree, &pool, "alice", "alice wants Jumanji").await;
        let bobs = plant_fact_carol_can_close(&tree, &pool, "bob", "bob wants Casablanca").await;

        let llm_resp = format!(
            "{{\"intent\":\"capture\",\"extractions\":[],\
             \"closures\":[{{\"target\":\"{a}\",\"reason\":\"completed\",\
             \"valid_to\":\"2026-06-10T22:00:00Z\"}},\
             {{\"target\":\"{b}\",\"reason\":\"completed\",\
             \"valid_to\":\"2026-06-10T22:00:00Z\"}}],\
             \"suggested_seed\":\"Segnati come visti.\"}}",
            a = alices.as_str(),
            b = bobs.as_str(),
        );
        let llm = ScriptedLlm::new(&[
            &llm_resp,
            "{\"closures\":[],\"validity_edits\":[],\"acl_changes\":[]}",
        ]);
        wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            req("li abbiamo visti tutti e due ieri sera", "carol"),
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");

        let rows: Vec<(String, Option<String>)> = sqlx::query_as(
            "SELECT context, recipient_id FROM structure_proposals \
              WHERE kind = 'wiki_promote' ORDER BY recipient_id",
        )
        .fetch_all(&pool)
        .await
        .expect("receipts");
        assert_eq!(
            rows.len(),
            2,
            "one receipt per person, not one for the batch"
        );

        for (context, recipient) in &rows {
            let printed: serde_json::Value = serde_json::from_str(context).unwrap();
            assert_eq!(printed["variant"], "validity_close");
            assert_eq!(
                printed["closed"].as_array().expect("closed").len(),
                1,
                "a receipt carries only its own reader's fact"
            );
            let (mine, theirs) = match recipient.as_deref() {
                Some("user:alice") => ("Jumanji", "Casablanca"),
                Some("user:bob") => ("Casablanca", "Jumanji"),
                other => panic!("unexpected addressee {other:?}"),
            };
            assert!(
                context.contains(mine),
                "{recipient:?} must read its own: {context}"
            );
            assert!(
                !context.contains(theirs),
                "{recipient:?} must not read the other person's fact: {context}"
            );
            assert!(
                printed.get("gesture").is_none(),
                "the sentence was carol's, and neither addressee said it: {context}"
            );
        }
        drop(dir);
    }

    /// One fact owned and authored by `subject`, shared with carol so she
    /// can close it in a turn of her own.
    async fn plant_fact_carol_can_close(
        tree: &WikiTree,
        pool: &SqlitePool,
        subject: &str,
        body: &str,
    ) -> FactId {
        capture::wiki_capture(
            tree,
            pool,
            fake_embedder(),
            CaptureRequest {
                subject_external: None,
                slot: None,
                slot_value: None,
                authored_refs: Vec::new(),
                wiki_id: WikiId::parse(subject).unwrap(),
                page: Some(PathBuf::from("cucina.md")),
                body: body.to_owned(),
                subject: Principal::User(subject.to_owned()),
                allow: vec![Principal::User("carol".into())],
                sender: Some(Principal::User(subject.to_owned())),
                fact_type: Some("plan".into()),
                page_description: None,
                topics: vec!["film".into()],
                dedup_threshold: Some(0.99),
                valid_from: None,
                valid_to: None,
                style: None,
                salience: None,
            },
        )
        .await
        .expect("plant")
        .fact_id
    }

    /// A closure whose `valid_to` is a MALFORMED non-ISO string (an
    /// unresolved relative phrase the classifier failed to convert) must not
    /// poison the stored row: the bad bound is treated as absent and falls
    /// back to this turn's instant, exactly like the validity-edit path.
    #[tokio::test]
    async fn ingest_closure_with_malformed_valid_to_falls_back_to_turn_now() {
        let (dir, tree, pool) = setup_workdir().await;
        let cap_req = CaptureRequest {
            subject_external: None,
            slot: None,
            slot_value: None,
            authored_refs: Vec::new(),
            wiki_id: WikiId::parse("alice").unwrap(),
            page: Some(PathBuf::from("cucina.md")),
            body: "alice wants to watch Jumanji".into(),
            subject: Principal::User("alice".into()),
            allow: Vec::new(),
            sender: None,
            fact_type: Some("plan".into()),
            page_description: None,
            topics: vec!["film".into()],
            dedup_threshold: Some(0.99),
            valid_from: None,
            valid_to: None,
            style: None,
            salience: None,
        };
        let planted = capture::wiki_capture(&tree, &pool, fake_embedder(), cap_req)
            .await
            .expect("plant");

        // The classifier emits a relative phrase instead of an ISO instant.
        let llm_resp = format!(
            "{{\"intent\":\"capture\",\"extractions\":[],\
             \"closures\":[{{\"target\":\"{}\",\"reason\":\"completed\",\
             \"valid_to\":\"ieri sera\"}}],\
             \"suggested_seed\":\"Segnato come visto.\"}}",
            planted.fact_id.as_str()
        );
        let llm = FakeLlmBackend::new("fake", &llm_resp);
        let occurred = chrono::DateTime::parse_from_rfc3339("2026-06-11T09:00:00Z")
            .expect("fixture timestamp")
            .with_timezone(&chrono::Utc);
        let request = IngestRequest {
            metadata: IngestMetadata {
                occurred_at: Some(occurred),
                ..Default::default()
            },
            ..req("ieri sera abbiamo visto Jumanji", "alice")
        };
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            None,
            request,
            &IngestPolicy::default(),
        )
        .await
        .expect("ingest");
        assert_eq!(resp.intent, IntentKind::Capture);

        // The window closed at the turn's instant, NOT the garbage string —
        // and in the one spelling the column is compared in, since the
        // due-soon scan reads `valid_to` as a string.
        let row = fact_index::find_by_id(&pool, &planted.fact_id)
            .await
            .expect("find")
            .expect("row");
        assert_eq!(
            row.valid_to.as_deref(),
            Some(fact_index::bound_from_instant(occurred).as_str()),
            "a malformed valid_to must fall back to turn_now, never store verbatim"
        );
        assert_eq!(
            row.decay_reason.as_deref(),
            Some(fact_index::decay::COMPLETED)
        );
        assert!(row.deleted_at.is_none(), "closure is never a tombstone");
        drop(dir);
    }

