    #[tokio::test]
    async fn ingest_recall_turn_appends_navigated_memory_section() {
        let (dir, tree, pool) = setup_workdir().await;
        // A page that is NOT the identity card: the card is served whole by
        // the deterministic `WHO IS SPEAKING` slot (69a) and is dropped from
        // this section by construction, so navigation is exercised on a
        // sibling page instead.
        std::fs::write(
            dir.path().join("wikis/alice/bologna.md"),
            "# bologna\nalice's city page\n",
        )
        .unwrap();
        // One active fact on the opened page makes the fragment header
        // carry the in-band freshness annotation (`· updated <date>`).
        let fact = fact_index::NewFact {
            subject_external: None,
            slot: None,
            slot_value: None,
            authored_refs: Vec::new(),
            fact_id: FactId::parse("018f1234-5678-7abc-9def-00000000f001").unwrap(),
            wiki_id: "alice".to_owned(),
            source_path: "wikis/alice/bologna.md".to_owned(),
            region_start: None,
            region_end: None,
            text: "alice lives in Bologna".to_owned(),
            embedding: vec![0.9, -0.3, 0.2, -0.1],
            subject_id: Principal::User("alice".into()),
            allow_ids: Vec::new(),
            sender_id: None,
            fact_type: Some("bio".to_owned()),
            topics: Vec::new(),
            valid_from: None,
            valid_to: None,
            salience: None,
            target_page: None,
            style: None,
            source_ref: None,
        };
        fact_index::insert(&pool, &fact).await.expect("insert fact");

        // The classifier only routes intent; the flat recap is deterministic.
        // This turn's point is the navigated section below.
        let llm = FakeLlmBackend::new("fake", "{\"intent\":\"recall\"}");
        // The fact's own page is a `rag`-seeded candidate; the navigator
        // opens it and stops.
        let nav = FakeLlmBackend::new(
            "fake-nav",
            "{\"open\":[{\"wiki_id\":\"alice\",\"page\":\"bologna.md\"}],\"done\":true}",
        );
        let policy = IngestPolicy::default();
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            Some(&nav),
            req("what do you know about me?", "alice"),
            &policy,
        )
        .await
        .expect("ingest");
        assert_eq!(resp.intent, IntentKind::Recall);
        let snippet = resp.context_snippet.expect("recall block present");
        assert!(
            snippet.contains(HDR_NAVIGATED_PAGES),
            "navigated section present: {snippet}"
        );
        assert!(
            snippet.contains("(alice/bologna.md · updated 20"),
            "fragment is page-headed with the freshness annotation: {snippet}"
        );
        assert!(snippet.contains("# bologna"), "projected prose: {snippet}");
        // The flat hit is homed on the page the navigator just injected —
        // the RELEVANT MEMORY slot drops it instead of repeating it (41f).
        assert!(
            !snippet.contains("- (alice) alice lives in Bologna"),
            "a hit homed on a navigated page must not arrive twice: {snippet}"
        );
        drop(dir);
    }

    /// The turn that asks for a shallower recall gets exactly one thing
    /// less.
    ///
    /// Same corpus, same message and same intent as
    /// [`ingest_recall_turn_appends_navigated_memory_section`], which walks
    /// the page — here `metadata.recall` is `light`, so the navigator is
    /// never called at all (`PanickingLlm` would blow the test up if it
    /// were) and the block carries no `NAVIGATED PAGES`. Everything else
    /// stands: the flat hit that the walk would have swallowed is served, so
    /// the turn still answers from memory.
    #[tokio::test]
    async fn a_light_turn_skips_the_walk_and_changes_nothing_else() {
        let (dir, tree, pool) = setup_workdir().await;
        std::fs::write(
            dir.path().join("wikis/alice/bologna.md"),
            "# bologna\nalice's city page\n",
        )
        .unwrap();
        let fact = fact_index::NewFact {
            subject_external: None,
            slot: None,
            slot_value: None,
            authored_refs: Vec::new(),
            fact_id: FactId::parse("018f1234-5678-7abc-9def-00000000f002").unwrap(),
            wiki_id: "alice".to_owned(),
            source_path: "wikis/alice/bologna.md".to_owned(),
            region_start: None,
            region_end: None,
            text: "alice lives in Bologna".to_owned(),
            embedding: vec![0.9, -0.3, 0.2, -0.1],
            subject_id: Principal::User("alice".into()),
            allow_ids: Vec::new(),
            sender_id: None,
            fact_type: Some("bio".to_owned()),
            topics: Vec::new(),
            valid_from: None,
            valid_to: None,
            salience: None,
            target_page: None,
            style: None,
            source_ref: None,
        };
        fact_index::insert(&pool, &fact).await.expect("insert fact");

        let llm = FakeLlmBackend::new("fake", "{\"intent\":\"recall\"}");
        let mut request = req("what do you know about me?", "alice");
        request.metadata.recall = RecallDepth::Light;
        let policy = IngestPolicy::default();
        let resp = wiki_ingest_message(
            &pool,
            &tree,
            fake_embedder(),
            &llm,
            Some(&PanickingLlm),
            request,
            &policy,
        )
        .await
        .expect("ingest");
        assert_eq!(resp.intent, IntentKind::Recall);
        let snippet = resp.context_snippet.expect("recall block present");
        assert!(
            !snippet.contains(HDR_NAVIGATED_PAGES),
            "the walk is the one thing a light turn drops: {snippet}"
        );
        assert!(
            snippet.contains("alice lives in Bologna"),
            "the flat hits are untouched, so the turn still answers: {snippet}"
        );
        drop(dir);
    }

    /// The wire tokens, and the refusal that keeps a typo from putting a
    /// latency-bound consumer back on the deep path without telling it.
    #[test]
    fn recall_depth_round_trips_its_wire_tokens() {
        assert_eq!(RecallDepth::parse("full"), Some(RecallDepth::Full));
        assert_eq!(RecallDepth::parse("light"), Some(RecallDepth::Light));
        assert_eq!(RecallDepth::default(), RecallDepth::Full);
        assert_eq!(RecallDepth::parse("ligth"), None);
        assert_eq!(RecallDepth::parse(""), None);
    }

